calc.mjs.text:
// Sales export -> journal, any platform. Drop the CSV you have; this works out which of fifteen
// platforms wrote it (Airbnb, Amazon, eBay, Etsy, Fiverr, Gumroad, KDP, Ko-fi/Buy Me a Coffee/Teachable, Paddle, Patreon/Lemon Squeezy, PayPal, Shopify, Square, Stripe, Upwork) by running each
// platform's own reader over it and keeping the one that understands the most rows, then hands back
// that engine's journals. The readers are unmodified copies of the per-platform tools in this
// portfolio, so a fix to one is a copy away from the hub; detect.test.mjs feeds every engine's own
// sample report to the hub and fails if the wrong platform wins.
import * as airbnb from "./engines/airbnb.mjs";
import * as amazon from "./engines/amazon.mjs";
import * as ebay from "./engines/ebay.mjs";
import * as etsy from "./engines/etsy.mjs";
import * as fiverr from "./engines/fiverr.mjs";
import * as gumroad from "./engines/gumroad.mjs";
import * as kdp from "./engines/kdp.mjs";
import * as kofi from "./engines/kofi.mjs";
import * as paddle from "./engines/paddle.mjs";
import * as patreon from "./engines/patreon.mjs";
import * as paypal from "./engines/paypal.mjs";
import * as shopify from "./engines/shopify.mjs";
import * as square from "./engines/square.mjs";
import * as stripe from "./engines/stripe.mjs";
import * as upwork from "./engines/upwork.mjs";

export const PLATFORMS = [
  { id: "airbnb", label: "Airbnb host transaction history", engine: airbnb },
  { id: "amazon", label: "Amazon settlement report", engine: amazon },
  { id: "ebay", label: "eBay Transaction report", engine: ebay },
  { id: "etsy", label: "Etsy payment account statement", engine: etsy },
  { id: "fiverr", label: "Fiverr earnings history", engine: fiverr },
  { id: "gumroad", label: "Gumroad sales export", engine: gumroad },
  { id: "kdp", label: "Amazon KDP royalty report", engine: kdp },
  { id: "kofi", label: "Ko-fi, Buy Me a Coffee or Teachable transactions export", engine: kofi },
  { id: "paddle", label: "Paddle transactions export", engine: paddle },
  { id: "patreon", label: "Patreon or Lemon Squeezy earnings export", engine: patreon },
  { id: "paypal", label: "PayPal Activity report", engine: paypal },
  { id: "shopify", label: "Shopify Payments payout transactions", engine: shopify },
  { id: "square", label: "Square Transactions export", engine: square },
  { id: "stripe", label: "Stripe payout reconciliation report", engine: stripe },
  { id: "upwork", label: "Upwork transaction history", engine: upwork },
];
// Header words only that platform's export carries. A boost, not a requirement: real exports drift,
// and the generic readers (Gumroad, Shopify) will happily parse a Stripe file as a worse fit, so the
// signature is what breaks that tie while a drifted header still falls back to row counts.
const SIGNATURES = {
  airbnb: ["confirmation code", "arriving by date"],
  amazon: ["settlement-id", "amount-description"],
  ebay: ["transaction creation date", "payout currency"],
  etsy: ["fees & taxes", "fees-&-taxes"],
  fiverr: ["date,order id,type", "order id,type,description"],
  gumroad: ["sale id", "purchase id"],
  kdp: ["asin/isbn", "printing cost", "kenp"],
  kofi: ["transactiontype", "datetime (utc)"],
  paddle: ["paddle fee", "billed at"],
  patreon: ["pledge amount", "platform fee"],
  paypal: ["balance impact", "transaction id,item title"],
  shopify: ["payout status", "automatic payout"],
  square: ["total collected", "gross sales"],
  stripe: ["automatic_payout_id", "reporting_category", "balance_transaction_id"],
  upwork: ["ref id", "amount in local currency"],
};
const signatureBoost = (id, text) => {
  const head = String(text).split(/\r?\n/).slice(0, 40).join("\n").toLowerCase();
  return SIGNATURES[id].some((t) => head.includes(t)) ? 400 : 0;
};
export const platform = (id) => PLATFORMS.find((p) => p.id === id);

const REJECTED = /does not look like|file is empty|no header/i;

// How well did this platform's reader understand the file? A reader that refuses the header scores
// nothing; otherwise rows it kept and journals it could build count for, unexplained errors against.
export function score(r) {
  if (r.findings.some((f) => f.severity === "error" && REJECTED.test(f.title))) return 0;
  const rows = r.summary.rows || 0;
  if (!rows) return 0;
  const errors = r.findings.filter((f) => f.severity === "error").length;
  const agreed = r.reconciliation.filter((x) => x.agrees === true || x.agree === true).length;
  return Math.max(1, rows * 10 + r.journals.length * 5 + agreed * 20 - errors * 15);
}

export function detect(text, opts = {}) {
  const ranked = PLATFORMS.map((p) => {
    const result = p.engine.validate(text, { ...opts, mapping: undefined });
    const base = score(result);
    return { id: p.id, label: p.label, score: base ? base + signatureBoost(p.id, text) : 0 };
  }).sort((a, b) => b.score - a.score);
  const best = ranked[0];
  if (!best || best.score <= 0) return { id: null, ranked, confident: false };
  const runnerUp = ranked[1];
  return { id: best.id, ranked, confident: !runnerUp || runnerUp.score < best.score * 0.6 };
}

// Run the reader for `id`, or the detected one. `mapping` is parsed by that platform's own parser.
export function convert(text, opts = {}) {
  const d = opts.platform && opts.platform !== "auto" ? { id: opts.platform, ranked: [], confident: true, forced: true } : detect(text, opts);
  if (!d.id) {
    return { detection: d, platform: null, result: null, findings: [{ severity: "error", title: "Could not tell which platform wrote this file", detail: "None of the fifteen readers recognised the header row. Choose the platform from the list, or open the single-platform tool for the export you have.", line: 0 }] };
  }
  const p = platform(d.id);
  const { platform: _drop, ...rest } = opts;
  const result = p.engine.validate(text, rest);
  return { detection: d, platform: p, result, findings: result.findings };
}

export const parseMapping = (id, text) => platform(id).engine.parseMapping(text);
export const mappingText = (id, mapping) => platform(id).engine.mappingText(mapping);
export const defaultMapping = (id) => platform(id).engine.defaultMapping();
export const sampleReport = (id) => platform(id).engine.sampleReport();
export const sampleBrokenReport = (id) => platform(id).engine.sampleBrokenReport();
export const money = gumroad.money;
export const decodeBuffer = gumroad.decodeBuffer;
export const toXeroJournalCsv = (id, j, o) => platform(id).engine.toXeroJournalCsv(j, o);
export const toQboJournalCsv = (id, j, o) => platform(id).engine.toQboJournalCsv(j, o);
export const toIif = (id, j, o) => platform(id).engine.toIif(j, o);
export const journalsCsv = (id, j, o) => platform(id).engine.journalsCsv(j, o);
export const findingsCsv = (id, r) => platform(id).engine.findingsCsv(r);

engines/airbnb.mjs.text:
// Airbnb host transaction history -> accounting journal.
//
// Airbnb pays hosts a net deposit that hides the nightly rate, the cleaning fee, Airbnb's host service
// fee, cancellations, resolution adjustments and any tax Airbnb pays across for the host to remit.
// Bookkeepers need those split out, in the month they belong to. This module reads the Transaction
// history CSV (Airbnb > Menu > Earnings > Transaction history > Download CSV), splits every reservation
// into rental income, cleaning income, host fees and refunds, books pass-through tax as a liability and
// adjustments as their own line, compares the rows to the payouts the file states, and writes balanced
// journals for Xero, QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV.
//
// The CSV's column names, its type labels and each importer's layout are from memory of public Airbnb and
// accounting help documents; no real Airbnb export and no live Xero or QuickBooks import was available when
// this was written. Columns are matched by several aliases, a reservation whose parts do not add to its
// amount is flagged, and a row no rule explains is never dropped: it lands in an "uncategorised" line and is
// reported, so the journal still equals the file.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Rental income (nightly rate, gross)", account: "Airbnb Rental Income" },
  cleaning: { label: "Cleaning fees charged to guests", account: "Airbnb Cleaning Fee Income" },
  refunds: { label: "Cancellations and refunds to guests", account: "Airbnb Refunds" },
  fees: { label: "Airbnb host service fees and fast pay fees", account: "Airbnb Host Fees" },
  tax: { label: "Occupancy tax Airbnb paid you to remit (liability)", account: "Occupancy Tax Payable" },
  adjustments: { label: "Resolution adjustments, credits and other Airbnb items", account: "Airbnb Adjustments" },
  cohost: { label: "Co-host payouts", account: "Co-Host Fees" },
  uncategorised: { label: "Uncategorised Airbnb items", account: "Airbnb Uncategorised" },
  clearing: { label: "Airbnb clearing (matches the payout deposits)", account: "Airbnb Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const GROUP = "Airbnb earnings";

// Airbnb's file has no payout ID on a reservation, so the whole file is one group: every non-payout row
// is summed, and every row typed "Payout" states a deposit. The two differ by whatever is still waiting
// to be paid (or was paid from before the file starts); that difference is what clearing holds.
// opts.basis: "paid" (default) places a reservation in the month of its transaction date; "checkin"
// places it in the month of its start date.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^\uFEFF/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose an Airbnb transaction history CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    date: col("date", "transaction-date"),
    type: col("type", "transaction-type"),
    code: col("confirmation-code", "confirmation", "reservation-code"),
    start: col("start-date", "check-in", "checkin-date"),
    listing: col("listing", "property"),
    details: col("details", "description"),
    currency: col("currency"),
    amount: col("amount"),
    paidOut: col("paid-out", "payout-amount"),
    fee: col("service-fee", "host-fee", "host-service-fee"),
    fast: col("fast-pay-fee", "fast-payout-fee"),
    cleaning: col("cleaning-fee"),
    gross: col("gross-earnings", "gross"),
    occ: col("occupancy-taxes", "occupancy-tax"),
  };
  const missing = [];
  if (I.type < 0) missing.push("type");
  if (I.amount < 0 && I.paidOut < 0) missing.push("amount");
  if (I.date < 0) missing.push("date");
  if (missing.length) {
    add("error", "This does not look like an Airbnb transaction history", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Airbnb open Menu > Earnings > Transaction history, choose the date range and Download CSV, then paste the whole file here.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const s = { id: GROUP, effective: null, stated: null, currency: "", rows: [] };
  let rows = 0, payoutRows = 0, occTotal = 0, occRows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const type = get(cells, "type"), tl = type.toLowerCase();
    const rid = get(cells, "code") || `line ${i + 1}`;
    const date = parseDate(get(cells, "date"), opts.dateOrder);
    const money_ = (k) => { const v = parseAmount(get(cells, k)); return v === null ? 0 : v; };
    const bad = ["amount", "paidOut", "fee", "fast", "cleaning", "gross", "occ"].some((k) => Number.isNaN(parseAmount(get(cells, k))));
    if (bad) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so the file will not add up.", i + 1); continue; }
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", "Mixed currencies in the export", `${cur} row among ${s.currency} rows. Journals assume one currency.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    if (date && (!s.effective || date > s.effective)) s.effective = date;
    if (/^payout$|^payout\b/.test(tl) && !/co-?host/.test(tl)) {
      const v = I.paidOut >= 0 && get(cells, "paidOut") !== "" ? money_("paidOut") : money_("amount");
      s.stated = (s.stated || 0) + Math.abs(v); payoutRows++;
      continue;
    }
    const net = money_("amount");
    const parts = [];
    const push = (k, amt) => { if (amt) parts.push({ k, amt }); };
    let created = date, item = get(cells, "listing") || type;
    if (/reservation/.test(tl) && !/pass/.test(tl)) {
      const gross = money_("gross"), cleaning = money_("cleaning"), fee = Math.abs(money_("fee")) + Math.abs(money_("fast"));
      const sign = gross < 0 ? -1 : 1;
      if (opts.basis === "checkin") created = parseDate(get(cells, "start"), opts.dateOrder) || date;
      if (I.gross < 0) { push("uncategorised", net); add("error", "No Gross earnings column", `${rid} cannot be split without it; it is journalled to uncategorised for ${money(net)}.`, i + 1); }
      else {
        if (gross < 0) push("refunds", gross); else { push("sales", gross - cleaning); push("cleaning", cleaning); }
        push("fees", -sign * fee);
        const residual = net - parts.reduce((a, p) => a + p.amt, 0);
        if (residual !== 0) { push("uncategorised", residual); add("error", `Parts do not add up to the amount on ${rid}`, `Gross earnings ${money(gross)} less fees ${money(sign * fee)} = ${money(gross - sign * fee)}, but the row's Amount is ${money(net)}. The ${money(residual)} difference is journalled to "uncategorised"; check the file was not edited, or whether tax was paid in the Amount.`, i + 1); }
      }
      const occ = money_("occ");
      if (occ) { occTotal += occ; occRows++; }
    } else if (/pass.?through/.test(tl) || (/tax/.test(tl) && !/withh/.test(tl))) push("tax", net);
    else if (/co-?host/.test(tl)) push("cohost", net);
    else if (/adjust|resolution|credit|referral|reimburs|compensation/.test(tl)) push("adjustments", net);
    else { push("uncategorised", net); add("warning", `Unrecognised type "${type}" on ${rid}`, "It is journalled to uncategorised so the journal still equals the file.", i + 1); }
    if (net === 0 && !parts.length) continue;
    s.rows.push({ line: i + 1, id: rid, item, gross: parts.filter((p) => p.k === "sales" || p.k === "cleaning").reduce((a, p) => a + p.amt, 0), fee: -(parts.find((p) => p.k === "fees")?.amt || 0), net, refunded: parts.some((p) => p.k === "refunds"), parts, created });
    rows++;
  }
  if (occRows) add("info", `${occRows} reservation${occRows === 1 ? "" : "s"} show occupancy taxes of ${money(occTotal, s.currency || "USD")} that Airbnb collected and remitted`, "That tax is not in your Amount, so it is not journalled. Pass Through Tax rows (tax Airbnb paid across for you to remit) are booked to the tax payable account.", 0);
  if (!rows && !payoutRows) add("error", "No transaction rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected) && s.stated === null) s.stated = opts.expected;
  const payouts = s.rows.length || s.stated !== null ? [s] : [];
  return { payouts, findings, summary: { rows, payouts: payoutRows } };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month; "none" one journal dated the file's last date.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.stated === null) findings.push({ severity: "warning", title: "The file has no Payout rows and no deposit was typed in", detail: `The rows add up to ${money(sum, cur)}. Include Payout rows in the date range, or enter the total deposited in the box above, to compare.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "warning", title: `Rows add up to ${money(sum, cur)} but payouts in the file total ${money(s.stated, cur)}`, detail: `Difference ${money(sum - s.stated, cur)}. ${sum > s.stated ? "That much is earned but not yet paid out (or the payout falls after the file's end date); Airbnb clearing will hold it until the deposit arrives." : "Payouts include money from reservations before the file starts. Extend the date range back to the first unpaid reservation."} If neither explains it, rows are missing from the paste.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const p of r.parts) add(p.k, p.amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} had no usable date`, detail: "They were placed in the file's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `The file spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Airbnb clearing, so every month's income and fees land in the month they belong to. Bank deposits then clear all of them.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Airbnb earnings ${ym}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Airbnb earnings ${ym}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the file. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

// "agrees" is null when the file states no payout; true when payouts equal the rows; false when they differ
// (usually timing, which the findings explain).
export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const docNo = (journals, j) => `AIRBNB-${j.period}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Date", "Arriving by date", "Type", "Confirmation code", "Start date", "End date", "Nights", "Guest", "Listing", "Details", "Currency", "Amount", "Paid out", "Service fee", "Fast pay fee", "Cleaning fee", "Gross earnings", "Occupancy taxes"];

// stays: [date, code, nights, gross, cleaning, fee, start]. A negative gross is a cancellation reversal.
// Occupancy taxes are shown on the row but are not in the Amount (Airbnb remits them).
export function buildReport({ currency = "USD", stays, extra = [], payouts = [], totalOverride }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const us = (iso) => { const [y, m, dd] = iso.split("-"); return `${m}/${dd}/${y}`; };
  const out = [HEAD.join(",")];
  for (const [date, code, nights, gross, cleaning, fee, start] of stays) {
    const net = typeof gross === "string" ? gross : (gross - fee).toFixed(2);
    out.push([us(date), "", "Reservation", code, us(start || date), "", nights, "Guest", "Lakeview cabin", "", currency, net, "", fee.toFixed(2), "0.00", cleaning.toFixed(2), typeof gross === "string" ? gross : gross.toFixed(2), "12.00"].map(csv).join(","));
  }
  for (const [date, type, amount] of extra) out.push([us(date), "", type, "", "", "", "", "", "Lakeview cabin", "", currency, amount.toFixed(2), "", "", "", "", "", ""].map(csv).join(","));
  for (const [date, amount] of payouts) out.push([us(date), "", "Payout", "", "", "", "", "", "", "to bank", currency, "", (totalOverride ?? amount).toFixed(2), "", "", "", "", ""].map(csv).join(","));
  return out.join("\n") + "\n";
}

const SAMPLE_STAYS = [
  ["2026-09-12", "HMAB1C2D3E", 3, 540.00, 90.00, 16.20, "2026-09-12"],
  ["2026-09-26", "HMAB4F5G6H", 5, 910.00, 90.00, 27.30, "2026-09-26"],
  ["2026-10-02", "HMAB7J8K9L", 2, 360.00, 90.00, 10.80, "2026-10-02"],
  ["2026-10-04", "HMABMN0P1Q", 4, -420.00, 0.00, -12.60, "2026-10-04"],
];
const SAMPLE_EXTRA = [["2026-10-03", "Pass Through Tax", 38.40], ["2026-10-03", "Resolution Adjustment", -45.00]];
const stayNet = (st) => st.reduce((a, r) => a + Math.round((r[3] - r[5]) * 100), 0);
const SAMPLE_PAID = (stayNet(SAMPLE_STAYS) + Math.round(38.4 * 100) - 4500) / 100;
export const sampleReport = () => buildReport({ stays: SAMPLE_STAYS, extra: SAMPLE_EXTRA, payouts: [["2026-10-05", SAMPLE_PAID]] });
// The same export after a hand edit: one reservation whose Amount does not match its parts, one amount that
// is not a number, and an unrecognised row type.
export function sampleBrokenReport() {
  const stays = SAMPLE_STAYS.slice(0, 3).concat([["2026-10-04", "HMABBAD001", 2, "12..5", 0, 0, "2026-10-04"]]);
  const csv = buildReport({ stays, extra: [...SAMPLE_EXTRA, ["2026-10-04", "Mystery Bonus", 25.00]], payouts: [["2026-10-05", SAMPLE_PAID]] });
  return csv.replace("349.20", "339.20");
}

engines/amazon.mjs.text:
// Amazon seller settlement report -> accounting journal.
//
// Amazon pays a marketplace seller a net deposit every settlement period. That one
// deposit hides sales, shipping income, tax, promotions, refunds, referral and FBA
// fees, storage, advertising and reserves. Bookkeepers need those split out, and a
// settlement that straddles a month end split in two. This module reads the
// "Flat File V2" settlement report (tab-delimited text, or the same columns as CSV),
// proves the rows add up to the deposit Amazon states, groups them into categories,
// and writes balanced journals for Xero, QuickBooks Online, QuickBooks Desktop (IIF)
// and a plain CSV.
//
// The report layout, the amount-type / amount-description names and each importer's
// column layout are from memory of public seller-help and import-help documents; no
// real settlement file and no live Xero or QuickBooks import was available when this
// was written. Rows no rule recognises are never dropped: they land in an
// "uncategorised" line and are reported, so the journal still equals the deposit.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Product sales", account: "Amazon Sales" },
  shipping: { label: "Shipping income", account: "Amazon Shipping Income" },
  promo: { label: "Promotional rebates", account: "Amazon Promotional Rebates" },
  refunds: { label: "Refunds and returns", account: "Amazon Refunds" },
  tax: { label: "Sales tax (collected and facilitator-withheld)", account: "Sales Tax Payable" },
  referral: { label: "Referral fees", account: "Amazon Referral Fees" },
  fba: { label: "FBA fulfilment fees", account: "Amazon FBA Fees" },
  storage: { label: "FBA storage and inventory fees", account: "Amazon Storage Fees" },
  advertising: { label: "Advertising", account: "Amazon Advertising" },
  subscription: { label: "Seller subscription", account: "Amazon Subscription Fees" },
  reimbursements: { label: "FBA reimbursements", account: "Amazon Reimbursements" },
  otherfees: { label: "Other selling fees", account: "Amazon Other Fees" },
  reserve: { label: "Reserve held / released", account: "Amazon Reserve" },
  uncategorised: { label: "Uncategorised Amazon items", account: "Amazon Uncategorised" },
  clearing: { label: "Amazon clearing (matches the bank deposit)", account: "Amazon Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO, DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const REQUIRED = ["settlement-id", "amount"];

export function parseSettlements(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  if (first < 0) { add("error", "The file is empty", "Paste or choose a settlement report."); return { settlements: [], findings, summary: { rows: 0, settlements: 0 } }; }
  const d = (lines[first].match(/\t/g) || []).length >= (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (n) => head.indexOf(n);
  const missing = REQUIRED.filter((n) => col(n) < 0);
  if (missing.length) {
    add("error", "This does not look like a settlement report", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. Download the "Flat File V2" settlement report from Seller Central > Reports > Payments > All Statements.`, first + 1);
    return { settlements: [], findings, summary: { rows: 0, settlements: 0 } };
  }
  const I = Object.fromEntries(["settlement-id", "settlement-start-date", "settlement-end-date", "deposit-date", "total-amount", "currency", "transaction-type", "order-id", "amount-type", "amount-description", "amount", "posted-date", "sku", "marketplace-name"].map((n) => [n, col(n)]));
  const get = (cells, n) => (I[n] >= 0 ? (cells[I[n]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, start: null, end: null, deposit: null, total: null, currency: "", rows: [], summaryRows: 0 }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const id = get(cells, "settlement-id");
    if (!id) { add("warning", "Row has no settlement ID", "It was skipped.", i + 1); continue; }
    const s = bucket(id);
    const type = get(cells, "transaction-type"), amt = get(cells, "amount"), tot = get(cells, "total-amount");
    if (!type && !amt && tot) { // the summary row
      s.summaryRows++;
      if (s.summaryRows > 1) add("warning", `Settlement ${id} has more than one summary row`, "The first one is used.", i + 1);
      else {
        const t = parseAmount(tot);
        if (Number.isNaN(t)) add("error", `Total amount "${tot}" is not a number`, `Settlement ${id}.`, i + 1); else s.total = t;
        s.start = parseDate(get(cells, "settlement-start-date"), opts.dateOrder);
        s.end = parseDate(get(cells, "settlement-end-date"), opts.dateOrder);
        s.deposit = parseDate(get(cells, "deposit-date"), opts.dateOrder);
        s.currency = get(cells, "currency");
      }
      continue;
    }
    const a = parseAmount(amt);
    if (a === null) { if (type || get(cells, "amount-description")) add("warning", "Row has no amount", `${type} / ${get(cells, "amount-description")} was skipped.`, i + 1); continue; }
    if (Number.isNaN(a)) { add("error", `Amount "${amt}" is not a number`, "The row is left out, so this settlement will not add up to its deposit.", i + 1); continue; }
    const cur = get(cells, "currency");
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in settlement ${id}`, `${cur} row among ${s.currency} rows.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    s.rows.push({ line: i + 1, type, orderId: get(cells, "order-id"), sku: get(cells, "sku"), amountType: get(cells, "amount-type"), desc: get(cells, "amount-description"), amount: a, posted: parseDate(get(cells, "posted-date"), opts.dateOrder), marketplace: get(cells, "marketplace-name") });
    rows++;
  }
  const settlements = [...byId.values()].filter((s) => s.rows.length || s.summaryRows);
  if (!settlements.length) add("error", "No settlement rows found", "The header was read but there were no data rows.");
  return { settlements, findings, summary: { rows, settlements: settlements.length } };
}

// ---- categorising ------------------------------------------------------------

export function categoryOf(row) {
  const type = row.type.toLowerCase(), at = row.amountType.toLowerCase(), desc = row.desc.toLowerCase();
  const refund = /refund|chargeback/.test(type);
  if (/tax|vat|gst/.test(desc) && !/taxable/.test(desc)) return "tax";
  if (/tax/.test(at)) return "tax";
  if (at === "promotion" || /^promotion|promotional/.test(desc)) return "promo";
  if (at === "itemfees") {
    if (/commission/.test(desc)) return "referral";
    if (/fba|fulfil|weightbased|pickandpack|perunit|perorder/.test(desc)) return "fba";
    return "otherfees";
  }
  if (at === "itemprice" || /^(principal|shipping|giftwrap)$/.test(desc)) {
    if (refund) return "refunds";
    if (/^shipping/.test(desc)) return "shipping";
    return "sales";
  }
  if (/cost of advertising|advertising/.test(desc) || /advertising/.test(type)) return "advertising";
  if (/subscription/.test(desc)) return "subscription";
  if (/reimburs/.test(desc) || /reimburs/.test(type)) return "reimbursements";
  if (/reserve/.test(desc)) return "reserve";
  if (/storage|long.?term/.test(desc)) return "storage";
  if (/disposal|removal|inbound|placement|labell?ing|prep service|return processing|fba/.test(desc)) return "storage";
  return "uncategorised";
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a settlement touches.
export function buildJournals(settlements, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of settlements) {
    const sum = s.rows.reduce((a, r) => a + r.amount, 0);
    const endDate = s.end || [...s.rows].map((r) => r.posted).filter(Boolean).sort().pop() || null;
    const cur = s.currency || "USD";
    if (s.total === null) findings.push({ severity: "warning", title: `Settlement ${s.id} has no summary row`, detail: "The deposit Amazon states could not be checked against the rows.", line: 0 });
    else if (s.total !== sum) findings.push({ severity: "error", title: `Settlement ${s.id}: rows add up to ${money(sum, cur)} but the deposit is ${money(s.total, cur)}`, detail: `Off by ${money(s.total - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0, outside = 0;
    for (const r of s.rows) {
      let ym = r.posted ? r.posted.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.posted) undated++;
      if (r.posted && s.start && s.end && (r.posted < s.start || r.posted > s.end)) outside++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const cat = categoryOf(r), m = periods.get(ym);
      const e = m.get(cat) || { net: 0, count: 0 };
      e.net += r.amount; e.count++; m.set(cat, e);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in settlement ${s.id} had no posted date`, detail: "They were placed in the settlement's final month.", line: 0 });
    if (outside) findings.push({ severity: "info", title: `${outside} row${outside === 1 ? "" : "s"} in settlement ${s.id} posted outside its start and end dates`, detail: "Amazon sometimes books late adjustments this way. They are journalled in the month they posted.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Settlement ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Amazon clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.total === null ? "the full amount" : money(s.total, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Settlement ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ settlementId: s.id, period: ym, date, deposit: s.deposit, currency: cur, narration: `Amazon settlement ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => categoryOf(r) === "uncategorised");
    if (unknown.length) findings.push({ severity: "warning", title: `Settlement ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.desc || r.type))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the deposit. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(settlements) {
  return settlements.flatMap((s) => s.rows.filter((r) => categoryOf(r) === "uncategorised").map((r) => ({ settlement: s.id, ...r })));
}

export function reconciliation(settlements, journals) {
  return settlements.map((s) => {
    const js = journals.filter((j) => j.settlementId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.deposit, currency: s.currency || "USD", stated: s.total, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.total === null ? null : s.total === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parseSettlements(text, opts);
  const b = buildJournals(p.settlements, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { settlements: p.settlements, journals: b.journals, findings, reconciliation: reconciliation(p.settlements, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([`${j.settlementId}${j.period && j.period !== "undated" && journalsOf(journals, j.settlementId) > 1 ? "-" + j.period : ""}`, fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}
const journalsOf = (journals, id) => journals.filter((j) => j.settlementId === id).length;

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(`${j.settlementId}${journalsOf(journals, j.settlementId) > 1 ? "-" + j.period : ""}`);
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["settlement", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.settlementId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["settlement-id", "settlement-start-date", "settlement-end-date", "deposit-date", "total-amount", "currency", "transaction-type", "order-id", "merchant-order-id", "adjustment-id", "shipment-id", "marketplace-name", "amount-type", "amount-description", "amount", "fulfillment-id", "posted-date", "posted-date-time", "order-item-code", "merchant-order-item-id", "merchant-adjustment-item-id", "sku", "quantity-purchased", "promotion-id"];

export function buildReport({ id = "12345678901", start = "2026-09-24", end = "2026-10-08", deposit = "2026-10-09", currency = "USD", items, totalOverride }) {
  const sum = items.reduce((a, r) => a + Math.round(r[5] * 100), 0);
  const total = totalOverride ?? sum / 100;
  const row = (o) => HEAD.map((h) => o[h] ?? "").join("\t");
  const out = [HEAD.join("\t"), row({ "settlement-id": id, "settlement-start-date": `${start} 00:00:00 UTC`, "settlement-end-date": `${end} 00:00:00 UTC`, "deposit-date": `${deposit} 00:00:00 UTC`, "total-amount": total.toFixed(2), currency })];
  for (const [type, order, at, desc, posted, amt, sku] of items)
    out.push(row({ "settlement-id": id, currency, "transaction-type": type, "order-id": order, "marketplace-name": "Amazon.com", "amount-type": at, "amount-description": desc, amount: typeof amt === "string" ? amt : amt.toFixed(2), "posted-date": posted, sku: sku || "" }));
  return out.join("\n") + "\n";
}

const O1 = "111-0000001-0000001", O2 = "111-0000002-0000002";
const SAMPLE_ITEMS = [
  ["Order", O1, "ItemPrice", "Principal", "2026-09-28", 129.99, "WIDGET-1"],
  ["Order", O1, "ItemPrice", "Tax", "2026-09-28", 9.10, "WIDGET-1"],
  ["Order", O1, "ItemPrice", "Shipping", "2026-09-28", 4.99, "WIDGET-1"],
  ["Order", O1, "ItemPrice", "ShippingTax", "2026-09-28", 0.35, "WIDGET-1"],
  ["Order", O1, "Promotion", "Principal", "2026-09-28", -5.00, "WIDGET-1"],
  ["Order", O1, "ItemFees", "Commission", "2026-09-28", -19.50, "WIDGET-1"],
  ["Order", O1, "ItemFees", "FBAPerUnitFulfillmentFee", "2026-09-28", -3.22, "WIDGET-1"],
  ["Order", O1, "ItemWithheldTax", "MarketplaceFacilitatorTax-Principal", "2026-09-28", -9.10, "WIDGET-1"],
  ["Order", O1, "ItemWithheldTax", "MarketplaceFacilitatorTax-Shipping", "2026-09-28", -0.35, "WIDGET-1"],
  ["Order", O2, "ItemPrice", "Principal", "2026-10-02", 449.99, "GADGET-2"],
  ["Order", O2, "ItemPrice", "Tax", "2026-10-02", 31.50, "GADGET-2"],
  ["Order", O2, "ItemFees", "Commission", "2026-10-02", -67.50, "GADGET-2"],
  ["Order", O2, "ItemFees", "FBAPerUnitFulfillmentFee", "2026-10-02", -5.40, "GADGET-2"],
  ["Order", O2, "ItemWithheldTax", "MarketplaceFacilitatorTax-Principal", "2026-10-02", -31.50, "GADGET-2"],
  ["Refund", O1, "ItemPrice", "Principal", "2026-10-04", -129.99, "WIDGET-1"],
  ["Refund", O1, "ItemPrice", "Tax", "2026-10-04", -9.10, "WIDGET-1"],
  ["Refund", O1, "ItemWithheldTax", "MarketplaceFacilitatorTax-Principal", "2026-10-04", 9.10, "WIDGET-1"],
  ["Refund", O1, "ItemFees", "RefundCommission", "2026-10-04", 3.90, "WIDGET-1"],
  ["other-transaction", "", "other-transaction", "Subscription Fee", "2026-09-25", -39.99],
  ["other-transaction", "", "other-transaction", "Storage Fee", "2026-10-03", -12.40],
  ["other-transaction", "", "other-transaction", "Cost of Advertising", "2026-10-05", -85.00],
  ["other-transaction", "", "other-transaction", "Current Reserve Amount", "2026-10-08", -100.00],
  ["other-transaction", "", "other-transaction", "Previous Reserve Amount Balance", "2026-10-08", 100.00],
];

export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS });
// The same report after a hand edit: a row dropped from the paste, so the deposit no longer
// agrees, plus one adjustment no rule recognises and one amount that is not a number.
export function sampleBrokenReport() {
  const items = SAMPLE_ITEMS.filter((r) => r[3] !== "Cost of Advertising");
  items.push(["other-transaction", "", "other-transaction", "Mystery Adjustment", "2026-10-06", 1.23], ["other-transaction", "", "other-transaction", "Subscription Fee", "2026-10-06", "12..5"]);
  return buildReport({ items, totalOverride: SAMPLE_ITEMS.reduce((a, r) => a + Math.round(r[5] * 100), 0) / 100 });
}

engines/ebay.mjs.text:
// eBay Transaction report -> accounting journal.
//
// eBay pays out a net deposit that hides item sales, shipping income, seller-collected tax, final value
// fees, Promoted Listings, insertion and store fees, shipping labels, refunds and disputes. Bookkeepers need
// those split out, and a payout that straddles a month end split in two. This module reads the Transaction
// report (Seller Hub > Payments > Reports > Downloads), proves each payout's rows add up to the Payout row,
// groups them into categories and writes balanced journals for Xero, QuickBooks Online, QuickBooks Desktop
// (IIF) and a plain CSV.
//
// The report layout, the Type and Description wording and each importer's column layout are from memory of
// public eBay and accounting help documents; no real eBay report and no live Xero or QuickBooks import was
// available when this was written. Rows no rule recognises are never dropped: they land in an
// "uncategorised" line and are reported, so the journal still equals the net.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Item sales (gross)", account: "eBay Sales" },
  shipping: { label: "Shipping and handling charged to buyers", account: "eBay Shipping Income" },
  tax: { label: "Sales tax collected by you (liability)", account: "eBay Sales Tax Payable" },
  refunds: { label: "Refunds", account: "eBay Refunds" },
  fees: { label: "Final value, international, performance and deposit fees", account: "eBay Fees" },
  ads: { label: "Promoted Listings and ad fees", account: "eBay Advertising" },
  listing: { label: "Insertion, listing upgrade and store subscription fees", account: "eBay Listing and Store Fees" },
  labels: { label: "Shipping labels bought on eBay", account: "eBay Shipping Labels" },
  disputes: { label: "Claims, disputes and chargebacks", account: "eBay Disputes" },
  other: { label: "Holds, reserves, transfers and adjustments", account: "eBay Adjustments" },
  uncategorised: { label: "Uncategorised eBay items", account: "eBay Uncategorised" },
  clearing: { label: "eBay clearing (matches the bank deposit)", account: "eBay Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

const UNPAID = "(not yet paid out)";
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };

// Returns YYYY-MM-DD or null. Accepts ISO, "Jun 1, 2026", "1 Jun 2026", DD.MM.YYYY and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim().replace(/^"|"$/g, "");
  if (!t || /^-+$/.test(t)) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})/)) && MONTHS[x[1].toLowerCase()]) [m, d, y] = [MONTHS[x[1].toLowerCase()], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})/)) && MONTHS[x[2].toLowerCase()]) [d, m, y] = [x[1], MONTHS[x[2].toLowerCase()], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

// Amounts: "--" and "" are nothing (null); currency symbols, "(1.00)" and thousands separators are read.
export function parseAmount(s) {
  let t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "" || /^-+$/.test(t)) return null;
  let neg = false;
  if (/^\(.*\)$/.test(t)) { neg = true; t = t.slice(1, -1); }
  t = t.replace(/[$€£]|USD|EUR|GBP|CAD|AUD/gi, "");
  if (t.startsWith("-")) { neg = !neg; t = t.slice(1); } else if (t.startsWith("+")) t = t.slice(1);
  let u = t;
  if (/^\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^\d+(\.\d+)?$/.test(u)) return NaN;
  const c = Math.round(parseFloat(u) * 100);
  return neg ? -c : c;
}

const FEE_COLUMNS = [["fvf-fixed", "final value fee - fixed", "final value fee – fixed", "final value fee fixed"], ["fvf-var", "final value fee - variable", "final value fee – variable", "final value fee variable"], ["nad", 'very high "not as described" fee', "very high 'not as described' fee", "very high not as described fee", "very high item not as described fee"], ["below", "below standard performance fee"], ["intl", "international fee"], ["deposit", "deposit processing fee"]];
const normHead = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/^"|"$/g, "").replace(/""/g, '"').replace(/\s+/g, " ");

// The report opens with a few metadata lines (name, seller, period) before the header, so the header is found, not assumed.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (!lines.some((l) => l.trim())) { add("error", "The file is empty", "Paste or choose an eBay Transaction report CSV."); return none; }
  const delim = (l) => ((l.match(/\t/g) || []).length > (l.match(/,/g) || []).length ? "\t" : ",");
  let first = -1;
  for (let i = 0; i < Math.min(lines.length, 30); i++) {
    const h = splitLine(lines[i], delim(lines[i])).map(normHead);
    if (h.includes("type") && h.includes("net amount")) { first = i; break; }
  }
  if (first < 0) { add("error", "This does not look like an eBay Transaction report", "No header row with the columns Type and Net amount was found in the first 30 lines. In Seller Hub open Payments > Reports > Downloads and download the Transaction report as CSV.", 1); return none; }
  const d = delim(lines[first]);
  const head = splitLine(lines[first], d).map(normHead);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    date: col("transaction creation date", "date", "transaction date"), type: col("type", "transaction type"), order: col("order number", "order id"), net: col("net amount", "net"),
    payout: col("payout id"), pdate: col("payout date"), currency: col("payout currency", "transaction currency"), tcur: col("transaction currency"), item: col("item id"), title: col("item title"),
    sub: col("item subtotal", "item price"), ship: col("shipping and handling", "shipping & handling", "postage and packaging"), stax: col("seller collected tax"), desc: col("description"), pstatus: col("payout status"),
  };
  const feeCols = FEE_COLUMNS.map((names) => col(...names)).filter((i) => i >= 0);
  if (I.date < 0) { add("error", "No Transaction creation date column", "The header has Type and Net amount but no date column, so rows cannot be assigned to months.", first + 1); return none; }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, effective: null, stated: null, currency: "", rows: [] }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    if (cells.length < 3) continue; // trailing summary lines
    const type = get(cells, "type"), tl = type.toLowerCase();
    const netS = get(cells, "net"), net = parseAmount(netS);
    if (net === null) { add("warning", "Row has no net amount", `${type || "row"} was skipped.`, i + 1); continue; }
    if (Number.isNaN(net)) { add("error", `Net amount "${netS}" is not a number`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const date = parseDate(get(cells, "date"), opts.dateOrder);
    if (!date) { add("error", `Date "${get(cells, "date")}" is not a date`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const num = (k) => parseAmount(get(cells, k));
    const sub = num("sub"), ship = num("ship"), stax = num("stax");
    const feeVals = feeCols.map((c) => parseAmount(cells[c] ?? ""));
    if ([sub, ship, stax, ...feeVals].some(Number.isNaN)) { add("error", "An amount column is not a number", `Row ${get(cells, "order") || i + 1} was left out.`, i + 1); continue; }
    // eBay shows fees as negatives; a credit is positive. Whatever the sign, the sum is what moved the net.
    const feeSum = feeVals.reduce((a, v) => a + (v ?? 0), 0);
    const pid = get(cells, "payout"), pidKey = !pid || /^-+$/.test(pid) ? UNPAID : pid;
    const s = bucket(pidKey);
    const cur = get(cells, "currency").toUpperCase(), tcur = get(cells, "tcur").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in payout ${pidKey}`, `${cur} row among ${s.currency} rows. Journals assume one currency per payout.`, i + 1);
    if (cur && tcur && cur !== tcur) add("warning", `Row ${get(cells, "order") || i + 1} was sold in ${tcur} but paid out in ${cur}`, "The Net amount is read as already converted to the payout currency; the exchange difference is not separated.", i + 1);
    if (cur && !s.currency) s.currency = cur;
    const eff = parseDate(get(cells, "pdate"), opts.dateOrder);
    if (eff && !s.effective) s.effective = eff;
    if (tl === "payout") { s.stated = (s.stated || 0) + Math.abs(net); continue; } // the deposit itself, not an activity row
    const row = { line: i + 1, id: get(cells, "order") || get(cells, "item"), type, desc: get(cells, "desc") || get(cells, "title"), net, date, sub, ship, stax, feeSum, hasItemCols: sub !== null || ship !== null || stax !== null };
    if (row.hasItemCols && (sub ?? 0) + (ship ?? 0) + (stax ?? 0) + feeSum !== net) add("error", `Item subtotal, shipping, tax and fees do not equal net on ${row.id || `line ${i + 1}`}`, `${money((sub ?? 0) + (ship ?? 0) + (stax ?? 0) + feeSum)} computed from the columns, but the row says ${money(net)}. The journal uses the net; check the file was not edited.`, i + 1);
    s.rows.push(row);
    rows++;
  }
  const payouts = [...byId.values()].filter((s) => s.rows.length || s.stated !== null);
  if (!payouts.length) add("error", "No rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    const real = payouts.filter((s) => s.id !== UNPAID);
    if (real.length === 1 && real[0].stated === null) real[0].stated = opts.expected;
    else if (real.length !== 1) add("info", "Expected deposit ignored", "It can only be applied when the file holds exactly one payout without a Payout row of its own.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- categorising ------------------------------------------------------------

// Type first, then the Description, because eBay files ads, listing fees and store fees all as "Other fee".
export function categoryOf(row) {
  const t = String(row.type || "").toLowerCase().trim(), d = String(row.desc || "").toLowerCase();
  if (t === "order" || t === "sale") return "sales";
  if (t === "refund" || (/^refund/.test(d) && t !== "other fee")) return "refunds";
  if (t === "shipping label" || /shipping label|postage label/.test(t)) return "labels";
  if (/^(claim|dispute|payment dispute|chargeback|case)/.test(t) || /chargeback|payment dispute/.test(d)) return "disputes";
  if (/promoted listing|promoted offsite|ad fee|advertis/.test(d)) return "ads";
  if (/insertion|listing fee|listing upgrade|store subscription|subscription/.test(d)) return "listing";
  if (/not as described|below standard|performance|international fee|final value|deposit processing|regulatory/.test(d)) return "fees";
  if (/^(hold|release|transfer|reserve|adjustment|credit|payout reversal|payout failure|charge|payment to)/.test(t) || /credit|reversal|adjust|reserve|hold/.test(d)) return "other";
  if (t === "other fee" || /fee/.test(t)) return "fees";
  return "uncategorised";
}

// A row's journal contribution as [category, signed cents] pairs that always sum to the row's net.
export function partsOf(row) {
  const cat = categoryOf(row);
  const out = [];
  if (cat === "sales" && row.hasItemCols) {
    if (row.sub) out.push(["sales", row.sub]);
    if (row.ship) out.push(["shipping", row.ship]);
    if (row.stax) out.push(["tax", row.stax]);
    if (row.feeSum) out.push(["fees", row.feeSum]);
    const rest = row.net - out.reduce((a, [, v]) => a + v, 0);
    if (rest) out.push(["sales", rest]);
    return out;
  }
  if (row.feeSum && cat === "sales") { out.push(["fees", row.feeSum]); out.push([cat, row.net - row.feeSum]); return out; }
  out.push([cat, row.net]);
  return out;
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.date).filter(Boolean).sort().pop() || null;
    if (s.id === UNPAID) findings.push({ severity: "warning", title: `${s.rows.length} row${s.rows.length === 1 ? "" : "s"} have no payout ID`, detail: "They are not yet paid out (or the report omits the payout column). They are journalled to eBay clearing as a separate group and will not match a bank deposit yet.", line: 0 });
    else if (s.stated === null) findings.push({ severity: "warning", title: `Payout ${s.id} has no payout row and no expected deposit`, detail: `The rows add up to ${money(sum, cur)}. Enter the deposit from your bank or eBay in the box above to check it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Payout ${s.id}: rows add up to ${money(sum, cur)} but the payout is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.date ? r.date.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.date) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const [k, amt] of partsOf(r)) add(k, amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in payout ${s.id} had no created date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Payout ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to eBay clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Payout ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `eBay payout ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => categoryOf(r) === "uncategorised");
    if (unknown.length) findings.push({ severity: "warning", title: `Payout ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.cat || r.desc))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => categoryOf(r) === "uncategorised").map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.id === UNPAID ? null : s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.id === UNPAID || s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Transaction creation date", "Type", "Order number", "Legacy order ID", "Buyer username", "Net amount", "Payout currency", "Payout date", "Payout ID", "Payout status", "Item ID", "Item title", "Quantity", "Item subtotal", "Shipping and handling", "Seller collected tax", "eBay collected tax", "Final Value Fee - fixed", "Final Value Fee - variable", '"Very high ""not as described"" fee"', "Below standard performance fee", "International fee", "Deposit processing fee", "Gross transaction amount", "Transaction currency", "Description"];
const MN = ["", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const ebayDate = (iso) => { const [y, m, d] = iso.split("-"); return `"${MN[+m]} ${+d}, ${y}"`; };
const amt = (n) => (n === undefined || n === null ? "--" : (n < 0 ? "-" : "") + Math.abs(n).toFixed(2));
const csvq = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));

// items: { date, type, order, sub, ship, tax, fixed, variable, intl, net, desc, title }. Fees are given as positive costs and written negative, as eBay does.
// A Payout row is added when `withPayoutRow`; eBay's own report carries one per payout, but a report cut by date may not.
export function buildReport({ id = "5000123456", effective = "2026-10-08", currency = "USD", items, withPayoutRow = true, totalOverride }) {
  const out = ["Transaction report", "Seller ID,samplestore", 'Report period,"Sep 28, 2026 - Oct 8, 2026"', "", HEAD.join(",")];
  let total = 0;
  const row = (o) => {
    const bad = typeof o.net === "string";
    const fees = (o.fixed ?? 0) + (o.variable ?? 0) + (o.intl ?? 0);
    const net = bad ? o.net : o.net ?? Math.round(((o.sub ?? 0) + (o.ship ?? 0) + (o.tax ?? 0) - fees) * 100) / 100;
    if (!bad && o.type !== "Payout") total += Math.round(net * 100);
    const cells = [ebayDate(o.date), o.type, o.order ?? "--", "--", "--", bad ? net : amt(net), currency, ebayDate(effective), id, "Paid", o.item ?? "--", o.title ? csvq(o.title) : "--", o.sub !== undefined ? 1 : "--", amt(o.sub), amt(o.ship), amt(o.tax), "--", o.fixed ? amt(-o.fixed) : "--", o.variable ? amt(-o.variable) : "--", "--", "--", o.intl ? amt(-o.intl) : "--", "--", o.sub !== undefined ? amt((o.sub ?? 0) + (o.ship ?? 0) + (o.tax ?? 0)) : "--", currency, o.desc ? csvq(o.desc) : "--"];
    out.push(cells.join(","));
  };
  for (const it of items) row(it);
  if (withPayoutRow) row({ date: effective, type: "Payout", net: -(totalOverride ?? total) / 100, desc: "Payout" });
  return out.join("\n") + "\n";
}

export const SAMPLE_ITEMS = [
  { date: "2026-09-28", type: "Order", order: "27-11001-50001", item: "334455667788", title: "Vintage Leather Camera Strap", sub: 38.0, ship: 5.0, tax: 3.1, fixed: 0.4, variable: 5.7 },
  { date: "2026-09-29", type: "Order", order: "27-11002-50002", item: "334455667799", title: "Brass Desk Lamp", sub: 64.5, ship: 0, tax: 0, fixed: 0.4, variable: 8.55 },
  { date: "2026-09-30", type: "Order", order: "27-11003-50003", item: "334455667788", title: "Vintage Leather Camera Strap", sub: 38.0, ship: 5.0, tax: 0, fixed: 0.4, variable: 5.7, intl: 0.7 },
  { date: "2026-09-30", type: "Shipping label", order: "27-11001-50001", net: -4.35, desc: "Shipping label" },
  { date: "2026-10-01", type: "Other fee", net: -6.2, desc: "Promoted Listings - General fee" },
  { date: "2026-10-02", type: "Order", order: "27-11004-50004", item: "334455667700", title: "Mid-century Ceramic Vase", sub: 112.0, ship: 12.0, tax: 0, fixed: 0.4, variable: 16.43 },
  { date: "2026-10-03", type: "Refund", order: "27-11002-50002", net: -73.05, desc: "Refund" },
  { date: "2026-10-04", type: "Other fee", net: -11.95, desc: "Store subscription fee" },
  { date: "2026-10-05", type: "Shipping label", order: "27-11004-50004", net: -9.8, desc: "Shipping label" },
  { date: "2026-10-06", type: "Hold", net: 2.0, desc: "Hold released" },
];
export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS });
// The same report after a hand edit: a row dropped from the paste so the payout no longer agrees, one Type no rule
// recognises, an amount that is not a number and a row whose columns disagree with its net.
export function sampleBrokenReport() {
  const full = buildReport({ items: SAMPLE_ITEMS });
  const total = full.split("\n").slice(5).filter((l) => /,Payout,/.test(l)).length ? SAMPLE_ITEMS.reduce((a, o) => a + (o.net !== undefined ? Math.round(o.net * 100) : Math.round(((o.sub ?? 0) + (o.ship ?? 0) + (o.tax ?? 0) - (o.fixed ?? 0) - (o.variable ?? 0) - (o.intl ?? 0)) * 100)), 0) : 0;
  const items = SAMPLE_ITEMS.filter((o) => o.desc !== "Store subscription fee").map((o) => (o.order === "27-11003-50003" && o.type === "Order" ? { ...o, net: 41.0 } : o));
  items.push({ date: "2026-10-06", type: "Mystery", net: 1.23, desc: "Marketplace thing" }, { date: "2026-10-06", type: "Other fee", net: "12..5", desc: "Insertion fee" });
  return buildReport({ items, totalOverride: total });
}

engines/etsy.mjs.text:
// Etsy Payment account / monthly statement CSV -> accounting journal.
//
// Etsy's statement lists every sale, fee, refund, ad charge, shipping label and deposit with
// amounts like "$25.00" and "--". Bookkeepers need gross sales, each kind of fee and the bank
// deposits booked separately, one journal per calendar month, balanced to an Etsy clearing
// account. This module reads the statement, checks every row's amount + fees = net, optionally
// proves the month's activity against a total typed in from Etsy, and writes balanced journals
// for Xero, QuickBooks Online, QuickBooks Desktop (IIF) and plain CSV.
//
// The column names, Type values and importer layouts are from memory of public Etsy and
// accounting help documents; no real Etsy export and no live import was available when this was
// written. Unrecognised rows are never dropped: they land in an uncategorised line and are reported.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Etsy sales (gross)", account: "Etsy Sales" },
  refunds: { label: "Refunds", account: "Etsy Refunds" },
  fees: { label: "Etsy fees (listing, transaction, processing, other)", account: "Etsy Fees" },
  ads: { label: "Etsy Ads and offsite ads", account: "Etsy Advertising" },
  labels: { label: "Shipping labels bought through Etsy", account: "Etsy Shipping Labels" },
  taxes: { label: "Taxes withheld or remitted by Etsy", account: "Etsy Taxes Withheld" },
  other: { label: "Adjustments and credits", account: "Etsy Adjustments" },
  uncategorised: { label: "Uncategorised Etsy items", account: "Etsy Uncategorised" },
  deposits: { label: "Deposits to your bank", account: "Bank - Etsy Deposits" },
  clearing: { label: "Etsy clearing (Payment account balance movement)", account: "Etsy Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const REQUIRED = ["net", "reporting-category"];

const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
// Etsy prints amounts as "$25.00", "-$1.63", "--" or "€12,50"; strip the symbol and read the rest.
export function parseMoney(s) {
  const t = String(s ?? "").trim();
  if (t === "" || /^-+$/.test(t)) return null;
  const neg = /^\(.*\)$/.test(t) || /^[-−]/.test(t) || /[-−]$/.test(t);
  const core = t.replace(/[^0-9.,]/g, "");
  if (!core) return NaN;
  const v = parseAmount(core);
  return v === null || Number.isNaN(v) ? NaN : neg ? -Math.abs(v) : v;
}
// Etsy writes "September 28, 2026" or "28 September 2026" or numeric dates; return YYYY-MM-DD or null.
export function parseStatementDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  let x;
  if ((x = t.match(/^([A-Za-z]{3})[a-z]*\.? (\d{1,2}),? (\d{4})/))) { const m = MONTHS[x[1].toLowerCase()]; return m ? parseDate(`${x[3]}-${String(m).padStart(2, "0")}-${String(x[2]).padStart(2, "0")}`) : null; }
  if ((x = t.match(/^(\d{1,2}) ([A-Za-z]{3})[a-z]*\.?,? (\d{4})/))) { const m = MONTHS[x[2].toLowerCase()]; return m ? parseDate(`${x[3]}-${String(m).padStart(2, "0")}-${String(x[1]).padStart(2, "0")}`) : null; }
  return parseDate(t, order);
}

// Rows are grouped by calendar month. The month's activity (everything except deposits) can be
// checked against a net total the caller types in from Etsy via opts.expected.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^\uFEFF/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose an Etsy statement."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = { date: col("date"), type: col("type"), title: col("title"), info: col("info"), currency: col("currency"), amount: col("amount"), fees: col("fees-&-taxes", "fees-and-taxes", "fees"), net: col("net") };
  const missing = [];
  if (I.date < 0) missing.push("Date");
  if (I.type < 0) missing.push("Type");
  if (I.net < 0 && I.amount < 0) missing.push("Net or Amount");
  if (missing.length) {
    add("error", "This does not look like an Etsy statement", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Etsy Shop Manager open Finances > Payment account (or Legal & tax > Monthly statements) and download the CSV.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const type = get(cells, "type").toLowerCase(), title = get(cells, "title");
    const date = parseStatementDate(get(cells, "date"), opts.dateOrder);
    if (!date) { add("error", `Date "${get(cells, "date")}" not understood`, "The row is left out, so its month will not add up.", i + 1); continue; }
    const amtS = get(cells, "amount"), feeS = get(cells, "fees"), netS = get(cells, "net");
    let amount = parseMoney(amtS), ft = parseMoney(feeS), net = parseMoney(netS);
    if ([amount, ft, net].some((v) => Number.isNaN(v))) { add("error", "An amount is not a number", `"${[amtS, feeS, netS].join(" | ")}" on ${title || type || `line ${i + 1}`} was left out.`, i + 1); continue; }
    if (amount === null && net === null) { add("warning", "Row has no amount", `${type || "row"} was skipped.`, i + 1); continue; }
    if (amount === null) amount = net - (ft || 0);
    if (net === null) net = amount + (ft || 0);
    if (ft === null) ft = 0;
    if (amount + ft !== net) add("error", `Amount plus fees and taxes does not equal net on "${title || type}"`, `${money(amount)} + ${money(ft)} = ${money(amount + ft)}, but the row says ${money(net)}. The journal uses the net; check the file was not edited.`, i + 1);
    const ym = date.slice(0, 7);
    if (!byId.has(ym)) byId.set(ym, { id: ym, effective: null, stated: null, currency: "", rows: [] });
    const s = byId.get(ym);
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in ${ym}`, `${cur} row among ${s.currency} rows. Journals assume one currency per month.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    if (!s.effective || date > s.effective) s.effective = date;
    s.rows.push({ line: i + 1, id: "", cat: type, desc: title, info: get(cells, "info"), gross: amount, fee: -ft, net, created: date });
    rows++;
  }
  const payouts = [...byId.values()].sort((a, b) => a.id.localeCompare(b.id));
  if (!payouts.length) add("error", "No statement rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    if (payouts.length === 1) payouts[0].stated = opts.expected;
    else add("info", "Expected total ignored", "It can only be applied when the file holds exactly one month.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- categorising ------------------------------------------------------------

export function categoryOf(row) {
  const c = String(row.cat || "").toLowerCase().trim();
  const t = String(row.desc || "").toLowerCase();
  if (c === "sale" || c === "payment" || c === "order") return "sales";
  if (c === "refund") return "refunds";
  if (c === "deposit" || c === "payout" || c === "transfer") return "deposits";
  if (c === "marketing" || /etsy ads|offsite ads|promoted/.test(t)) return "ads";
  if (c === "shipping" || c === "shipping label" || /shipping label|postage/.test(t)) return "labels";
  if (c === "tax" || c === "vat" || c === "sales tax") return "taxes";
  if (c === "fee" || c === "listing" || c === "processing" || c === "transaction" || /listing fee|transaction fee|processing fee|regulatory|renew/.test(t)) return "fees";
  if (c === "adjustment" || c === "credit" || c === "reserve" || c === "reserve release") return "other";
  return "uncategorised";
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.filter((r) => categoryOf(r) !== "deposits").reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.stated === null) findings.push({ severity: "info", title: `Month ${s.id}: no expected total to check against`, detail: `The activity rows (everything except deposits) add up to ${money(sum, cur)}. Type the month's net total from Etsy into the optional box to prove it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Month ${s.id}: activity adds up to ${money(sum, cur)} but the total you gave is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      const k = categoryOf(r);
      add(k, r.gross);
      add(k === "sales" ? "taxes" : "fees", -r.fee);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in ${s.id} had no date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Month ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Stripe clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Etsy statement ${s.id}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Etsy statement ${s.id}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => categoryOf(r) === "uncategorised");
    if (unknown.length) findings.push({ severity: "warning", title: `Month ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.cat || r.desc))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => categoryOf(r) === "uncategorised").map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = s.rows.filter((r) => categoryOf(r) !== "deposits").reduce((a, r) => a + r.net, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Date", "Type", "Title", "Info", "Currency", "Amount", "Fees & Taxes", "Net", "Tax Details"];
const usd = (c) => (c < 0 ? "-" : "") + "$" + Math.abs(c / 100).toFixed(2);

// items: [date, type, title, amount, feesAndTaxes]; amounts in dollars, fees negative. Net is computed.
export function buildReport(items) {
  const q = (v) => (/[",]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
  const out = [HEAD.join(",")];
  for (const [date, type, title, amount, fees] of items) {
    const a = typeof amount === "string" ? amount : usd(Math.round(amount * 100));
    const f = fees ? usd(Math.round(fees * 100)) : "--";
    const n = typeof amount === "string" ? amount : usd(Math.round((amount + (fees || 0)) * 100));
    out.push([date, type, title, "", "USD", a, f, n, "--"].map(q).join(","));
  }
  return out.join("\n") + "\n";
}

export const SAMPLE_ITEMS = [
  ["September 3, 2026", "Sale", "Payment for Order #1001", 42.0, 0],
  ["September 3, 2026", "Fee", "Transaction fee: Handmade candle", -2.73, 0],
  ["September 3, 2026", "Fee", "Processing fee", -1.5, 0],
  ["September 9, 2026", "Sale", "Payment for Order #1002", 28.5, 0],
  ["September 9, 2026", "Fee", "Transaction fee: Soap set", -1.85, 0],
  ["September 14, 2026", "Fee", "Listing fee", -0.2, 0],
  ["September 20, 2026", "Marketing", "Etsy Ads", -6.0, 0],
  ["September 25, 2026", "Refund", "Refund for Order #1001 (partial)", -10.0, 0],
  ["September 30, 2026", "Deposit", "Deposit to bank account ending 1234", -30.0, 0],
  ["October 2, 2026", "Sale", "Payment for Order #1003", 64.0, 0],
  ["October 2, 2026", "Fee", "Transaction fee: Candle trio", -4.16, 0],
  ["October 4, 2026", "Shipping", "Shipping label: USPS Priority", -8.9, 0],
  ["October 5, 2026", "Fee", "Listing fee", -0.2, 0],
];
export const SAMPLE_NET_SEPT = 42.0 - 2.73 - 1.5 + 28.5 - 1.85 - 0.2 - 6.0 - 10.0;

export const sampleReport = () => buildReport(SAMPLE_ITEMS);
// The same statement after a hand edit: an unknown type, a garbled amount and a net that no longer adds up.
export function sampleBrokenReport() {
  return buildReport(SAMPLE_ITEMS).replace("Etsy Ads,,USD,-$6.00,--,-$6.00", "Etsy Ads,,USD,-$6.00,--,-$5.00") + `"October 6, 2026",Mystery,Unknown thing,,USD,$1.23,--,$1.23,--\n"October 6, 2026",Sale,Typo,,USD,$12..5,--,$12..5,--\n`;
}

engines/fiverr.mjs.text:
// Fiverr earnings / transaction history -> accounting journal.
//
// Fiverr keeps a seller's money in a Fiverr revenue balance. Order revenue and tips arrive, Fiverr's 20% service
// fee is either shown as its own negative row or already taken off the order amount, refunds and cancellations
// reverse revenue, and a withdrawal to a bank, PayPal or Payoneer moves the money out (often with a withdrawal
// fee). A bookkeeper therefore has to book income gross, the fee as an expense, and clear the Fiverr balance
// against the withdrawals. This module reads a Fiverr earnings / transaction CSV (Date, Type, Description or
// Order ID, Amount, optionally Balance), books each row by its Type, proves the file is complete by walking the
// Balance column row to row (a missing or edited row breaks the chain), and writes balanced journals for Xero,
// QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV, one per month.
//
// When order rows are already net of Fiverr's fee (no separate fee rows), feeMode "net" grosses each order row
// up at feePct (default 20) and books the difference as the service fee, so revenue is still gross and the
// Fiverr balance is unchanged. Tips are never grossed up.
//
// The export's column names, its Type labels and each importer's layout are alias-matched guesses from memory
// of public Fiverr and accounting help documents; no real Fiverr export and no live Xero or QuickBooks import
// was available when this was written. Columns are matched by several aliases, a row no rule explains is never
// dropped (it lands in an "uncategorised" line and is reported), and the Balance check says whether the rows
// can be trusted.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  orders: { label: "Fiverr order revenue (gross)", account: "Fiverr Order Income" },
  tips: { label: "Fiverr tips (gross)", account: "Fiverr Tip Income" },
  fees: { label: "Fiverr service fees", account: "Fiverr Service Fees" },
  withdrawalfees: { label: "Fiverr withdrawal and processing fees", account: "Fiverr Withdrawal Fees" },
  refunds: { label: "Refunds, cancellations and resolutions", account: "Fiverr Refunds" },
  withdrawals: { label: "Withdrawals to your bank, PayPal or Payoneer", account: "Bank (Fiverr withdrawals)" },
  uncategorised: { label: "Uncategorised Fiverr items", account: "Fiverr Uncategorised" },
  clearing: { label: "Fiverr balance (clearing)", account: "Fiverr Balance" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

// "$1,234.56", "-$12.00", "(12.00)", "USD 5" and European "1.234,56" all read to cents. Empty is null, junk is NaN.
export function parseAmount(s) {
  let t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  t = t.replace(/^([-+]?)(?:[A-Za-z]{3})/, "$1").replace(/[$€£]/g, "");
  const paren = t.match(/^\((.*)\)$/);
  if (paren) t = "-" + paren[1];
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), "Sep 28, 2026", DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})/)) && MONTHS[x[1].toLowerCase()]) [m, d, y] = [MONTHS[x[1].toLowerCase()], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})/)) && MONTHS[x[2].toLowerCase()]) [d, m, y] = [x[1], MONTHS[x[2].toLowerCase()], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

// Fiverr Type labels, matched loosely and in this order: a "Withdrawal Fee" is a fee, not a withdrawal, and a
// cancelled order is a reversal, not revenue.
export function rowCategory(type) {
  const t = String(type || "").toLowerCase().trim();
  if (!t) return "uncategorised";
  if (/withdraw.*fee|fee.*withdraw|processing fee|transfer fee|payout fee|wire fee/.test(t)) return "withdrawalfees";
  if (/service fee|fiverr fee|commission|transaction fee|marketplace fee|\bfee\b/.test(t)) return "fees";
  if (/withdraw|transfer to|payout|paypal|payoneer|bank/.test(t)) return "withdrawals";
  if (/refund|chargeback|dispute|reversal|clawback|cancel|resolution|revoked/.test(t)) return "refunds";
  if (/\btips?\b|gratuity/.test(t)) return "tips";
  if (/order|revenue|earning|delivered|sale|gig|payment|milestone|project/.test(t)) return "orders";
  return "uncategorised";
}

const ALL = "Fiverr";

// The whole file is one account statement. Rows are walked in time order (Fiverr may list newest or oldest first; the order is
// detected from the Balance column, or from the dates when there is none) so the running Balance can be proved.
// opts.expected, when given, is the balance Fiverr shows after the last row.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Fiverr earnings or transaction history CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    date: col("date", "transaction-date", "date-created", "created-at", "completed-date", "cleared-date", "datetime", "date-time", "day"),
    id: col("order-id", "order-number", "order", "reference-id", "reference", "transaction-id", "ref-id", "id", "ref"),
    type: col("type", "transaction-type", "activity", "activity-type", "event", "entry-type"),
    desc: col("description", "details", "gig", "gig-title", "service", "memo", "note", "notes", "buyer"),
    amount: col("amount", "net-amount", "amount-in-usd", "usd-amount", "total"),
    currency: col("currency"),
    balance: col("balance", "balance-in-usd", "running-balance", "account-balance", "revenue-balance"),
  };
  const missing = [];
  if (I.date < 0) missing.push("date");
  if (I.type < 0) missing.push("type");
  if (I.amount < 0) missing.push("amount");
  if (missing.length) {
    add("error", "This does not look like a Fiverr earnings history", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Fiverr open Business > Earnings (or Revenue), choose the date range and download the CSV, then paste the whole file here. Column names are alias-matched, so a differently named column may need renaming to Date, Type and Amount.`, first + 1);
    return none;
  }
  const feePct = Number.isFinite(opts.feePct) && opts.feePct >= 0 && opts.feePct < 100 ? opts.feePct : 20;
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const rows = [];
  let currency = "";
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const rid = get(cells, "id") || `line ${i + 1}`;
    const amount = parseAmount(get(cells, "amount")), bal = I.balance >= 0 ? parseAmount(get(cells, "balance")) : null;
    if (amount === null) { add("warning", "Row has no amount", `${rid} was skipped.`, i + 1); continue; }
    if (Number.isNaN(amount) || Number.isNaN(bal)) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so the balance will not add up.", i + 1); continue; }
    const cur = get(cells, "currency").toUpperCase();
    if (cur && currency && cur !== currency) add("warning", "Mixed currencies in the export", `${cur} row among ${currency} rows. Journals assume one currency; Fiverr's own Amount column is in your account currency.`, i + 1);
    if (cur && !currency) currency = cur;
    const type = get(cells, "type");
    const key = rowCategory(type);
    const created = parseDate(get(cells, "date"), opts.dateOrder);
    if (!created) add("warning", `Row ${rid} has no readable date`, `"${get(cells, "date")}" was not understood; the row is placed in the final month.`, i + 1);
    let parts = [{ k: key, amt: amount }], gross = key === "orders" || key === "tips" ? amount : 0, fee = key === "fees" ? -amount : 0;
    if (opts.feeMode === "net" && key === "orders" && amount > 0) {
      gross = Math.round(amount / (1 - feePct / 100));
      fee = gross - amount;
      parts = [{ k: "orders", amt: gross }, { k: "fees", amt: -fee }];
    }
    rows.push({ line: i + 1, id: rid, item: get(cells, "desc") || type, type, gross, fee, net: amount, bal, refunded: key === "refunds", parts, created });
  }
  if (!rows.length) { add("error", "No transaction rows found", "The header was read but there were no data rows."); return none; }

  // Put the rows in time order. With balances, the order that makes the running balance hold wins.
  const chain = (rs) => rs.reduce((n, r, j) => n + (j > 0 && r.bal !== null && rs[j - 1].bal !== null && rs[j - 1].bal + r.net === r.bal ? 1 : 0), 0);
  const fwd = rows, rev = [...rows].reverse();
  let ordered = fwd;
  const cf = chain(fwd), cr = chain(rev);
  if (cf !== cr) ordered = cr > cf ? rev : fwd;
  else { const a = fwd[0].created, z = fwd[fwd.length - 1].created; if (a && z && a > z) ordered = rev; }

  const haveBal = ordered.every((r) => r.bal !== null);
  let stated = null, opening = null;
  if (haveBal) {
    opening = ordered[0].bal - ordered[0].net;
    stated = ordered[ordered.length - 1].bal - opening;
    for (let j = 1; j < ordered.length; j++) {
      const p = ordered[j - 1], r = ordered[j], off = r.bal - p.bal - r.net;
      if (off !== 0) add("error", `Balance does not follow between ${p.id} and ${r.id}`, `The balance moved by ${money(r.bal - p.bal, currency || "USD")} but ${r.id} is ${money(r.net, currency || "USD")}: ${money(off, currency || "USD")} is missing or was edited (line ${p.line} to ${r.line}). A row may have been dropped from the paste or its amount changed.`, r.line);
    }
    if (opts.expected != null && Number.isFinite(opts.expected) && opts.expected !== ordered[ordered.length - 1].bal) add("warning", "The last balance in the file is not the balance you entered", `The file ends at ${money(ordered[ordered.length - 1].bal, currency || "USD")} but you entered ${money(opts.expected, currency || "USD")}. The export may stop before today, or newer rows are missing.`, 0);
  } else add("warning", "No Balance column, so completeness cannot be proved", "Without the running balance the page cannot tell if a row is missing. Download the full Transaction history (it includes Balance) and paste that.", 0);
  const effective = ordered.map((r) => r.created).filter(Boolean).sort().pop() || null;
  const group = { id: ALL, effective, stated, opening, currency, rows: ordered };
  return { payouts: [group], findings, summary: { rows: ordered.length, payouts: 1 } };
}

// What Fiverr cost, against what was billed: the number a seller actually wants from the file.
export function feeSummary(payouts) {
  let gross = 0, fees = 0, withdrawalFees = 0, refunds = 0, withdrawn = 0;
  for (const s of payouts) for (const r of s.rows) for (const p of r.parts) {
    if (p.k === "orders" || p.k === "tips") gross += p.amt;
    else if (p.k === "fees") fees -= p.amt;
    else if (p.k === "withdrawalfees") withdrawalFees -= p.amt;
    else if (p.k === "refunds") refunds -= p.amt;
    else if (p.k === "withdrawals") withdrawn -= p.amt;
  }
  return { gross, fees, withdrawalFees, refunds, withdrawn, feeRate: gross > 0 ? fees / gross : null, allInRate: gross > 0 ? (fees + withdrawalFees) / gross : null };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.stated === null) findings.push({ severity: "warning", title: "The Fiverr balance could not be checked", detail: `The rows add up to ${money(sum, cur)}. Without a Balance column the page cannot prove nothing is missing.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Rows add up to ${money(sum, cur)} but the Fiverr balance moved by ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped or edited. Do not post these journals until the figures agree.`, line: 0 });

    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const p of r.parts) add(p.k, p.amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} had no readable date`, detail: "They were placed in the final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `The export spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to the Fiverr balance account, so every month's revenue and fees land in the month they happened.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Change in Fiverr balance (${ym})` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Fiverr transactions ${ym}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), fees: feeSummary(p.payouts), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Date", "Order ID", "Type", "Description", "Amount", "Currency", "Balance"];

// items: [date, type, description, amount] in time order. The file lists the newest row first, with the balance
// after each row. `skip` drops rows from the output but keeps the balances, as a hand-edited paste would.
export function buildReport({ currency = "USD", opening = 250, items, skip = [], mangle = {} }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  let bal = Math.round(opening * 100);
  const rows = items.map(([date, type, desc, amt], n) => {
    const cents = Math.round(amt * 100);
    bal += cents;
    const amtText = mangle[n] ?? (cents < 0 ? "-" : "") + (Math.abs(cents) / 100).toFixed(2);
    return [date, `FO${2000000 + n}`, type, desc, amtText, currency, (bal / 100).toFixed(2)].map(csv).join(",");
  });
  const kept = rows.filter((_, n) => !skip.includes(n));
  return [HEAD.join(","), ...kept.reverse()].join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-18", "Order revenue", "Logo design - Gold package", 500.00],
  ["2026-09-18", "Service fee", "Fiverr service fee (20%)", -100.00],
  ["2026-09-25", "Order revenue", "Voice-over, 500 words", 300.00],
  ["2026-09-25", "Service fee", "Fiverr service fee (20%)", -60.00],
  ["2026-09-29", "Withdrawal", "Withdrawal to PayPal", -500.00],
  ["2026-09-29", "Withdrawal fee", "PayPal withdrawal fee", -1.00],
  ["2026-10-02", "Tip", "Tip from buyer - Logo design", 50.00],
  ["2026-10-04", "Order revenue", "Logo design - Silver package", 250.00],
  ["2026-10-04", "Service fee", "Fiverr service fee (20%)", -50.00],
  ["2026-10-05", "Order cancellation", "Cancelled - Voice-over rush", -80.00],
];

export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS });
// The same history after a hand edit: the tip row dropped from the paste (the balance no longer follows),
// one amount that is not a number, and a type no rule knows.
export function sampleBrokenReport() {
  const items = [...SAMPLE_ITEMS, ["2026-10-06", "Fiverr credit", "Promotional credit", 5.00], ["2026-10-06", "Order revenue", "Logo design - Bronze package", 0]];
  return buildReport({ items, skip: [6], mangle: { 11: "6..4" } });
}

engines/gumroad.mjs.text:
// Gumroad sales export -> accounting journal.
//
// Gumroad pays creators a net deposit that hides the sales, the Gumroad fee and any refunds.
// Bookkeepers need those split out, and a payout that straddles a month end split in two.
// This module reads the sales CSV (Gumroad Analytics > Sales > Export, or the Payouts
// "download CSV"), splits every sale into sales, shipping income, tax you collected, fees and
// refunds, proves the rows add up to the payout, and writes balanced journals for Xero,
// QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV.
//
// The export's column names and each importer's column layout are from memory of public Gumroad
// and accounting help documents; no real Gumroad export and no live Xero or QuickBooks import was
// available when this was written. Column names are matched by several aliases, a sale whose
// parts do not add to its net is flagged, and a row no rule explains is never dropped: it lands in an
// "uncategorised" line and is reported, so the journal still equals the net.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Product sales (gross)", account: "Gumroad Sales" },
  shipping: { label: "Shipping charged to buyers", account: "Gumroad Shipping Income" },
  tax: { label: "Sales tax / VAT you collected (liability)", account: "Gumroad Sales Tax Payable" },
  refunds: { label: "Refunds", account: "Gumroad Refunds" },
  fees: { label: "Gumroad fees", account: "Gumroad Fees" },
  uncategorised: { label: "Uncategorised Gumroad items", account: "Gumroad Uncategorised" },
  clearing: { label: "Gumroad clearing (matches the payout deposit)", account: "Gumroad Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const UNPAID = "(no payout ID)";
const ALL = "all rows";
const TRUE = /^(true|yes|y|1|refunded)$/i;

// Rows are grouped by payout id when the export has one; otherwise the whole file is one group and
// the deposit is supplied by the caller (opts.expected, from the bank / PayPal / Gumroad payouts page).
// An optional `type` column containing "payout" states the deposit.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Gumroad sales CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    payout: col("payout-id", "payout", "payout-reference"),
    effective: col("payout-date", "paid-out-on", "payout-created-at"),
    id: col("sale-id", "purchase-id", "order-id", "id"),
    created: col("date", "purchase-date", "sale-date", "created-at", "created"),
    currency: col("currency", "price-currency"),
    price: col("price", "product-price", "amount", "gross"),
    shipping: col("shipping", "shipping-price"),
    tax: col("taxes", "tax", "sales-tax", "vat"),
    fee: col("fees", "fee", "gumroad-fees", "gumroad-fee"),
    net: col("net-total", "net", "net-earnings", "seller-revenue", "you-receive"),
    refunded: col("refunded", "is-refunded", "refunded?", "refund"),
    refundAmt: col("refunded-amount", "amount-refunded"),
    item: col("item-name", "product-name", "product", "item"),
    type: col("type", "transaction-type"),
  };
  const missing = [];
  if (I.net < 0) missing.push("net total");
  if (I.price < 0) missing.push("price");
  if (missing.length) {
    add("error", "This does not look like a Gumroad sales export", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Gumroad open Analytics > Sales (or Payouts) and choose Export / Download CSV, then paste the whole file here.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, effective: null, stated: null, currency: "", rows: [] }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const rid = get(cells, "id") || `line ${i + 1}`;
    const pid = I.payout >= 0 ? get(cells, "payout") || UNPAID : ALL;
    const s = bucket(pid);
    const eff = parseDate(get(cells, "effective"), opts.dateOrder);
    if (eff && !s.effective) s.effective = eff;
    const netS = get(cells, "net"), net = parseAmount(netS);
    if (/^payout/i.test(get(cells, "type"))) { if (net !== null && !Number.isNaN(net)) s.stated = (s.stated || 0) + Math.abs(net); continue; } // the deposit itself
    if (net === null) { add("warning", "Row has no net total", `${rid} was skipped.`, i + 1); continue; }
    const amts = {};
    let bad = Number.isNaN(net);
    for (const k of ["price", "shipping", "tax", "fee", "refundAmt"]) { const v = parseAmount(get(cells, k)); if (Number.isNaN(v)) bad = true; amts[k] = v == null ? 0 : v; }
    if (bad) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in ${pid === ALL ? "the export" : `payout ${pid}`}`, `${cur} row among ${s.currency} rows. Journals assume one currency per payout.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    const refunded = TRUE.test(get(cells, "refunded")) || amts.refundAmt > 0;
    // Gumroad fee columns are usually positive numbers meaning a cost; a negative one is read as a cost too.
    const fee = Math.abs(amts.fee);
    const parts = [];
    const push = (k, amt) => { if (amt) parts.push({ k, amt }); };
    push("sales", amts.price);
    push("shipping", amts.shipping);
    // Tax is the buyer's, so it only belongs in the payout when the row's own arithmetic says Gumroad paid it out.
    const taxInNet = amts.tax !== 0 && amts.price + amts.shipping + amts.tax - fee === net + (refunded ? (amts.refundAmt || amts.price + amts.shipping + amts.tax) : 0);
    if (taxInNet) push("tax", amts.tax);
    push("fees", -fee);
    if (refunded) push("refunds", -(amts.refundAmt || amts.price + amts.shipping + (taxInNet ? amts.tax : 0)));
    let residual = net - parts.reduce((a, p) => a + p.amt, 0);
    if (residual !== 0) {
      if (refunded) { push("fees", residual); add("info", `${rid}: refunded sale's fee adjusted by ${money(residual)}`, "The net total on a refunded sale differs from price minus fee minus refund; the difference is booked to fees (Gumroad returning or keeping its fee).", i + 1); }
      else { push("uncategorised", residual); add("error", `Parts do not add up to the net total on ${rid}`, `Price ${money(amts.price)} + shipping ${money(amts.shipping)} - fee ${money(fee)} = ${money(amts.price + amts.shipping - fee)}, but the row says ${money(net)}. The ${money(residual)} difference is journalled to "uncategorised"; check the file was not edited.`, i + 1); }
    }
    s.rows.push({ line: i + 1, id: rid, item: get(cells, "item"), gross: amts.price, fee, net, refunded, parts, created: parseDate(get(cells, "created"), opts.dateOrder) });
    rows++;
  }
  const payouts = [...byId.values()].filter((s) => s.rows.length || s.stated !== null);
  if (!payouts.length) add("error", "No sales rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    const real = payouts.filter((s) => s.id !== UNPAID);
    if (real.length === 1 && real[0].stated === null) real[0].stated = opts.expected;
    else if (real.length !== 1) add("info", "Expected deposit ignored", "It can only be applied when the file holds exactly one payout (or no payout column) without a deposit row of its own.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.id === UNPAID) findings.push({ severity: "warning", title: `${s.rows.length} row${s.rows.length === 1 ? "" : "s"} have no payout ID`, detail: "They have no payout ID in the report. They are journalled to Gumroad clearing as a separate group and will not match a bank deposit yet.", line: 0 });
    else if (s.stated === null) findings.push({ severity: "warning", title: `${s.id === ALL ? "The export" : `Payout ${s.id}`} has no payout row and no expected deposit`, detail: `The rows add up to ${money(sum, cur)}. Enter the deposit from your bank, PayPal or Gumroad payout in the box above to check it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Payout ${s.id}: rows add up to ${money(sum, cur)} but the payout is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const p of r.parts) add(p.k, p.amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in payout ${s.id} had no created date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Payout ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Gumroad clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Payout ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Gumroad payout ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `Payout ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.id === UNPAID ? null : s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.id === UNPAID || s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Type", "Sale ID", "Item Name", "Date", "Price", "Shipping", "Taxes", "Fees", "Net Total", "Currency", "Refunded", "Payout ID"];

// items: [date, item, price, fee, refunded, shipping]. A deposit row is added when `withPayoutRow`
// (real exports usually have none, so the deposit is then typed in from the bank).
export function buildReport({ id = "P-2026-10", currency = "USD", items, withPayoutRow = false, totalOverride }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const out = [HEAD.join(",")];
  let net = 0, n = 0;
  for (const [date, item, price, fee, refunded, shipping] of items) {
    n++;
    const bad = typeof price === "string";
    const ship = shipping || 0;
    const nn = bad ? NaN : refunded ? -fee : price + ship - fee;
    if (!Number.isNaN(nn)) net += Math.round(nn * 100);
    out.push(["sale", `S${1000 + n}`, item, `${date} 12:00:00`, bad ? price : price.toFixed(2), ship.toFixed(2), "0.00", fee.toFixed(2), bad ? price : nn.toFixed(2), currency, refunded ? "true" : "false", id].map(csv).join(","));
  }
  if (withPayoutRow) out.push(["payout", "", "", "", "", "", "", "", ((totalOverride ?? net / 100)).toFixed(2), currency, "", id].map(csv).join(","));
  return out.join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-28", "Notion template pack", 29.00, 3.70, false],
  ["2026-09-29", "Logo design course", 149.00, 15.40, false],
  ["2026-09-30", "Stock photo bundle", 19.00, 2.35, false],
  ["2026-10-01", "Logo design course", 149.00, 15.40, false],
  ["2026-10-02", "Notion template pack", 29.00, 3.70, true],
  ["2026-10-03", "Printed poster", 35.00, 4.25, false, 6.50],
];

const deposit = (items) => items.reduce((a, r) => a + Math.round(((r[4] ? 0 : r[2] + (r[5] || 0)) - r[3]) * 100), 0) / 100;
export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS, withPayoutRow: true });
// The same export after a hand edit: a row dropped from the paste so the payout no longer agrees,
// one sale whose parts do not add to its net, and one amount that is not a number.
export function sampleBrokenReport() {
  const items = SAMPLE_ITEMS.filter((r) => r[1] !== "Printed poster");
  items.push(["2026-10-04", "Mystery item", 10.00, 1.00, false]);
  items.push(["2026-10-04", "Ebook", "12..5", 1.00, false]);
  return buildReport({ items, totalOverride: deposit(SAMPLE_ITEMS), withPayoutRow: true }).replace("10.00,0.00,0.00,1.00,9.00,", "10.00,0.00,0.00,1.00,7.00,");
}

engines/kdp.mjs.text:
// Amazon KDP royalty report / payments export -> accounting journal.
//
// An author's KDP royalties arrive as one payment per marketplace and currency, long after the sales happened,
// and a paperback or hardcover royalty is what is left after Amazon's printing cost. A bookkeeper who books only
// the bank deposit understates income, hides printing cost, puts income in the wrong month and cannot tell which
// marketplace or format earned it. This module reads a KDP royalty report CSV (a date or month, a format or
// transaction type, a royalty amount, optionally marketplace, title, units, printing cost, tax withheld,
// currency and a per-row total), books each row gross by marketplace and format (ebook, paperback, hardcover,
// KENP page reads), books printing cost and any tax withheld as expenses, sends rows no rule recognises to an
// uncategorised account (never dropped), proves the file is complete by checking each row's Total column and
// any Total row against the rows, and writes balanced journals for Xero, QuickBooks Online, QuickBooks Desktop
// (IIF) and a plain CSV, one per currency per month, against an Amazon KDP receivable account.
//
// Currency is noted, never converted: a journal is written per currency, labelled with that currency, and no
// exchange rate is applied or invented.
//
// When the royalty column is already net of printing cost, printMode "net" adds the printing-cost column back
// onto income and books it as an expense, so income is gross and the amount owed by Amazon is unchanged.
//
// The export's column names, its format labels and each importer's layout are alias-matched guesses; no real KDP
// export and no live Xero or QuickBooks import was available when this was written. Columns are matched by
// several aliases, a row no rule explains is never dropped, and the completeness checks say whether the rows
// can be trusted.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  ebook: { label: "KDP eBook royalties (gross)", account: "KDP eBook Royalties" },
  paperback: { label: "KDP paperback royalties (gross)", account: "KDP Paperback Royalties" },
  hardcover: { label: "KDP hardcover royalties (gross)", account: "KDP Hardcover Royalties" },
  kenp: { label: "KDP KENP page-read royalties", account: "KDP KENP Royalties" },
  printing: { label: "KDP printing costs", account: "KDP Printing Costs" },
  withholding: { label: "KDP tax withheld", account: "KDP Tax Withheld" },
  uncategorised: { label: "Uncategorised KDP items", account: "KDP Uncategorised" },
  clearing: { label: "Amazon KDP royalties receivable (clearing)", account: "Amazon KDP Receivable" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);
const INCOME = new Set(["ebook", "paperback", "hardcover", "kenp"]);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

// "$1,234.56", "-$12.00", "(12.00)", "USD 5" and European "1.234,56" all read to cents. Empty is null, junk is NaN.
export function parseAmount(s) {
  let t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  t = t.replace(/^([-+]?)(?:[A-Za-z]{3})/, "$1").replace(/[$€£]/g, "");
  const paren = t.match(/^\((.*)\)$/);
  if (paren) t = "-" + paren[1];
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// A units or page count: whole numbers, thousands separators allowed. Empty or junk is 0.
const parseCount = (s) => { const n = Number(String(s ?? "").replace(/[,\s]/g, "")); return Number.isFinite(n) ? n : 0; };

const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const endOfMonth = (y, m) => `${y}-${String(m).padStart(2, "0")}-${String(new Date(Date.UTC(+y, +m, 0)).getUTCDate()).padStart(2, "0")}`;

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), "Sep 28, 2026", DD.MM.YYYY, slashed dates read per `order`,
// and month-only values ("2026-09", "September 2026"), which read as the last day of that month.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})$/))) { if (+x[2] < 1 || +x[2] > 12) return null; return endOfMonth(x[1], x[2]); }
  if ((x = t.match(/^([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$/)) && MONTHS[x[1].toLowerCase()]) return endOfMonth(x[2], MONTHS[x[1].toLowerCase()]);
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})/)) && MONTHS[x[1].toLowerCase()]) [m, d, y] = [MONTHS[x[1].toLowerCase()], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})/)) && MONTHS[x[2].toLowerCase()]) [d, m, y] = [x[1], MONTHS[x[2].toLowerCase()], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

// Format / transaction-type labels, matched loosely and in this order: a "Paperback printing cost" is a cost, not a
// paperback sale, and KENP page reads are not ebook sales. Anything else is reviewed, not guessed.
export function rowCategory(text) {
  const t = String(text || "").toLowerCase().trim();
  if (!t) return "uncategorised";
  if (/printing|print cost|manufactur/.test(t)) return "printing";
  if (/withh|tax held|tax-held|\btax\b/.test(t)) return "withholding";
  if (/kenp|pages? read|normali[sz]ed|kindle unlimited|\bku\b/.test(t)) return "kenp";
  if (/hardcover|hard cover|hardback/.test(t)) return "hardcover";
  if (/paperback|softcover|soft cover/.test(t)) return "paperback";
  if (/e-?book|kindle|digital/.test(t)) return "ebook";
  return "uncategorised";
}

const totalRowLabel = (cells) => { const f = cells.find((c) => c.trim()); return f ? /^(grand\s+)?totals?\b/i.test(f.trim()) : false; };

// Rows are grouped by currency (never converted). opts.printMode: "separate" (default: the royalty column is before
// printing cost) or "net" (the royalty column is already after it, so income is grossed up by the printing-cost
// column). opts.currency is the currency to assume when the file has no Currency column. opts.expected, when
// given, is the total you were paid (cents) for a single-currency file.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a KDP royalty report or payments CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    date: col("royalty-date", "date", "sales-date", "month", "sales-month", "reporting-month", "period", "payment-date", "transaction-date"),
    title: col("title", "book-title", "book", "name"),
    id: col("asin/isbn", "asin-isbn", "asin", "isbn", "isbn-13", "book-id", "id"),
    market: col("marketplace", "store", "amazon-store", "market", "country", "sales-channel"),
    format: col("format", "book-format", "product-type", "binding", "edition"),
    type: col("transaction-type", "type", "entry-type", "activity", "line-item"),
    kenp: col("kindle-edition-normalized-page-(kenp)-read", "kindle-edition-normalized-pages-(kenp)-read", "kenp-read", "kenp", "pages-read", "normalized-pages-read"),
    units: col("units-sold", "units", "net-units-sold", "quantity"),
    royalty: col("royalty", "royalty-amount", "royalties", "earnings", "amount", "gross-royalty", "royalty-before-costs"),
    printing: col("printing-cost", "print-cost", "printing-costs", "manufacturing-cost", "printing"),
    withheld: col("tax-withheld", "withholding", "withholding-tax", "tax-held", "tax-withholding", "withheld"),
    currency: col("currency", "royalty-currency", "payment-currency"),
    net: col("total", "net", "net-amount", "net-royalty", "net-payment", "payment", "payment-amount", "total-royalty", "net-total"),
  };
  const missing = [];
  if (I.date < 0) missing.push("date (Royalty Date, Date or Month)");
  if (I.format < 0 && I.type < 0) missing.push("format (Format or Transaction Type)");
  if (I.royalty < 0 && I.net < 0) missing.push("royalty amount (Royalty)");
  if (missing.length) {
    add("error", "This does not look like a KDP royalty report", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In KDP open Reports, choose the date range and download the royalty or payments report as CSV, then paste the whole file here. Column names are alias-matched and not verified against a real export, so a differently named column may need renaming.`, first + 1);
    return none;
  }
  const useNetAsRoyalty = I.royalty < 0;
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const rows = [];
  let total = null;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const rid = get(cells, "id") || get(cells, "title") || `line ${i + 1}`;
    if (totalRowLabel(cells)) {
      const num = (k) => (I[k] >= 0 ? parseAmount(get(cells, k)) : null);
      total = { line: i + 1, royalty: num("royalty"), printing: num("printing"), withheld: num("withheld"), net: num("net") };
      continue;
    }
    const royaltyRaw = parseAmount(get(cells, useNetAsRoyalty ? "net" : "royalty"));
    const printRaw = parseAmount(get(cells, "printing")), heldRaw = parseAmount(get(cells, "withheld"));
    const netRaw = useNetAsRoyalty ? null : parseAmount(get(cells, "net"));
    if ([royaltyRaw, printRaw, heldRaw, netRaw].some((v) => Number.isNaN(v))) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so the totals will not add up.", i + 1); continue; }
    if (royaltyRaw === null && printRaw === null && heldRaw === null) { add("warning", "Row has no amount", `${rid} was skipped.`, i + 1); continue; }
    const royalty = royaltyRaw ?? 0, print = Math.abs(printRaw ?? 0), held = Math.abs(heldRaw ?? 0);
    const fmtText = [get(cells, "format"), get(cells, "type")].join(" ").trim();
    const kenpPages = parseCount(get(cells, "kenp"));
    let key = rowCategory(fmtText);
    if (key === "uncategorised" && kenpPages > 0) key = "kenp";
    const created = parseDate(get(cells, "date"), opts.dateOrder);
    if (!created) add("warning", `Row ${rid} has no readable date`, `"${get(cells, "date")}" was not understood; the row is placed in the final month.`, i + 1);
    const cur = get(cells, "currency").toUpperCase();
    const market = get(cells, "market") || "Unspecified marketplace";
    let parts, gross = 0;
    if (key === "printing" || key === "withholding") parts = [{ k: key, amt: -Math.abs(royalty) }];
    else {
      const inc = opts.printMode === "net" ? royalty + print : royalty;
      parts = [{ k: key, amt: inc }];
      if (print) parts.push({ k: "printing", amt: -print });
      gross = INCOME.has(key) ? inc : 0;
    }
    if (held && key !== "withholding") parts.push({ k: "withholding", amt: -held });
    const net = parts.reduce((a, p) => a + p.amt, 0);
    const units = key === "kenp" && kenpPages > 0 ? kenpPages : parseCount(get(cells, "units"));
    if (netRaw !== null && netRaw !== net) add("error", `Total on ${rid} does not match its own columns`, `The row's Total column says ${money(netRaw, cur || "USD")} but its royalty${opts.printMode === "net" ? "" : " less printing cost"} less tax withheld is ${money(net, cur || "USD")} (off by ${money(netRaw - net, cur || "USD")}). A figure was edited or a column is missing from the paste.`, i + 1);
    rows.push({ line: i + 1, id: rid, item: get(cells, "title") || fmtText, type: fmtText, market, units, gross, net, netStated: netRaw, royalty, print, held, parts, created, currency: cur });
  }
  if (!rows.length) { add("error", "No royalty rows found", "The header was read but there were no data rows."); return none; }

  const fallback = String(opts.currency || "USD").toUpperCase();
  const haveCurrencyColumn = I.currency >= 0 && rows.some((r) => r.currency);
  if (!haveCurrencyColumn) add("warning", "No currency in the file", `The report has no Currency column, so every row is journalled as ${fallback} (the setting on this page). No exchange rate is applied; set the currency to what the report was paid in.`, 0);
  const by = new Map();
  for (const r of rows) {
    const c = r.currency || fallback;
    if (!by.has(c)) by.set(c, []);
    by.get(c).push(r);
  }
  if (by.size > 1) add("info", `${by.size} currencies in the file`, `${[...by.keys()].join(", ")}. Each currency is journalled separately in its own currency; no conversion is made, so convert in your accounting software if you need a base-currency figure.`, 0);

  const sum = (f) => rows.reduce((a, r) => a + f(r), 0);
  const single = by.size === 1;
  let stated = null;
  if (total) {
    if (!single) add("info", "A Total row was found in a multi-currency file", "A single total cannot be compared with rows in several currencies, so it was not checked. The per-row Total column, if present, was.", total.line);
    else {
      const cur = [...by.keys()][0];
      const cmp = (label, got, want) => { if (got !== null && !Number.isNaN(got) && got !== want) add("error", `Rows add up to ${money(want, cur)} but the Total row says ${money(got, cur)} (${label})`, `Off by ${money(got - want, cur)}. Rows are missing from the paste, or an amount was skipped or edited. Do not post these journals until the figures agree.`, total.line); };
      cmp("royalty", total.royalty, sum((r) => r.royalty));
      cmp("printing cost", total.printing === null ? null : Math.abs(total.printing), sum((r) => r.print));
      cmp("tax withheld", total.withheld === null ? null : Math.abs(total.withheld), sum((r) => r.held));
      stated = total.net !== null && !Number.isNaN(total.net) ? total.net : null;
      if (stated === null && total.royalty !== null && !Number.isNaN(total.royalty)) stated = total.royalty - (opts.printMode === "net" ? 0 : Math.abs(total.printing ?? 0)) - Math.abs(total.withheld ?? 0);
    }
  }
  const perRow = rows.every((r) => r.netStated !== null);
  if (stated === null && perRow) stated = sum((r) => r.netStated);
  if (!total && !perRow) add("warning", "No Total column or Total row, so completeness cannot be proved", "Without a per-row Total column or a Total row the page cannot tell if a row is missing. Download the full royalty report including its total and paste that.", 0);
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    if (!single) add("info", "The amount you entered was not checked", "It is compared only for a single-currency file.", 0);
    else if (opts.expected !== sum((r) => r.net)) add("warning", "The rows do not add up to the amount you entered", `The rows total ${money(sum((r) => r.net), [...by.keys()][0])} but you entered ${money(opts.expected, [...by.keys()][0])}. The report may stop before the payment period ends, or rows are missing.`, 0);
  }

  const payouts = [...by.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([cur, rs]) => {
    const effective = rs.map((r) => r.created).filter(Boolean).sort().pop() || null;
    return { id: `KDP-${cur}`, effective, stated: single ? stated : (perRow ? rs.reduce((a, r) => a + r.netStated, 0) : null), opening: null, currency: cur, rows: rs };
  });
  return { payouts, findings, summary: { rows: rows.length, payouts: payouts.length } };
}

// Gross by marketplace and format, with what KDP took out: the figures a bookkeeper wants per marketplace.
export function royaltySummary(payouts) {
  const byMarket = new Map();
  const tot = { gross: 0, printing: 0, withheld: 0, other: 0, net: 0 };
  for (const s of payouts) for (const r of s.rows) for (const p of r.parts) {
    const key = `${s.currency}|${r.market}|${p.k}`;
    const e = byMarket.get(key) || { currency: s.currency, market: r.market, category: p.k, amount: 0, units: 0 };
    e.amount += p.amt;
    if (INCOME.has(p.k) && p === r.parts[0]) e.units += r.units;
    byMarket.set(key, e);
    if (INCOME.has(p.k)) tot.gross += p.amt;
    else if (p.k === "printing") tot.printing -= p.amt;
    else if (p.k === "withholding") tot.withheld -= p.amt;
    else tot.other += p.amt;
    tot.net += p.amt;
  }
  return { rows: [...byMarket.values()].sort((a, b) => a.currency.localeCompare(b.currency) || a.market.localeCompare(b.market) || CATEGORY_ORDER.indexOf(a.category) - CATEGORY_ORDER.indexOf(b.category)), ...tot, printingShare: tot.gross > 0 ? tot.printing / tot.gross : null };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a currency group touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.stated === null) findings.push({ severity: "warning", title: `The ${cur} royalties could not be checked`, detail: `The rows add up to ${money(sum, cur)}. Without a Total column or Total row the page cannot prove nothing is missing.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Rows add up to ${money(sum, cur)} but the report's total is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)} (${cur}). Rows are missing from the paste, or an amount was skipped or edited. Do not post these journals until the figures agree.`, line: 0 });

    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      for (const p of r.parts) {
        if (!p.amt) continue;
        const key = `${p.k}\u0000${r.market}`;
        const e = m.get(key) || { k: p.k, market: r.market, net: 0, count: 0 };
        e.net += p.amt; e.count++; m.set(key, e);
      }
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} had no readable date`, detail: "They were placed in the final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `The ${cur} rows span ${keys.length} months`, detail: `Written as ${keys.length} ${cur} journals (${keys.join(", ")}), each balanced to the KDP receivable account, so every month's royalties and costs land in the month they were reported.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing") continue;
        for (const e of [...m.values()].filter((x) => x.k === k).sort((a, b) => a.market.localeCompare(b.market))) {
          if (e.net === 0) continue;
          const where = ` - ${e.market}`;
          lines.push({ category: k, account: mapping[k], debit: e.net < 0 ? -e.net : 0, credit: e.net > 0 ? e.net : 0, memo: `${CATEGORIES[k].label}${where} (${e.count} row${e.count === 1 ? "" : "s"})`, market: e.market });
        }
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Royalties owed by Amazon KDP (${ym}, ${cur})`, market: "" });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `KDP royalties ${ym} (${cur})`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.type || r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the total. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summaryByMarket: royaltySummary(p.payouts), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative. Xero's file has no currency column: the currency is in the narration.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)} [${j.currency}]`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["group", "period", "date", "currency", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, j.currency, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Royalty Date", "Title", "ASIN/ISBN", "Marketplace", "Format", "Units Sold", "Royalty", "Printing Cost", "Tax Withheld", "Currency", "Total"];

// items: [date, title, id, marketplace, format, units, royalty, printing, withheld, currency]. Each row's Total is
// royalty - printing - withheld. `skip` drops rows from the output as a hand-edited paste would; `mangleTotal`
// replaces a row's Total text; `mangle` replaces a row's Royalty text; `totalRow` appends a Total row (one currency only).
export function buildReport({ items, skip = [], mangle = {}, mangleTotal = {}, totalRow = false, totalOverride = {} }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const f = (c) => (c / 100).toFixed(2);
  const rows = items.map(([date, title, id, market, fmt, units, roy, print, held, cur], n) => {
    const r = Math.round(roy * 100), p = Math.round(print * 100), h = Math.round(held * 100);
    return [date, title, id, market, fmt, units, mangle[n] ?? f(r), p ? f(p) : "", h ? f(h) : "", cur, mangleTotal[n] ?? f(r - p - h)].map(csv).join(",");
  });
  const kept = rows.filter((_, n) => !skip.includes(n));
  const out = [HEAD.join(","), ...kept];
  if (totalRow) {
    const r = items.reduce((a, x) => a + Math.round(x[6] * 100), 0), p = items.reduce((a, x) => a + Math.round(x[7] * 100), 0), h = items.reduce((a, x) => a + Math.round(x[8] * 100), 0);
    out.push(["Total", "", "", "", "", items.reduce((a, x) => a + x[5], 0), f(totalOverride.royalty ?? r), f(totalOverride.printing ?? p), f(totalOverride.withheld ?? h), "", totalOverride.net ?? f(r - p - h)].join(","));
  }
  return out.join("\n") + "\n";
}

// A made-up author: invented titles, ASINs and amounts.
const SAMPLE_ITEMS = [
  ["2026-08", "The Lantern Keeper", "B0EXAMPLE1", "Amazon.com", "Kindle eBook", 120, 252.00, 0, 0, "USD"],
  ["2026-08", "The Lantern Keeper", "B0EXAMPLE1", "Amazon.com", "Paperback", 40, 150.00, 56.00, 0, "USD"],
  ["2026-08", "The Lantern Keeper", "B0EXAMPLE1", "Amazon.com", "Kindle Edition Normalized Pages (KENP) read", 18000, 90.00, 0, 0, "USD"],
  ["2026-08", "The Lantern Keeper", "B0EXAMPLE1", "Amazon.co.uk", "Kindle eBook", 30, 48.00, 0, 0, "GBP"],
  ["2026-09", "The Lantern Keeper", "B0EXAMPLE1", "Amazon.com", "Kindle eBook", 100, 210.00, 0, 0, "USD"],
  ["2026-09", "The Lantern Keeper", "B0EXAMPLE1", "Amazon.com", "Paperback", 55, 205.00, 77.00, 0, "USD"],
  ["2026-09", "Salt and Signal", "B0EXAMPLE2", "Amazon.com", "Hardcover", 12, 60.00, 30.00, 0, "USD"],
  ["2026-09", "Salt and Signal", "B0EXAMPLE2", "Amazon.de", "Kindle eBook", 25, 40.00, 0, 6.00, "EUR"],
];

export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS });
// The same report after a hand edit: one row's Total altered, one royalty that is not a number, and a format no rule knows.
export function sampleBrokenReport() {
  const items = [...SAMPLE_ITEMS, ["2026-09", "Salt and Signal", "B0EXAMPLE2", "Amazon.com", "Audio Replica", 3, 9.00, 0, 0, "USD"], ["2026-09", "Salt and Signal", "B0EXAMPLE2", "Amazon.com", "Kindle eBook", 4, 8.00, 0, 0, "USD"]];
  return buildReport({ items, mangleTotal: { 1: "100.00" }, mangle: { 9: "8..0" } });
}

engines/kofi.mjs.text:
// Ko-fi earnings export -> accounting journal.
//
// Ko-fi pays creators through PayPal or Stripe, so the money that lands is net of processing
// fees (and Ko-fi's cut on memberships, shop sales and commissions on the free plan) and mixes
// tips, memberships, shop orders and commissions. Bookkeepers need those split out, and a month end
// respected. This module reads the Ko-fi transactions CSV (Ko-fi > Dashboard > Transactions >
// Download CSV: DateTime, From, Item, Received, Given, Currency, TransactionType, ...), books each
// transaction to an income account by its TransactionType, derives the fee as Given - Received,
// proves the rows add up to the deposit you type in from PayPal or your bank, proves the rows add up to the payout, and writes balanced journals for Xero,
// QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV.
//
// The export's column names and each importer's column layout are from memory of public Ko-fi
// and accounting help documents; no real Ko-fi export and no live Xero or QuickBooks import was
// available when this was written. Column names are matched by several aliases, a sale whose
// parts do not add to its net is flagged, and a row no rule explains is never dropped: it lands in an
// "uncategorised" line and is reported, so the journal still equals the net.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  donations: { label: "Ko-fi donations and tips (gross)", account: "Ko-fi Donation Income" },
  memberships: { label: "Ko-fi memberships (gross)", account: "Ko-fi Membership Income" },
  shop: { label: "Ko-fi shop orders (gross)", account: "Ko-fi Shop Income" },
  commissions: { label: "Ko-fi commissions (gross)", account: "Ko-fi Commission Income" },
  shipping: { label: "Shipping charged to buyers", account: "Ko-fi Shipping Income" },
  tax: { label: "Sales tax / VAT you collected (liability)", account: "Ko-fi Sales Tax Payable" },
  refunds: { label: "Refunds", account: "Ko-fi Refunds" },
  fees: { label: "Ko-fi and payment processing fees", account: "Ko-fi Fees" },
  uncategorised: { label: "Uncategorised Ko-fi items", account: "Ko-fi Uncategorised" },
  clearing: { label: "Ko-fi clearing (matches the payout deposit)", account: "Ko-fi Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

// Ko-fi TransactionType values: Donation, Subscription, Shop Order, Commission (matched loosely).
export function incomeCategory(type) {
  const t = String(type || "").toLowerCase();
  if (/donat|tip|coffee/.test(t)) return "donations";
  if (/subscr|member/.test(t)) return "memberships";
  if (/shop|order|product|digital|physical/.test(t)) return "shop";
  if (/commission/.test(t)) return "commissions";
  return t ? "uncategorised" : "donations"; // a blank type is a plain tip; an unknown one is reviewed
}

const UNPAID = "(no payout ID)";
const ALL = "all rows";
const TRUE = /^(true|yes|y|1|refunded)$/i;

// Rows are grouped by payout id when the export has one; otherwise the whole file is one group and
// the deposit is supplied by the caller (opts.expected, from the bank / PayPal / Ko-fi payouts page).
// An optional `type` column containing "payout" states the deposit.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Ko-fi earnings CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    payout: col("payout-id", "payout", "payout-reference"),
    effective: col("payout-date", "paid-out-on", "payout-created-at"),
    id: col("transactionid", "transaction-id", "charge-id", "sale-id", "purchase-id", "order-id", "id"),
    created: col("datetime", "date-time", "charge-date", "date", "purchase-date", "sale-date", "created-at", "created"),
    currency: col("currency", "price-currency"),
    price: col("given", "pledge-amount", "pledge", "price", "amount", "gross", "charge-amount"),
    shipping: col("shipping", "shipping-price"),
    tax: col("salestax", "taxes", "tax", "sales-tax", "vat"),
    fee: col("fees", "fee", "ko-fi-fees", "ko-fi-fee", "total-fees"),
    platformFee: col("platform-fee", "platform-fees", "ko-fi-platform-fee"),
    processingFee: col("processing-fee", "payment-processing-fee", "processing-fees"),
    net: col("received", "net-total", "net", "net-earnings", "seller-revenue", "you-receive"),
    refunded: col("refunded", "is-refunded", "refunded?", "refund"),
    refundAmt: col("refunded-amount", "amount-refunded"),
    item: col("item", "tier", "reward-tier", "item-name", "product-name", "product", "item", "patron"),
    type: col("transactiontype", "type", "transaction-type"),
  };
  const missing = [];
  if (I.net < 0) missing.push("amount received");
  if (I.price < 0) missing.push("amount given");
  if (missing.length) {
    add("error", "This does not look like a Ko-fi transactions export", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Ko-fi open Dashboard > Transactions (or Settings > Data export) and choose Download CSV, then paste the whole file here.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, effective: null, stated: null, currency: "", rows: [] }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const rid = get(cells, "id") || `line ${i + 1}`;
    const pid = I.payout >= 0 ? get(cells, "payout") || UNPAID : ALL;
    const s = bucket(pid);
    const eff = parseDate(get(cells, "effective"), opts.dateOrder);
    if (eff && !s.effective) s.effective = eff;
    const netS = get(cells, "net"), net = parseAmount(netS);
    if (/^payout/i.test(get(cells, "type"))) { if (net !== null && !Number.isNaN(net)) s.stated = (s.stated || 0) + Math.abs(net); continue; } // the deposit itself
    if (net === null) { add("warning", "Row has no net total", `${rid} was skipped.`, i + 1); continue; }
    const amts = {};
    let bad = Number.isNaN(net);
    for (const k of ["price", "shipping", "tax", "fee", "platformFee", "processingFee", "refundAmt"]) { const v = parseAmount(get(cells, k)); if (Number.isNaN(v)) bad = true; amts[k] = v == null ? 0 : v; }
    if (bad) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in ${pid === ALL ? "the export" : `payout ${pid}`}`, `${cur} row among ${s.currency} rows. Journals assume one currency per payout.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    const refunded = TRUE.test(get(cells, "refunded")) || amts.refundAmt > 0;
    // Ko-fi fee columns are usually positive numbers meaning a cost; a negative one is read as a cost too.
    // Ko-fi reports a platform fee and a processing fee as separate columns; both are summed (a combined fee column wins when present).
    // Ko-fi's export has no fee column: the fee is what the supporter gave minus what you received.
    const derived = I.fee < 0 && I.platformFee < 0 && I.processingFee < 0;
    const fee = derived ? amts.price + amts.shipping - net : I.fee >= 0 ? Math.abs(amts.fee) : Math.abs(amts.platformFee) + Math.abs(amts.processingFee);
    if (derived && fee < 0) add("warning", `${rid}: received is more than given`, "The fee came out negative, so the extra is booked as a negative fee. Check the Received and Given columns were not swapped.", i + 1);
    const incomeKey = incomeCategory(get(cells, "type"));
    const parts = [];
    const push = (k, amt) => { if (amt) parts.push({ k, amt }); };
    push(incomeKey, amts.price);
    push("shipping", amts.shipping);
    // Tax is the buyer's, so it only belongs in the payout when the row's own arithmetic says Ko-fi paid it out.
    const taxInNet = amts.tax !== 0 && amts.price + amts.shipping + amts.tax - fee === net + (refunded ? (amts.refundAmt || amts.price + amts.shipping + amts.tax) : 0);
    if (taxInNet) push("tax", amts.tax);
    push("fees", -fee);
    if (refunded) push("refunds", -(amts.refundAmt || amts.price + amts.shipping + (taxInNet ? amts.tax : 0)));
    let residual = net - parts.reduce((a, p) => a + p.amt, 0);
    if (residual !== 0) {
      if (refunded) { push("fees", residual); add("info", `${rid}: refunded sale's fee adjusted by ${money(residual)}`, "The net total on a refunded sale differs from price minus fee minus refund; the difference is booked to fees (Ko-fi returning or keeping its fee).", i + 1); }
      else { push("uncategorised", residual); add("error", `Parts do not add up to the net total on ${rid}`, `Price ${money(amts.price)} + shipping ${money(amts.shipping)} - fee ${money(fee)} = ${money(amts.price + amts.shipping - fee)}, but the row says ${money(net)}. The ${money(residual)} difference is journalled to "uncategorised"; check the file was not edited.`, i + 1); }
    }
    s.rows.push({ line: i + 1, id: rid, item: get(cells, "item"), gross: amts.price, fee, net, refunded, parts, created: parseDate(get(cells, "created"), opts.dateOrder) });
    rows++;
  }
  const payouts = [...byId.values()].filter((s) => s.rows.length || s.stated !== null);
  if (!payouts.length) add("error", "No sales rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    const real = payouts.filter((s) => s.id !== UNPAID);
    if (real.length === 1 && real[0].stated === null) real[0].stated = opts.expected;
    else if (real.length !== 1) add("info", "Expected deposit ignored", "It can only be applied when the file holds exactly one payout (or no payout column) without a deposit row of its own.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.id === UNPAID) findings.push({ severity: "warning", title: `${s.rows.length} row${s.rows.length === 1 ? "" : "s"} have no payout ID`, detail: "They have no payout ID in the report. They are journalled to Ko-fi clearing as a separate group and will not match a bank deposit yet.", line: 0 });
    else if (s.stated === null) findings.push({ severity: "warning", title: `${s.id === ALL ? "The export" : `Payout ${s.id}`} has no payout row and no expected deposit`, detail: `The rows add up to ${money(sum, cur)}. Enter the deposit from your bank, PayPal or Ko-fi payout in the box above to check it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Payout ${s.id}: rows add up to ${money(sum, cur)} but the payout is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const p of r.parts) add(p.k, p.amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in payout ${s.id} had no created date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Payout ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Ko-fi clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Payout ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Ko-fi payout ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `Payout ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.id === UNPAID ? null : s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.id === UNPAID || s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["DateTime (UTC)", "From", "Message", "Item", "Received", "Given", "Currency", "TransactionType", "TransactionId", "Reference"];

// items: [date, from, item, type, given, received]. A deposit row is added when `withPayoutRow`
// (a real export has none, so the deposit is normally typed in from PayPal, Stripe or the bank).
export function buildReport({ currency = "USD", items, withPayoutRow = false, totalOverride }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const out = [HEAD.join(",")];
  let net = 0, n = 0;
  for (const [date, from, item, type, given, received] of items) {
    n++;
    if (typeof received === "number") net += Math.round(received * 100);
    const f = (v) => (typeof v === "number" ? v.toFixed(2) : v);
    out.push([`${date} 12:00:00`, from, "", item, f(received), f(given), currency, type, `T${1000 + n}`, `ref-${n}`].map(csv).join(","));
  }
  if (withPayoutRow) out.push(["", "", "", "", (totalOverride ?? net / 100).toFixed(2), "", currency, "Payout", "", ""].map(csv).join(","));
  return out.join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-28", "Alex", "Ko-fi Donation", "Donation", 5.00, 4.85],
  ["2026-09-29", "Sam", "Gold supporter", "Subscription", 10.00, 9.35],
  ["2026-09-30", "Jo", "Sticker pack", "Shop Order", 18.00, 16.75],
  ["2026-10-01", "Kim", "Character portrait", "Commission", 120.00, 112.10],
  ["2026-10-02", "Riley", "Ko-fi Donation", "Donation", 3.00, 2.90],
  ["2026-10-03", "Sam", "Gold supporter", "Subscription", 10.00, 9.35],
];

const deposit = (items) => items.reduce((a, r) => a + Math.round(r[5] * 100), 0) / 100;
export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS, withPayoutRow: true });
// The same export after a hand edit: a transaction dropped from the paste so the payout no longer agrees,
// one amount that is not a number, one type no rule knows, and one row whose columns look swapped.
export function sampleBrokenReport() {
  const items = SAMPLE_ITEMS.slice(0, -1);
  items.push(["2026-10-04", "Lee", "Mystery item", "Gift Card", 10.00, 9.00]);
  items.push(["2026-10-04", "Max", "Ko-fi Donation", "Donation", 5.00, "4..5"]);
  items.push(["2026-10-05", "Dee", "Ko-fi Donation", "Donation", 4.00, 4.50]);
  return buildReport({ items, totalOverride: deposit(SAMPLE_ITEMS), withPayoutRow: true });
}

engines/paddle.mjs.text:
// Paddle earnings export -> accounting journal.
//
// Paddle pays creators a net deposit that hides the sales, the Paddle fee and any refunds.
// Bookkeepers need those split out, and a payout that straddles a month end split in two.
// This module reads the earnings CSV (Paddle Orders export, or the Payouts
// "download CSV"), splits every sale into sales, shipping income, tax you collected, fees and
// refunds, proves the rows add up to the payout, and writes balanced journals for Xero,
// QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV.
//
// The export's column names and each importer's column layout are from memory of public Paddle
// and accounting help documents; no real Paddle export and no live Xero or QuickBooks import was
// available when this was written. Column names are matched by several aliases, a sale whose
// parts do not add to its net is flagged, and a row no rule explains is never dropped: it lands in an
// "uncategorised" line and is reported, so the journal still equals the net.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Paddle Product Sales (gross)", account: "Paddle Product Sales" },
  shipping: { label: "Shipping charged to buyers", account: "Paddle Shipping Income" },
  tax: { label: "Sales tax / VAT you collected (liability)", account: "Paddle Sales Tax Payable" },
  refunds: { label: "Refunds", account: "Paddle Refunds" },
  fees: { label: "Paddle platform and processing fees", account: "Paddle Fees" },
  uncategorised: { label: "Uncategorised Paddle items", account: "Paddle Uncategorised" },
  clearing: { label: "Paddle clearing (matches the payout deposit)", account: "Paddle Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const UNPAID = "(no payout ID)";
const ALL = "all rows";
const TRUE = /^(true|yes|y|1|refunded)$/i;

// Rows are grouped by payout id when the export has one; otherwise the whole file is one group and
// the deposit is supplied by the caller (opts.expected, from the bank / PayPal / Paddle payouts page).
// An optional `type` column containing "payout" states the deposit.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Paddle earnings CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    payout: col("payout-id", "payout", "payout-reference"),
    effective: col("payout-date", "paid-out-on", "payout-created-at", "payout-paid-at"),
    id: col("transaction-id", "order-id", "checkout-id", "charge-id", "sale-id", "purchase-id", "id"),
    created: col("billed-at", "transaction-date", "sale-date", "event-time", "charge-date", "date", "purchase-date", "created-at", "created"),
    currency: col("currency", "price-currency"),
    price: col("subtotal", "sale-gross", "gross-amount", "sale-amount", "pledge-amount", "price", "amount", "gross", "charge-amount"),
    shipping: col("shipping", "shipping-price"),
    tax: col("taxes", "tax", "sales-tax", "vat"),
    fee: col("fees", "fee", "paddle-fees", "paddle-fee", "paddle-fees", "total-fees"),
    platformFee: col("platform-fee", "platform-fees", "paddle-platform-fee"),
    processingFee: col("processing-fee", "payment-processing-fee", "processing-fees"),
    net: col("earnings", "net-total", "net", "net-earnings", "seller-revenue", "you-receive", "payout-amount"),
    refunded: col("refunded", "is-refunded", "refunded?", "refund"),
    refundAmt: col("refunded-amount", "amount-refunded"),
    item: col("product", "product-name", "price-name", "variant", "tier", "reward-tier", "item-name", "product-name", "product", "item", "patron"),
    type: col("type", "transaction-type"),
  };
  const missing = [];
  if (I.net < 0) missing.push("earnings (net)");
  if (I.price < 0) missing.push("sale amount (subtotal or sale gross)");
  const grossIncludesTax = I.price >= 0 && ["sale-gross", "gross-amount", "gross"].includes(head[I.price]);
  if (missing.length) {
    add("error", "This does not look like a Paddle transaction or payout export", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Paddle open Insights / Payouts and choose Export / Download CSV, then paste the whole file here.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, effective: null, stated: null, currency: "", rows: [] }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const rid = get(cells, "id") || `line ${i + 1}`;
    const pid = I.payout >= 0 ? get(cells, "payout") || UNPAID : ALL;
    const s = bucket(pid);
    const eff = parseDate(get(cells, "effective"), opts.dateOrder);
    if (eff && !s.effective) s.effective = eff;
    const netS = get(cells, "net"), net = parseAmount(netS);
    if (/^payout/i.test(get(cells, "type"))) { if (net !== null && !Number.isNaN(net)) s.stated = (s.stated || 0) + Math.abs(net); continue; } // the deposit itself
    if (net === null) { add("warning", "Row has no net total", `${rid} was skipped.`, i + 1); continue; }
    const amts = {};
    let bad = Number.isNaN(net);
    for (const k of ["price", "shipping", "tax", "fee", "platformFee", "processingFee", "refundAmt"]) { const v = parseAmount(get(cells, k)); if (Number.isNaN(v)) bad = true; amts[k] = v == null ? 0 : v; }
    if (bad) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in ${pid === ALL ? "the export" : `payout ${pid}`}`, `${cur} row among ${s.currency} rows. Journals assume one currency per payout.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    const refunded = TRUE.test(get(cells, "refunded")) || amts.refundAmt > 0;
    // Paddle fee columns are usually positive numbers meaning a cost; a negative one is read as a cost too.
    // Paddle reports a platform fee and a processing fee as separate columns; both are summed (a combined fee column wins when present).
    const fee = I.fee >= 0 ? Math.abs(amts.fee) : Math.abs(amts.platformFee) + Math.abs(amts.processingFee);
    const parts = [];
    const push = (k, amt) => { if (amt) parts.push({ k, amt }); };
    push("sales", amts.price);
    push("shipping", amts.shipping);
    // Tax is the buyer's, so it only belongs in the payout when the row's own arithmetic says Paddle paid it out.
    // Paddle is merchant of record: when the sale amount is a tax-inclusive gross and gross - tax - fee equals the earnings,
    // the tax was remitted by Paddle and never reached you, so it is taken out of income rather than booked as a payable.
    if (grossIncludesTax && amts.tax !== 0 && amts.price - Math.abs(amts.tax) - fee === net + (refunded ? (amts.refundAmt || amts.price) : 0) - (refunded ? 0 : 0) && !refunded) { amts.price -= Math.abs(amts.tax); amts.tax = 0; }
    const taxInNet = amts.tax !== 0 && amts.price + amts.shipping + amts.tax - fee === net + (refunded ? (amts.refundAmt || amts.price + amts.shipping + amts.tax) : 0);
    if (taxInNet) push("tax", amts.tax);
    push("fees", -fee);
    if (refunded) push("refunds", -(amts.refundAmt || amts.price + amts.shipping + (taxInNet ? amts.tax : 0)));
    let residual = net - parts.reduce((a, p) => a + p.amt, 0);
    if (residual !== 0) {
      if (refunded) { push("fees", residual); add("info", `${rid}: refunded sale's fee adjusted by ${money(residual)}`, "The net total on a refunded sale differs from price minus fee minus refund; the difference is booked to fees (Paddle returning or keeping its fee).", i + 1); }
      else { push("uncategorised", residual); add("error", `Parts do not add up to the net total on ${rid}`, `Price ${money(amts.price)} + shipping ${money(amts.shipping)} - fee ${money(fee)} = ${money(amts.price + amts.shipping - fee)}, but the row says ${money(net)}. The ${money(residual)} difference is journalled to "uncategorised"; check the file was not edited.`, i + 1); }
    }
    s.rows.push({ line: i + 1, id: rid, item: get(cells, "item"), gross: amts.price, fee, net, refunded, parts, created: parseDate(get(cells, "created"), opts.dateOrder) });
    rows++;
  }
  const payouts = [...byId.values()].filter((s) => s.rows.length || s.stated !== null);
  if (!payouts.length) add("error", "No sales rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    const real = payouts.filter((s) => s.id !== UNPAID);
    if (real.length === 1 && real[0].stated === null) real[0].stated = opts.expected;
    else if (real.length !== 1) add("info", "Expected deposit ignored", "It can only be applied when the file holds exactly one payout (or no payout column) without a deposit row of its own.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.id === UNPAID) findings.push({ severity: "warning", title: `${s.rows.length} row${s.rows.length === 1 ? "" : "s"} have no payout ID`, detail: "They have no payout ID in the report. They are journalled to Paddle clearing as a separate group and will not match a bank deposit yet.", line: 0 });
    else if (s.stated === null) findings.push({ severity: "warning", title: `${s.id === ALL ? "The export" : `Payout ${s.id}`} has no payout row and no expected deposit`, detail: `The rows add up to ${money(sum, cur)}. Enter the deposit from your bank, PayPal or Paddle payout in the box above to check it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Payout ${s.id}: rows add up to ${money(sum, cur)} but the payout is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const p of r.parts) add(p.k, p.amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in payout ${s.id} had no created date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Payout ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Paddle clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Payout ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Paddle payout ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `Payout ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.id === UNPAID ? null : s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.id === UNPAID || s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Type", "Transaction ID", "Product", "Billed At", "Subtotal", "Shipping", "Tax", "Paddle Fee", "Earnings", "Currency", "Refunded", "Payout ID"];

// items: [date, item, price, fee, refunded, shipping]. A deposit row is added when `withPayoutRow`
// (real exports usually have none, so the deposit is then typed in from the bank).
export function buildReport({ id = "P-2026-10", currency = "USD", items, withPayoutRow = false, totalOverride }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const out = [HEAD.join(",")];
  let net = 0, n = 0;
  for (const [date, item, price, fee, refunded, shipping] of items) {
    n++;
    const bad = typeof price === "string";
    const ship = shipping || 0;
    const nn = bad ? NaN : refunded ? -fee : price + ship - fee;
    if (!Number.isNaN(nn)) net += Math.round(nn * 100);
    out.push(["sale", `txn_${1000 + n}`, item, `${date}T12:00:00Z`, bad ? price : price.toFixed(2), ship.toFixed(2), "0.00", fee.toFixed(2), bad ? price : nn.toFixed(2), currency, refunded ? "true" : "false", id].map(csv).join(","));
  }
  if (withPayoutRow) out.push(["payout", "", "", "", "", "", "", "", ((totalOverride ?? net / 100)).toFixed(2), currency, "", id].map(csv).join(","));
  return out.join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-28", "Supporter tier", 29.00, 3.70, false],
  ["2026-09-29", "Patron tier", 149.00, 15.40, false],
  ["2026-09-30", "Early-access tier", 19.00, 2.35, false],
  ["2026-10-01", "Patron tier", 149.00, 15.40, false],
  ["2026-10-02", "Supporter tier", 29.00, 3.70, true],
  ["2026-10-03", "Postcard reward", 35.00, 4.25, false, 6.50],
];

const deposit = (items) => items.reduce((a, r) => a + Math.round(((r[4] ? 0 : r[2] + (r[5] || 0)) - r[3]) * 100), 0) / 100;
export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS, withPayoutRow: true });
// The same export after a hand edit: a row dropped from the paste so the payout no longer agrees,
// one sale whose parts do not add to its net, and one amount that is not a number.
export function sampleBrokenReport() {
  const items = SAMPLE_ITEMS.filter((r) => r[1] !== "Postcard reward");
  items.push(["2026-10-04", "Mystery item", 10.00, 1.00, false]);
  items.push(["2026-10-04", "Extra tier", "12..5", 1.00, false]);
  return buildReport({ items, totalOverride: deposit(SAMPLE_ITEMS), withPayoutRow: true }).replace("10.00,0.00,0.00,1.00,9.00,", "10.00,0.00,0.00,1.00,7.00,");
}

engines/patreon.mjs.text:
// Patreon earnings export -> accounting journal.
//
// Patreon pays creators a net deposit that hides the sales, the Patreon fee and any refunds.
// Bookkeepers need those split out, and a payout that straddles a month end split in two.
// This module reads the earnings CSV (Patreon Insights > Earnings export, or the Payouts
// "download CSV"), splits every sale into sales, shipping income, tax you collected, fees and
// refunds, proves the rows add up to the payout, and writes balanced journals for Xero,
// QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV.
//
// The export's column names and each importer's column layout are from memory of public Patreon
// and accounting help documents; no real Patreon export and no live Xero or QuickBooks import was
// available when this was written. Column names are matched by several aliases, a sale whose
// parts do not add to its net is flagged, and a row no rule explains is never dropped: it lands in an
// "uncategorised" line and is reported, so the journal still equals the net.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Patreon Membership Income (gross)", account: "Patreon Membership Income" },
  shipping: { label: "Shipping charged to buyers", account: "Patreon Shipping Income" },
  tax: { label: "Sales tax / VAT you collected (liability)", account: "Patreon Sales Tax Payable" },
  refunds: { label: "Refunds", account: "Patreon Refunds" },
  fees: { label: "Patreon platform and processing fees", account: "Patreon Fees" },
  uncategorised: { label: "Uncategorised Patreon items", account: "Patreon Uncategorised" },
  clearing: { label: "Patreon clearing (matches the payout deposit)", account: "Patreon Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const UNPAID = "(no payout ID)";
const ALL = "all rows";
const TRUE = /^(true|yes|y|1|refunded)$/i;

// Rows are grouped by payout id when the export has one; otherwise the whole file is one group and
// the deposit is supplied by the caller (opts.expected, from the bank / PayPal / Patreon payouts page).
// An optional `type` column containing "payout" states the deposit.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Patreon earnings CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    payout: col("payout-id", "payout", "payout-reference"),
    effective: col("payout-date", "paid-out-on", "payout-created-at"),
    id: col("charge-id", "sale-id", "purchase-id", "order-id", "id"),
    created: col("charge-date", "date", "purchase-date", "sale-date", "created-at", "created"),
    currency: col("currency", "price-currency"),
    price: col("pledge-amount", "pledge", "price", "amount", "gross", "charge-amount"),
    shipping: col("shipping", "shipping-price"),
    tax: col("taxes", "tax", "sales-tax", "vat"),
    fee: col("fees", "fee", "patreon-fees", "patreon-fee", "total-fees"),
    platformFee: col("platform-fee", "platform-fees", "patreon-platform-fee"),
    processingFee: col("processing-fee", "payment-processing-fee", "processing-fees"),
    net: col("net-total", "net", "net-earnings", "seller-revenue", "you-receive"),
    refunded: col("refunded", "is-refunded", "refunded?", "refund"),
    refundAmt: col("refunded-amount", "amount-refunded"),
    item: col("tier", "reward-tier", "item-name", "product-name", "product", "item", "patron"),
    type: col("type", "transaction-type"),
  };
  const missing = [];
  if (I.net < 0) missing.push("net total");
  if (I.price < 0) missing.push("pledge amount");
  if (missing.length) {
    add("error", "This does not look like a Patreon earnings export", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Patreon open Insights / Payouts and choose Export / Download CSV, then paste the whole file here.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, effective: null, stated: null, currency: "", rows: [] }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const rid = get(cells, "id") || `line ${i + 1}`;
    const pid = I.payout >= 0 ? get(cells, "payout") || UNPAID : ALL;
    const s = bucket(pid);
    const eff = parseDate(get(cells, "effective"), opts.dateOrder);
    if (eff && !s.effective) s.effective = eff;
    const netS = get(cells, "net"), net = parseAmount(netS);
    if (/^payout/i.test(get(cells, "type"))) { if (net !== null && !Number.isNaN(net)) s.stated = (s.stated || 0) + Math.abs(net); continue; } // the deposit itself
    if (net === null) { add("warning", "Row has no net total", `${rid} was skipped.`, i + 1); continue; }
    const amts = {};
    let bad = Number.isNaN(net);
    for (const k of ["price", "shipping", "tax", "fee", "platformFee", "processingFee", "refundAmt"]) { const v = parseAmount(get(cells, k)); if (Number.isNaN(v)) bad = true; amts[k] = v == null ? 0 : v; }
    if (bad) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in ${pid === ALL ? "the export" : `payout ${pid}`}`, `${cur} row among ${s.currency} rows. Journals assume one currency per payout.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    const refunded = TRUE.test(get(cells, "refunded")) || amts.refundAmt > 0;
    // Patreon fee columns are usually positive numbers meaning a cost; a negative one is read as a cost too.
    // Patreon reports a platform fee and a processing fee as separate columns; both are summed (a combined fee column wins when present).
    const fee = I.fee >= 0 ? Math.abs(amts.fee) : Math.abs(amts.platformFee) + Math.abs(amts.processingFee);
    const parts = [];
    const push = (k, amt) => { if (amt) parts.push({ k, amt }); };
    push("sales", amts.price);
    push("shipping", amts.shipping);
    // Tax is the buyer's, so it only belongs in the payout when the row's own arithmetic says Patreon paid it out.
    const taxInNet = amts.tax !== 0 && amts.price + amts.shipping + amts.tax - fee === net + (refunded ? (amts.refundAmt || amts.price + amts.shipping + amts.tax) : 0);
    if (taxInNet) push("tax", amts.tax);
    push("fees", -fee);
    if (refunded) push("refunds", -(amts.refundAmt || amts.price + amts.shipping + (taxInNet ? amts.tax : 0)));
    let residual = net - parts.reduce((a, p) => a + p.amt, 0);
    if (residual !== 0) {
      if (refunded) { push("fees", residual); add("info", `${rid}: refunded sale's fee adjusted by ${money(residual)}`, "The net total on a refunded sale differs from price minus fee minus refund; the difference is booked to fees (Patreon returning or keeping its fee).", i + 1); }
      else { push("uncategorised", residual); add("error", `Parts do not add up to the net total on ${rid}`, `Price ${money(amts.price)} + shipping ${money(amts.shipping)} - fee ${money(fee)} = ${money(amts.price + amts.shipping - fee)}, but the row says ${money(net)}. The ${money(residual)} difference is journalled to "uncategorised"; check the file was not edited.`, i + 1); }
    }
    s.rows.push({ line: i + 1, id: rid, item: get(cells, "item"), gross: amts.price, fee, net, refunded, parts, created: parseDate(get(cells, "created"), opts.dateOrder) });
    rows++;
  }
  const payouts = [...byId.values()].filter((s) => s.rows.length || s.stated !== null);
  if (!payouts.length) add("error", "No sales rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    const real = payouts.filter((s) => s.id !== UNPAID);
    if (real.length === 1 && real[0].stated === null) real[0].stated = opts.expected;
    else if (real.length !== 1) add("info", "Expected deposit ignored", "It can only be applied when the file holds exactly one payout (or no payout column) without a deposit row of its own.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.id === UNPAID) findings.push({ severity: "warning", title: `${s.rows.length} row${s.rows.length === 1 ? "" : "s"} have no payout ID`, detail: "They have no payout ID in the report. They are journalled to Patreon clearing as a separate group and will not match a bank deposit yet.", line: 0 });
    else if (s.stated === null) findings.push({ severity: "warning", title: `${s.id === ALL ? "The export" : `Payout ${s.id}`} has no payout row and no expected deposit`, detail: `The rows add up to ${money(sum, cur)}. Enter the deposit from your bank, PayPal or Patreon payout in the box above to check it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Payout ${s.id}: rows add up to ${money(sum, cur)} but the payout is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const p of r.parts) add(p.k, p.amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in payout ${s.id} had no created date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Payout ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Patreon clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Payout ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Patreon payout ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `Payout ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.id === UNPAID ? null : s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.id === UNPAID || s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Type", "Charge ID", "Tier", "Date", "Pledge Amount", "Shipping", "Taxes", "Platform Fee", "Processing Fee", "Net Total", "Currency", "Refunded", "Payout ID"];

// items: [date, item, price, fee, refunded, shipping]. A deposit row is added when `withPayoutRow`
// (real exports usually have none, so the deposit is then typed in from the bank).
export function buildReport({ id = "P-2026-10", currency = "USD", items, withPayoutRow = false, totalOverride }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const out = [HEAD.join(",")];
  let net = 0, n = 0;
  for (const [date, item, price, fee, refunded, shipping] of items) {
    n++;
    const bad = typeof price === "string";
    const ship = shipping || 0;
    const nn = bad ? NaN : refunded ? -fee : price + ship - fee;
    if (!Number.isNaN(nn)) net += Math.round(nn * 100);
    const plat = Math.round(fee * 70) / 100, proc = Math.round((fee - plat) * 100) / 100;
    out.push(["pledge", `C${1000 + n}`, item, `${date} 12:00:00`, bad ? price : price.toFixed(2), ship.toFixed(2), "0.00", plat.toFixed(2), proc.toFixed(2), bad ? price : nn.toFixed(2), currency, refunded ? "true" : "false", id].map(csv).join(","));
  }
  if (withPayoutRow) out.push(["payout", "", "", "", "", "", "", "", "", ((totalOverride ?? net / 100)).toFixed(2), currency, "", id].map(csv).join(","));
  return out.join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-28", "Supporter tier", 29.00, 3.70, false],
  ["2026-09-29", "Patron tier", 149.00, 15.40, false],
  ["2026-09-30", "Early-access tier", 19.00, 2.35, false],
  ["2026-10-01", "Patron tier", 149.00, 15.40, false],
  ["2026-10-02", "Supporter tier", 29.00, 3.70, true],
  ["2026-10-03", "Postcard reward", 35.00, 4.25, false, 6.50],
];

const deposit = (items) => items.reduce((a, r) => a + Math.round(((r[4] ? 0 : r[2] + (r[5] || 0)) - r[3]) * 100), 0) / 100;
export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS, withPayoutRow: true });
// The same export after a hand edit: a row dropped from the paste so the payout no longer agrees,
// one sale whose parts do not add to its net, and one amount that is not a number.
export function sampleBrokenReport() {
  const items = SAMPLE_ITEMS.filter((r) => r[1] !== "Postcard reward");
  items.push(["2026-10-04", "Mystery item", 10.00, 1.00, false]);
  items.push(["2026-10-04", "Extra tier", "12..5", 1.00, false]);
  return buildReport({ items, totalOverride: deposit(SAMPLE_ITEMS), withPayoutRow: true }).replace("10.00,0.00,0.00,0.70,0.30,9.00,", "10.00,0.00,0.00,0.70,0.30,7.00,");
}

engines/paypal.mjs.text:
// PayPal Activity report -> accounting journal.
//
// A PayPal account is itself a bank-like balance: sales arrive gross, fees come off, refunds and
// disputes move money back, and withdrawals to a bank move it out. Bookkeepers need each of those
// on its own line, split at month end, with a PayPal account line that moves by exactly what the
// account's Balance column says it moved. This module reads the Activity Download CSV, proves
// the running Balance column is continuous (opening balance + every net = closing balance, row
// by row), groups rows into categories, and writes balanced journals for Xero, QuickBooks Online,
// QuickBooks Desktop (IIF) and a plain CSV.
//
// The report column names, the transaction type names and each importer's column layout are from
// memory of public PayPal and accounting-software help documents; no real PayPal export and no
// live Xero or QuickBooks import was available when this was written. Rows no rule recognises are
// never dropped: they land in an "uncategorised" line and are reported.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Payments received (gross)", account: "PayPal Sales" },
  refunds: { label: "Refunds paid", account: "PayPal Refunds" },
  disputes: { label: "Chargebacks, disputes and holds", account: "PayPal Disputes" },
  processing: { label: "PayPal fees", account: "PayPal Fees" },
  purchases: { label: "Payments sent", account: "PayPal Payments Sent" },
  transfers: { label: "Transfers to and from the bank", account: "Bank Transfer Clearing" },
  conversion: { label: "Currency conversion", account: "PayPal Currency Conversion" },
  uncategorised: { label: "Uncategorised PayPal items", account: "PayPal Uncategorised" },
  clearing: { label: "PayPal account (moves by the Balance column)", account: "PayPal Account" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO, DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const norm = (h) => h.trim().toLowerCase().replace(/^\ufeff/, "").replace(/[\s_]+/g, "-").replace(/-+$/, "");
const ALIASES = {
  date: ["date"],
  time: ["time"],
  type: ["type", "transaction-type"],
  status: ["status"],
  currency: ["currency"],
  gross: ["gross", "amount"],
  fee: ["fee", "fees"],
  net: ["net"],
  balance: ["balance"],
  impact: ["balance-impact"],
  id: ["transaction-id"],
  name: ["name"],
  desc: ["item-title", "description", "subject"],
};
const SKIP_STATUS = /^(pending|denied|canceled|cancelled|created|voided|expired|declined|failed|placed|unclaimed)$/i;

export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const empty = () => ({ settlements: [], findings, summary: { rows: 0, settlements: 0 } });
  const lines = String(text || "").replace(/^\ufeff/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  if (first < 0) { add("error", "The file is empty", "Paste or choose a PayPal Activity report."); return empty(); }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const I = {};
  for (const [k, names] of Object.entries(ALIASES)) I[k] = names.map((n) => head.indexOf(n)).find((i) => i >= 0) ?? -1;
  const missing = ["date", "type", "currency"].filter((k) => I[k] < 0);
  if (missing.length || (I.gross < 0 && I.net < 0)) {
    add("error", "This does not look like a PayPal Activity report", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}${I.gross < 0 && I.net < 0 ? " gross/net" : ""}. In PayPal open Activity > Statements > Activity download (or Reports > Activity), choose Completed payments or All transactions, and download the CSV with the Date, Type, Currency, Gross, Fee, Net and Balance columns.`, first + 1);
    return empty();
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  // The file is usually newest-first; read it oldest-first so the Balance chain can be walked.
  const data = [];
  for (let i = first + 1; i < lines.length; i++) if (lines[i].trim()) data.push({ i, cells: splitLine(lines[i], d) });
  const dateOf = (r) => parseDate(get(r.cells, "date"), opts.dateOrder) || "";
  const dated = data.filter((r) => dateOf(r));
  if (dated.length > 1 && dateOf(dated[0]) + get(dated[0].cells, "time") > dateOf(dated[dated.length - 1]) + get(dated[dated.length - 1].cells, "time")) data.reverse();
  const byCur = new Map();
  const bucket = (cur) => { if (!byCur.has(cur)) byCur.set(cur, { id: `PayPal ${cur}`, start: null, end: null, deposit: null, total: null, currency: cur, rows: [], summaryRows: 0, chain: [] }); return byCur.get(cur); };
  let rows = 0, skipped = 0, memo = 0;
  for (const { i, cells } of data) {
    const status = get(cells, "status"), impact = get(cells, "impact"), type = get(cells, "type");
    const cur = (get(cells, "currency") || "").toUpperCase();
    if (!cur) { add("warning", "Row has no currency", "It was skipped.", i + 1); continue; }
    if (/^memo$/i.test(impact)) { memo++; continue; }
    if (status && SKIP_STATUS.test(status)) { skipped++; continue; }
    const netRaw = get(cells, "net"), grossRaw = get(cells, "gross"), feeRaw = get(cells, "fee"), balRaw = get(cells, "balance");
    const net = parseAmount(netRaw), gross = parseAmount(grossRaw), fee = parseAmount(feeRaw), bal = parseAmount(balRaw);
    if ([net, gross, fee, bal].some((v) => Number.isNaN(v))) { add("error", `A number in this row is not valid (gross "${grossRaw}", fee "${feeRaw}", net "${netRaw}", balance "${balRaw}")`, "The row is left out, so the account will not reconcile.", i + 1); continue; }
    if (net === null && gross === null) { add("warning", "Row has no amount", `${type || "row"} was skipped.`, i + 1); continue; }
    const f = fee ?? 0, g = gross ?? net - f, n = net ?? g + f;
    if (g + f !== n) add("warning", "Gross plus fee is not net on this row", `${type}: ${money(g, cur)} + ${money(f, cur)} is ${money(g + f, cur)} but the report says ${money(n, cur)}. The net is used.`, i + 1);
    const s = bucket(cur);
    const posted = parseDate(get(cells, "date"), opts.dateOrder);
    const base = { line: i + 1, type, orderId: get(cells, "id"), id: get(cells, "id"), posted, desc: get(cells, "desc") || get(cells, "name") };
    const gAdj = n - f; // gross component, so gross + fee == net always holds
    if (gAdj !== 0) s.rows.push({ ...base, part: "gross", amount: gAdj });
    if (f !== 0) s.rows.push({ ...base, part: "fee", amount: f });
    s.chain.push({ line: i + 1, net: n, balance: bal });
    rows++;
  }
  for (const s of byCur.values()) {
    // Opening balance = first balance minus its own net. Every later row must land on the previous balance + its net.
    const withBal = s.chain.filter((c) => c.balance !== null);
    if (withBal.length === s.chain.length && s.chain.length) {
      let prev = s.chain[0].balance - s.chain[0].net, breaks = 0;
      for (const c of s.chain) {
        if (prev + c.net !== c.balance) { breaks++; if (breaks <= 3) add("error", `Balance column breaks at this row (${s.currency})`, `Previous balance ${money(prev, s.currency)} plus net ${money(c.net, s.currency)} is ${money(prev + c.net, s.currency)}, but the file says ${money(c.balance, s.currency)}. Rows are missing or out of order above this line.`, c.line); }
        prev = c.balance;
      }
      if (breaks > 3) add("error", `${breaks - 3} more Balance breaks in ${s.currency}`, "Only the first three are listed.");
      s.total = s.chain[s.chain.length - 1].balance - (s.chain[0].balance - s.chain[0].net);
    }
    s.openBalance = s.chain.length && s.chain[0].balance !== null ? s.chain[0].balance - s.chain[0].net : null;
    s.closeBalance = s.chain.length ? s.chain[s.chain.length - 1].balance : null;
  }
  if (memo) add("info", `${memo} memo row${memo === 1 ? "" : "s"} skipped`, "Rows whose Balance Impact is Memo (authorisations, orders) do not move the balance.");
  if (skipped) add("info", `${skipped} pending, denied or cancelled row${skipped === 1 ? "" : "s"} skipped`, "They did not move the balance. Download again once they complete.");
  const settlements = [...byCur.values()].filter((s) => s.rows.length);
  if (!settlements.length) add("error", "No transactions found", "The header was read but no completed row moved the balance.");
  return { settlements, findings, summary: { rows, settlements: settlements.length } };
}
export const parseSettlements = parsePayouts;

// ---- categorising ------------------------------------------------------------

export function categoryOf(row) {
  const type = row.type.toLowerCase();
  if (row.part === "fee") return "processing";
  if (/refund/.test(type)) return "refunds";
  if (/chargeback|dispute|reversal|hold on balance|release|reserve/.test(type)) return "disputes";
  if (/withdraw|bank deposit|add funds|transfer to bank|transfer from bank|bank transfer/.test(type)) return "transfers";
  if (/currency conversion/.test(type)) return "conversion";
  if (/payment|checkout|sale|invoice|subscription|donation|purchase|shopping cart|virtual terminal|qr|order/.test(type)) return row.amount < 0 ? "purchases" : "sales";
  return "uncategorised";
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a settlement touches.
export function buildJournals(settlements, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of settlements) {
    const sum = s.rows.reduce((a, r) => a + r.amount, 0);
    const endDate = s.end || [...s.rows].map((r) => r.posted).filter(Boolean).sort().pop() || null;
    const cur = s.currency || "USD";
    if (s.total === null) findings.push({ severity: "warning", title: `${s.id} has no Balance column`, detail: "The running balance could not be used to prove the rows are complete.", line: 0 });
    else if (s.total !== sum) findings.push({ severity: "error", title: `${s.id}: rows add up to ${money(sum, cur)} but the Balance column moved by ${money(s.total, cur)}`, detail: `Off by ${money(s.total - sum, cur)}. Rows are missing from the download, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0, outside = 0;
    for (const r of s.rows) {
      let ym = r.posted ? r.posted.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.posted) undated++;
      if (r.posted && s.start && s.end && (r.posted < s.start || r.posted > s.end)) outside++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const cat = categoryOf(r), m = periods.get(ym);
      const e = m.get(cat) || { net: 0, count: 0 };
      e.net += r.amount; e.count++; m.set(cat, e);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in ${s.id} had no posted date`, detail: "They were placed in the settlement's final month.", line: 0 });
    if (outside) findings.push({ severity: "info", title: `${outside} row${outside === 1 ? "" : "s"} in ${s.id} posted outside its start and end dates`, detail: "They are journalled in the month they posted.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to the PayPal account, so every month's revenue and fees land in the month they happened. Together they move the PayPal account by exactly what the Balance column moved.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ settlementId: s.id, period: ym, date, deposit: s.deposit, currency: cur, narration: `${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => categoryOf(r) === "uncategorised");
    if (unknown.length) findings.push({ severity: "warning", title: `${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.desc || r.type))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the Balance column's movement. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(settlements) {
  return settlements.flatMap((s) => s.rows.filter((r) => categoryOf(r) === "uncategorised").map((r) => ({ settlement: s.id, ...r })));
}

export function reconciliation(settlements, journals) {
  return settlements.map((s) => {
    const js = journals.filter((j) => j.settlementId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.deposit, currency: s.currency || "USD", stated: s.total, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.total === null ? null : s.total === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parseSettlements(text, opts);
  const b = buildJournals(p.settlements, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { settlements: p.settlements, journals: b.journals, findings, reconciliation: reconciliation(p.settlements, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([`${j.settlementId}${j.period && j.period !== "undated" && journalsOf(journals, j.settlementId) > 1 ? "-" + j.period : ""}`, fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}
const journalsOf = (journals, id) => journals.filter((j) => j.settlementId === id).length;

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(`${j.settlementId}${journalsOf(journals, j.settlementId) > 1 ? "-" + j.period : ""}`);
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["settlement", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.settlementId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Date", "Time", "TimeZone", "Name", "Type", "Status", "Currency", "Gross", "Fee", "Net", "Transaction ID", "Item Title", "Balance", "Balance Impact"];

// items: [type, date (YYYY-MM-DD), gross, fee, title, name, status?, impact?]; oldest first. The Balance
// column is computed from `opening`, and the file is written newest-first, as PayPal downloads it.
export function buildReport({ items, opening = 1000, currency = "USD", mdy = true }) {
  const c = (n) => Math.round(n * 100);
  let bal = c(opening);
  const q = (v) => { const t = String(v); return /[",]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t; };
  const fmt = (n) => (n / 100).toFixed(2);
  const rows = items.map(([type, date, gross, fee, title, name, status = "Completed", impact = "Credit"], i) => {
    const net = c(gross) + c(fee);
    if (impact !== "Memo") bal += net;
    const [y, m, d] = date.split("-");
    const shown = bal;
    return [mdy ? `${m}/${d}/${y}` : `${d}/${m}/${y}`, `10:${String(i).padStart(2, "0")}:00`, "PDT", name || "", type, status, currency, fmt(c(gross)), fmt(c(fee)), fmt(net), `TX${1000 + i}`, title || "", fmt(shown), impact === "Memo" ? "Memo" : net < 0 ? "Debit" : "Credit"].map(q).join(",");
  });
  return [HEAD.join(","), ...rows.reverse()].join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["Website Payment", "2026-09-28", 129.99, -4.07, "Order 1001", "Pat Example"],
  ["Express Checkout Payment", "2026-09-29", 49.0, -1.75, "Order 1002", "Sam Example"],
  ["Subscription Payment", "2026-09-30", 19.0, -0.85, "Monthly plan", "Alex Example"],
  ["General Withdrawal", "2026-09-30", -150.0, 0, "Transfer to bank", ""],
  ["Payment Refund", "2026-10-02", -49.0, 1.75, "Refund order 1002", "Sam Example"],
  ["Website Payment", "2026-10-02", 79.0, -2.59, "Order 1003", "Jo Example"],
  ["Chargeback", "2026-10-03", -79.0, 0, "Chargeback order 1003", "Jo Example"],
  ["Payment Sent", "2026-10-04", -25.0, 0, "Domain renewal", "Registrar Inc"],
  ["Authorization", "2026-10-05", 60.0, 0, "Pre-auth", "Kim Example", "Pending", "Memo"],
  ["Mobile Payment", "2026-10-06", 5.0, -0.46, "Tip", "Lee Example"],
];

export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS });
// The same download after a hand edit: rows missing so the Balance column breaks, plus an amount that is not a number.
export function sampleBrokenReport() {
  const items = SAMPLE_ITEMS.filter((r) => r[0] !== "Subscription Payment");
  return buildReport({ items }) + buildReportBad();
}
function buildReportBad() { return `10/06/2026,11:00:00,PDT,Bad Row,Website Payment,Completed,USD,12..5,0.00,12..5,TXBAD,Bad amount,0.00,Credit\n`; }

engines/shopify.mjs.text:
// Shopify Payments payout transactions export -> accounting journal.
//
// Shopify pays out a net deposit that hides gross sales, processing fees, refunds,
// chargebacks and shipping-label purchases. Bookkeepers need those split out, and a
// payout that straddles a month end split in two. This module reads the payout
// transactions CSV (Payments > Payouts > Export, or the all-transactions export: same
// columns), proves each payout's rows add up to the payout, groups them into
// categories and writes balanced journals for Xero, QuickBooks Online, QuickBooks
// Desktop (IIF) and a plain CSV.
//
// The report layout, the Type values and each importer's column layout are from memory
// of public Shopify and accounting help documents; no real Shopify export and no live
// Xero or QuickBooks import was available when this was written.
// Rows no rule recognises are never dropped: they land in an "uncategorised" line and
// are reported, so the journal still equals the net.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Order payments (gross)", account: "Shopify Sales" },
  refunds: { label: "Refunds", account: "Shopify Refunds" },
  disputes: { label: "Chargebacks and dispute fees", account: "Shopify Chargebacks" },
  shipping: { label: "Shipping labels bought in Shopify", account: "Shopify Shipping Labels" },
  fees: { label: "Shopify Payments fees (processing, FX, app and referral)", account: "Shopify Fees" },
  other: { label: "Adjustments and transfers", account: "Shopify Adjustments" },
  uncategorised: { label: "Uncategorised Shopify items", account: "Shopify Uncategorised" },
  clearing: { label: "Shopify clearing (matches the bank deposit)", account: "Shopify Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const REQUIRED = ["net", "reporting-category"];
const UNPAID = "(not yet paid out)";

// Rows are grouped by automatic payout id. `payout` rows (an export may carry one per payout) state the deposit; the payout transactions export usually does not,
// so the caller may supply the deposit from the bank / dashboard via opts.expected.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Shopify payout transactions CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    payout: col("payout-id", "automatic-payout-id", "payout"),
    effective: col("payout-date", "automatic-payout-effective-at", "arrival-date"),
    id: col("balance-transaction-id", "id", "order"),
    created: col("transaction-date", "created", "created-utc", "created-date"),
    currency: col("currency"),
    gross: col("gross", "amount"),
    fee: col("fee"),
    net: col("net"),
    cat: col("type", "reporting-category"),
    type: col("reporting-category"),
    source: col("source-id", "source"),
    desc: col("description"),
  };
  const missing = [];
  if (I.net < 0) missing.push("net");
  if (I.cat < 0 && I.type < 0) missing.push("Type");
  if (missing.length) {
    add("error", "This does not look like a Shopify payout transactions export", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Shopify admin open Settings > Payments > Shopify Payments > Payouts, open a payout and choose Export (or use Finances > Payouts > Export transactions).`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, effective: null, stated: null, currency: "", rows: [] }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const cat = (get(cells, "cat") || get(cells, "type")).toLowerCase();
    const netS = get(cells, "net");
    const net = parseAmount(netS);
    if (net === null) { add("warning", "Row has no net amount", `${cat || "row"} was skipped.`, i + 1); continue; }
    if (Number.isNaN(net)) { add("error", `Net amount "${netS}" is not a number`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const grossS = get(cells, "gross"), feeS = get(cells, "fee");
    let gross = grossS === "" ? net : parseAmount(grossS), fee = feeS === "" ? 0 : parseAmount(feeS);
    if (Number.isNaN(gross) || Number.isNaN(fee)) { add("error", "Gross or fee is not a number", `Row ${get(cells, "id") || i + 1} was left out.`, i + 1); continue; }
    if (gross - fee !== net) add("error", `Gross minus fee does not equal net on ${get(cells, "id") || `line ${i + 1}`}`, `${money(gross)} - ${money(fee)} = ${money(gross - fee)}, but the row says ${money(net)}. The journal uses the net; check the file was not edited.`, i + 1);
    const pid = get(cells, "payout") || UNPAID;
    const s = bucket(pid);
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in payout ${pid}`, `${cur} row among ${s.currency} rows. Journals assume one currency per payout.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    const eff = parseDate(get(cells, "effective"), opts.dateOrder);
    if (eff && !s.effective) s.effective = eff;
    const row = { line: i + 1, id: get(cells, "id"), cat, desc: get(cells, "desc"), source: get(cells, "source"), gross, fee, net, created: parseDate(get(cells, "created"), opts.dateOrder) };
    if (cat === "payout") { s.stated = (s.stated || 0) + -net; continue; } // the deposit itself, not an activity row
    s.rows.push(row);
    rows++;
  }
  const payouts = [...byId.values()].filter((s) => s.rows.length || s.stated !== null);
  if (!payouts.length) add("error", "No payout rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    const real = payouts.filter((s) => s.id !== UNPAID);
    if (real.length === 1 && real[0].stated === null) real[0].stated = opts.expected;
    else if (real.length !== 1) add("info", "Expected deposit ignored", "It can only be applied when the file holds exactly one payout without a payout row of its own.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- categorising ------------------------------------------------------------

const FEE_CATS = /^(fee|.*_fee|.*_fees|.*_cost|.*_costs|app_fee|referral_fee|tax|vat|billing|currency_conversion|fx)$/;
export function categoryOf(row) {
  const c = String(row.cat || "").toLowerCase().trim().replace(/[\s-]+/g, "_");
  if (c === "charge" || c === "payment" || c === "capture" || c === "sale") return "sales";
  if (c === "refund" || c === "refund_failure" || c === "refund_reversal") return "refunds";
  if (c === "dispute" || c === "chargeback" || c === "chargeback_won" || c === "chargeback_hold" || c === "chargeback_hold_release" || c === "dispute_reversal" || c === "dispute_withdrawal" || c === "dispute_fee") return "disputes";
  if (c === "shipping_label" || c === "shipping_label_refund" || c === "shipping_label_adjustment" || c === "shipping_return_to_sender") return "shipping";
  if (FEE_CATS.test(c)) return "fees";
  if (c === "adjustment" || c === "credit" || c === "debit" || c === "transfer" || c === "payout_reversal" || c === "payout_failure" || c === "reserve" || c === "reserved_funds" || c === "reserved_funds_release" || c === "advance" || c === "capital") return "other";
  return "uncategorised";
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.id === UNPAID) findings.push({ severity: "warning", title: `${s.rows.length} row${s.rows.length === 1 ? "" : "s"} have no payout ID`, detail: "They are not yet paid out (or the report omits the payout column). They are journalled to Shopify clearing as a separate group and will not match a bank deposit yet.", line: 0 });
    else if (s.stated === null) findings.push({ severity: "warning", title: `Payout ${s.id} has no payout row and no expected deposit`, detail: `The rows add up to ${money(sum, cur)}. Enter the deposit from your bank or Shopify in the box above to check it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Payout ${s.id}: rows add up to ${money(sum, cur)} but the payout is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      add(categoryOf(r), r.gross);
      add("fees", -r.fee);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in payout ${s.id} had no created date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Payout ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Shopify clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Payout ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Shopify payout ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => categoryOf(r) === "uncategorised");
    if (unknown.length) findings.push({ severity: "warning", title: `Payout ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.cat || r.desc))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => categoryOf(r) === "uncategorised").map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.id === UNPAID ? null : s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.id === UNPAID || s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Transaction Date", "Type", "Order", "Card Brand", "Card Source", "Payout Status", "Payout Date", "Payout ID", "Available On", "Amount", "Fee", "Net", "Checkout", "Payment Method Name", "Presentment Amount", "Presentment Currency", "Currency", "Vat"];

// items: [date, type, amount, fee, order]. A payout row is added when `withPayoutRow`
// (real exports usually have none, so the deposit is then typed in from the bank).
export function buildReport({ id = "1234567890", effective = "2026-10-08", currency = "USD", items, withPayoutRow = false, totalOverride }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  const out = [HEAD.join(",")];
  let net = 0, n = 0;
  const row = (date, type, order, amt, fee, netS) => out.push([`${date} 12:00:00 -0400`, type, order, type === "charge" ? "visa" : "", type === "charge" ? "online" : "", "paid", effective, id, effective, amt, fee, netS, "", type === "charge" ? "shopify_payments" : "", amt, currency, currency, ""].map(csv).join(","));
  for (const [date, type, amount, fee, order] of items) {
    n++;
    const bad = typeof amount === "string";
    const nn = bad ? NaN : amount - fee;
    if (!Number.isNaN(nn)) net += Math.round(nn * 100);
    row(date, type, order || `#${1000 + n}`, bad ? amount : amount.toFixed(2), fee.toFixed(2), bad ? amount : nn.toFixed(2));
  }
  if (withPayoutRow) {
    const total = totalOverride ?? net / 100;
    row(effective, "payout", "", (-total).toFixed(2), "0.00", (-total).toFixed(2));
  }
  return out.join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-28", "charge", 129.99, 3.97, "#1041"],
  ["2026-09-29", "charge", 49.00, 1.72, "#1042"],
  ["2026-09-30", "charge", 19.00, 0.85, "#1043"],
  ["2026-10-01", "charge", 449.99, 13.35, "#1044"],
  ["2026-10-02", "charge", 19.00, 0.85, "#1045"],
  ["2026-10-03", "refund", -49.00, 0.00, "#1042"],
  ["2026-10-04", "chargeback", -19.00, 15.00, "#1043"],
  ["2026-10-05", "shipping_label", -14.20, 0.00, "#1044"],
  ["2026-10-06", "app_fee", -4.50, 0.00, ""],
  ["2026-10-07", "adjustment", 2.00, 0.00, ""],
];

export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS, withPayoutRow: true });
// The same export after a hand edit: a row dropped from the paste so the payout no longer
// agrees, one Type no rule recognises and one amount that is not a number.
export function sampleBrokenReport() {
  const total = SAMPLE_ITEMS.reduce((a, r) => a + Math.round((r[2] - r[3]) * 100), 0) / 100;
  const items = SAMPLE_ITEMS.filter((r) => r[1] !== "shipping_label");
  items.push(["2026-10-06", "mystery_item", 1.23, 0, "#1099"], ["2026-10-06", "charge", "12..5", 0, "#1098"]);
  return buildReport({ items, totalOverride: total, withPayoutRow: true });
}

engines/square.mjs.text:
// Square Transactions CSV -> accounting journal.
//
// Square's Transactions export (Dashboard > Reports > Transactions > Export) has one row per
// payment with Gross Sales, Discounts, Net Sales, Tax, Tip, Partial Refunds, Total Collected, Fees
// and Net Total. Bookkeepers need sales, discounts, sales tax, tips, refunds and Square's fees
// booked separately, one journal per calendar month, balanced to a Square clearing account, and
// each Deposit ID totalled so it can be matched to the bank feed. This module reads the export,
// checks every row (Total Collected + Fees = Net Total), accounts for every dollar of Total
// Collected, and writes balanced journals for Xero, QuickBooks Online, QuickBooks Desktop (IIF)
// and plain CSV.
//
// Column names and importer layouts are from memory of public Square and accounting help
// documents; no real Square export and no live import was available when this was written.
// Money that no rule explains goes to an uncategorised line and is reported, never dropped.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Gross sales", account: "Square Sales" },
  discounts: { label: "Discounts", account: "Square Discounts" },
  service: { label: "Service charges", account: "Square Service Charges" },
  giftcards: { label: "Gift card sales (liability)", account: "Gift Cards Outstanding" },
  tax: { label: "Sales tax collected (liability)", account: "Sales Tax Payable" },
  tips: { label: "Tips collected (liability)", account: "Tips Payable" },
  refunds: { label: "Refunds", account: "Square Refunds" },
  fees: { label: "Square processing fees", account: "Square Fees" },
  uncategorised: { label: "Collected money no rule explains", account: "Square Uncategorised" },
  clearing: { label: "Square clearing (pending deposit)", account: "Square Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}


const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
// Etsy prints amounts as "$25.00", "-$1.63", "--" or "€12,50"; strip the symbol and read the rest.
export function parseMoney(s) {
  const t = String(s ?? "").trim();
  if (t === "" || /^-+$/.test(t)) return null;
  const neg = /^\(.*\)$/.test(t) || /^[-−]/.test(t) || /[-−]$/.test(t);
  const core = t.replace(/[^0-9.,]/g, "");
  if (!core) return NaN;
  const v = parseAmount(core);
  return v === null || Number.isNaN(v) ? NaN : neg ? -Math.abs(v) : v;
}
// Etsy writes "September 28, 2026" or "28 September 2026" or numeric dates; return YYYY-MM-DD or null.
export function parseStatementDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  let x;
  if ((x = t.match(/^([A-Za-z]{3})[a-z]*\.? (\d{1,2}),? (\d{4})/))) { const m = MONTHS[x[1].toLowerCase()]; return m ? parseDate(`${x[3]}-${String(m).padStart(2, "0")}-${String(x[2]).padStart(2, "0")}`) : null; }
  if ((x = t.match(/^(\d{1,2}) ([A-Za-z]{3})[a-z]*\.?,? (\d{4})/))) { const m = MONTHS[x[2].toLowerCase()]; return m ? parseDate(`${x[3]}-${String(m).padStart(2, "0")}-${String(x[1]).padStart(2, "0")}`) : null; }
  return parseDate(t, order);
}


const COLUMNS = {
  date: ["date"], gross: ["gross-sales"], discounts: ["discounts"], service: ["service-charges"], net: ["net-sales"],
  giftcards: ["gift-card-sales"], tax: ["tax"], tip: ["tip"], refunds: ["partial-refunds", "refunds"],
  collected: ["total-collected"], fees: ["fees"], netTotal: ["net-total"], txn: ["transaction-id"], payment: ["payment-id"],
  deposit: ["deposit-id"], status: ["transaction-status"], desc: ["description", "details"], tz: ["time-zone"],
};

// Rows are grouped by calendar month. The period's Net Total can be checked against a figure
// the caller types in via opts.expected (only when the file holds exactly one month).
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], deposits: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Square Transactions export."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const I = {};
  for (const [k, names] of Object.entries(COLUMNS)) { I[k] = -1; for (const n of names) { const i = head.indexOf(n); if (i >= 0) { I[k] = i; break; } } }
  const missing = [];
  if (I.date < 0) missing.push("Date");
  if (I.collected < 0) missing.push("Total Collected");
  if (I.fees < 0 && I.netTotal < 0) missing.push("Fees or Net Total");
  if (missing.length) {
    add("error", "This does not look like a Square Transactions export", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In the Square Dashboard open Reports > Sales > Transactions (or Payments), choose the dates and export the CSV. The Items export has no fees and cannot be used.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map(), deps = new Map();
  let rows = 0, skipped = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const date = parseDate(get(cells, "date"), opts.dateOrder);
    const label = get(cells, "payment") || get(cells, "txn") || get(cells, "desc") || `line ${i + 1}`;
    if (!date) { add("error", `Date "${get(cells, "date")}" not understood`, "The row is left out, so its month will not add up.", i + 1); continue; }
    const f = {};
    let bad = false;
    for (const k of ["gross", "discounts", "service", "net", "giftcards", "tax", "tip", "refunds", "collected", "fees", "netTotal"]) {
      const v = parseMoney(get(cells, k));
      if (Number.isNaN(v)) { add("error", "An amount is not a number", `"${get(cells, k)}" in ${k} on ${label} was left out with its row.`, i + 1); bad = true; break; }
      f[k] = v;
    }
    if (bad) continue;
    const status = get(cells, "status").toLowerCase();
    if (status && !/^(complete|completed|paid|success|succeeded|)$/.test(status) && !/refund/.test(status)) { skipped++; add("warning", `Row with status "${get(cells, "status")}" skipped`, `${label} is not a completed payment, so no money moved; it is not journalled.`, i + 1); continue; }
    if (f.collected === null && f.netTotal === null) { add("warning", "Row has no total", `${label} was skipped.`, i + 1); continue; }
    const fees = f.fees ?? 0;
    const collected = f.collected ?? (f.netTotal - fees);
    const netTotal = f.netTotal ?? (collected + fees);
    if (collected + fees !== netTotal) add("error", `Total Collected plus Fees does not equal Net Total on ${label}`, `${money(collected)} + ${money(fees)} = ${money(collected + fees)}, but the row says ${money(netTotal)}. The journal uses the Net Total; check the file was not edited.`, i + 1);
    const g = f.gross ?? 0, disc = f.discounts ?? 0, svc = f.service ?? 0, gc = f.giftcards ?? 0, tax = f.tax ?? 0, tip = f.tip ?? 0, ref = f.refunds ?? 0;
    // Discounts and refunds print as negatives on most exports; either sign is read as a reduction.
    const parts = { sales: g, discounts: -Math.abs(disc), service: svc, giftcards: gc, tax, tips: tip, refunds: -Math.abs(ref) };
    const explained = Object.values(parts).reduce((a, v) => a + v, 0);
    parts.uncategorised = collected - explained;
    parts.fees = fees;
    const ym = date.slice(0, 7);
    if (!byId.has(ym)) byId.set(ym, { id: ym, effective: null, stated: null, currency: "USD", rows: [] });
    const s = byId.get(ym);
    if (!s.effective || date > s.effective) s.effective = date;
    const dep = get(cells, "deposit");
    s.rows.push({ line: i + 1, label, created: date, parts, net: netTotal, deposit: dep });
    if (dep) { const e = deps.get(dep) || { id: dep, net: 0, rows: 0, first: date, last: date }; e.net += netTotal; e.rows++; if (date < e.first) e.first = date; if (date > e.last) e.last = date; deps.set(dep, e); }
    rows++;
  }
  const payouts = [...byId.values()].sort((a, b) => a.id.localeCompare(b.id));
  if (!payouts.length) add("error", "No transactions found", "The header was read but there were no usable data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    if (payouts.length === 1) payouts[0].stated = opts.expected;
    else add("info", "Expected total ignored", "It can only be applied when the file holds exactly one month.");
  }
  const noDeposit = payouts.reduce((a, s) => a + s.rows.filter((r) => !r.deposit).length, 0);
  if (rows && noDeposit) add("info", `${noDeposit} row${noDeposit === 1 ? " has" : "s have"} no Deposit ID`, "Square assigns a Deposit ID when a payment is paid out. Rows without one are recent or cash and are not yet in any bank deposit.", 0);
  return { payouts, deposits: [...deps.values()].sort((a, b) => a.first.localeCompare(b.first)), findings, summary: { rows, payouts: payouts.length, skipped } };
}

// ---- categorising ------------------------------------------------------------

export function categoryOf(row) { return Object.entries(row.parts).filter(([, v]) => v).map(([k]) => k); }

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    if (s.stated === null) findings.push({ severity: "info", title: `Month ${s.id}: no expected total to check against`, detail: `Net Total for the month adds up to ${money(sum)}. Type the month's Net Total from your Square report summary into the optional box to prove it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Month ${s.id}: Net Total adds up to ${money(sum)} but the total you gave is ${money(s.stated)}`, detail: `Off by ${money(s.stated - sum)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const m = new Map();
    for (const r of s.rows) for (const [k, v] of Object.entries(r.parts)) {
      if (!v) continue;
      const e = m.get(k) || { net: 0, count: 0 };
      e.net += v; e.count++; m.set(k, e);
    }
    const lines = [];
    for (const k of CATEGORY_ORDER) {
      if (k === "clearing" || !m.has(k)) continue;
      const { net, count } = m.get(k);
      if (net === 0) continue;
      lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
    }
    const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
    if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Square transactions ${s.id}` });
    journals.push({ payoutId: s.id, period: s.id, date: lastDay(s.id), deposit: s.effective, currency: "USD", narration: `Square transactions ${s.id}`, lines, clearing: net });
    const unk = s.rows.filter((r) => r.parts.uncategorised);
    if (unk.length) findings.push({ severity: "warning", title: `Month ${s.id} has ${unk.length} row${unk.length === 1 ? "" : "s"} where Total Collected is not explained by the other columns`, detail: `${money(unk.reduce((a, r) => a + r.parts.uncategorised, 0))} in total (for example gift card redemptions, other tenders or a refund booked in an unusual column). It is journalled to "${mapping.uncategorised}" so the journal still equals the Net Total. Review those rows and reclassify by hand.`, line: unk[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.uncategorised).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    return { id: s.id, deposit: s.effective, currency: "USD", stated: s.stated, journalled: sum, periods: journals.filter((j) => j.payoutId === s.id).map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, deposits: p.deposits, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Date", "Time", "Time Zone", "Gross Sales", "Discounts", "Service Charges", "Net Sales", "Gift Card Sales", "Tax", "Tip", "Partial Refunds", "Total Collected", "Source", "Card", "Card Brand", "PAN Suffix", "Fees", "Net Total", "Transaction ID", "Payment ID", "Deposit ID", "Description"];
const usd = (c) => (c < 0 ? "-" : "") + "$" + Math.abs(c / 100).toFixed(2);

// items: { date, gross, disc, tax, tip, refund, fee, deposit, id } in dollars; totals are computed.
export function buildReport(items) {
  const c = (v) => Math.round((v || 0) * 100);
  const out = [HEAD.join(",")];
  for (const it of items) {
    const net = c(it.gross) - c(it.disc) + (it.gift ? 0 : 0);
    const collected = net + c(it.tax) + c(it.tip) + (it.gift ? c(it.gift) : 0) - c(it.refund);
    const fee = -c(it.fee);
    const row = [it.date, "12:00:00", "Eastern Time (US & Canada)", usd(c(it.gross)), usd(-c(it.disc)), "$0.00", usd(net), usd(c(it.gift)), usd(c(it.tax)), usd(c(it.tip)), usd(-c(it.refund)), usd(collected), "Square Point of Sale", "Card", "Visa", "1111", usd(fee), usd(collected + fee), `T${it.id}`, `P${it.id}`, it.deposit || "", it.desc || ""];
    out.push(row.join(","));
  }
  return out.join("\n") + "\n";
}

export const SAMPLE_ITEMS = [
  { id: 1, date: "2026-09-02", gross: 40, disc: 0, tax: 3.3, tip: 6, fee: 1.46, deposit: "D100" },
  { id: 2, date: "2026-09-02", gross: 25, disc: 5, tax: 1.65, tip: 0, fee: 0.9, deposit: "D100" },
  { id: 3, date: "2026-09-15", gross: 120, disc: 0, tax: 9.9, tip: 12, fee: 4.48, deposit: "D101" },
  { id: 4, date: "2026-09-29", gross: 60, disc: 0, tax: 4.95, tip: 0, fee: 2.0, refund: 20, deposit: "D102" },
  { id: 5, date: "2026-09-30", gross: 15, disc: 0, tax: 1.24, tip: 2, gift: 25, fee: 0.78, deposit: "D102" },
  { id: 6, date: "2026-10-03", gross: 80, disc: 8, tax: 5.94, tip: 10, fee: 3.1, deposit: "D103" },
  { id: 7, date: "2026-10-04", gross: 32, disc: 0, tax: 2.64, tip: 0, fee: 1.1, deposit: "" },
];
export const SAMPLE_NET_SEPT = (() => {
  let t = 0;
  for (const it of SAMPLE_ITEMS.filter((x) => x.date.startsWith("2026-09"))) t += Math.round((it.gross - it.disc + it.tax + it.tip + (it.gift || 0) - (it.refund || 0)) * 100) - Math.round(it.fee * 100);
  return t / 100;
})();

export const sampleReport = () => buildReport(SAMPLE_ITEMS);
// The same export after a hand edit: a fee that breaks the net, a garbled amount and a payment that never completed.
export function sampleBrokenReport() {
  const lines = buildReport(SAMPLE_ITEMS).trimEnd().split("\n");
  const cells = lines[1].split(",");
  cells[17] = "$40.00";
  lines[1] = cells.join(",");
  const bad = lines[2].split(",");
  bad[8] = "$1..65";
  lines[2] = bad.join(",");
  return lines.join("\n") + "\n";
}

engines/stripe.mjs.text:
// Stripe payout reconciliation report -> accounting journal.
//
// Stripe pays out a net deposit that hides gross sales, processing fees, refunds and
// disputes. Bookkeepers need those split out, and a payout that straddles a month end
// split in two. This module reads the itemised payout reconciliation report (or the
// balance-transactions export: same columns under Title Case names), proves each
// payout's rows add up to the payout, groups them into categories and writes balanced
// journals for Xero, QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV.
//
// The report layout, the reporting_category values and each importer's column layout
// are from memory of public Stripe and accounting help documents; no real Stripe
// export and no live Xero or QuickBooks import was available when this was written.
// Rows no rule recognises are never dropped: they land in an "uncategorised" line and
// are reported, so the journal still equals the net.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  sales: { label: "Card and wallet sales (gross)", account: "Stripe Sales" },
  refunds: { label: "Refunds", account: "Stripe Refunds" },
  disputes: { label: "Disputes and reversals", account: "Stripe Disputes" },
  fees: { label: "Stripe fees (processing, billing, tax, FX, network)", account: "Stripe Fees" },
  other: { label: "Adjustments and transfers", account: "Stripe Adjustments" },
  uncategorised: { label: "Uncategorised Stripe items", account: "Stripe Uncategorised" },
  clearing: { label: "Stripe clearing (matches the bank deposit)", account: "Stripe Clearing" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

export function parseAmount(s) {
  const t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

const REQUIRED = ["net", "reporting-category"];
const UNPAID = "(not yet paid out)";

// Rows are grouped by automatic payout id. `payout` rows (the balance-transactions export
// carries one per payout) state the deposit; the itemised reconciliation report does not,
// so the caller may supply the deposit from the bank / dashboard via opts.expected.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose a Stripe report."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    payout: col("automatic-payout-id", "payout-id", "payout"),
    effective: col("automatic-payout-effective-at", "automatic-payout-effective-at-utc", "payout-date", "arrival-date"),
    id: col("balance-transaction-id", "id"),
    created: col("created", "created-utc", "created-date"),
    currency: col("currency"),
    gross: col("gross", "amount"),
    fee: col("fee"),
    net: col("net"),
    cat: col("reporting-category"),
    type: col("type"),
    source: col("source-id", "source"),
    desc: col("description"),
  };
  const missing = [];
  if (I.net < 0) missing.push("net");
  if (I.cat < 0 && I.type < 0) missing.push("reporting_category");
  if (missing.length) {
    add("error", "This does not look like a Stripe payout report", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In the Stripe Dashboard open Reports > Payout reconciliation (or Balance > All activity) and download the itemised CSV.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const byId = new Map();
  const bucket = (id) => { if (!byId.has(id)) byId.set(id, { id, effective: null, stated: null, currency: "", rows: [] }); return byId.get(id); };
  let rows = 0;
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const cat = (get(cells, "cat") || get(cells, "type")).toLowerCase();
    const netS = get(cells, "net");
    const net = parseAmount(netS);
    if (net === null) { add("warning", "Row has no net amount", `${cat || "row"} was skipped.`, i + 1); continue; }
    if (Number.isNaN(net)) { add("error", `Net amount "${netS}" is not a number`, "The row is left out, so its payout will not add up.", i + 1); continue; }
    const grossS = get(cells, "gross"), feeS = get(cells, "fee");
    let gross = grossS === "" ? net : parseAmount(grossS), fee = feeS === "" ? 0 : parseAmount(feeS);
    if (Number.isNaN(gross) || Number.isNaN(fee)) { add("error", "Gross or fee is not a number", `Row ${get(cells, "id") || i + 1} was left out.`, i + 1); continue; }
    if (gross - fee !== net) add("error", `Gross minus fee does not equal net on ${get(cells, "id") || `line ${i + 1}`}`, `${money(gross)} - ${money(fee)} = ${money(gross - fee)}, but the row says ${money(net)}. The journal uses the net; check the file was not edited.`, i + 1);
    const pid = get(cells, "payout") || UNPAID;
    const s = bucket(pid);
    const cur = get(cells, "currency").toUpperCase();
    if (cur && s.currency && cur !== s.currency) add("warning", `Mixed currencies in payout ${pid}`, `${cur} row among ${s.currency} rows. Journals assume one currency per payout.`, i + 1);
    if (cur && !s.currency) s.currency = cur;
    const eff = parseDate(get(cells, "effective"), opts.dateOrder);
    if (eff && !s.effective) s.effective = eff;
    const row = { line: i + 1, id: get(cells, "id"), cat, desc: get(cells, "desc"), source: get(cells, "source"), gross, fee, net, created: parseDate(get(cells, "created"), opts.dateOrder) };
    if (cat === "payout") { s.stated = (s.stated || 0) + -net; continue; } // the deposit itself, not an activity row
    s.rows.push(row);
    rows++;
  }
  const payouts = [...byId.values()].filter((s) => s.rows.length || s.stated !== null);
  if (!payouts.length) add("error", "No payout rows found", "The header was read but there were no data rows.");
  if (opts.expected != null && Number.isFinite(opts.expected)) {
    const real = payouts.filter((s) => s.id !== UNPAID);
    if (real.length === 1 && real[0].stated === null) real[0].stated = opts.expected;
    else if (real.length !== 1) add("info", "Expected deposit ignored", "It can only be applied when the file holds exactly one payout without a payout row of its own.");
  }
  return { payouts, findings, summary: { rows, payouts: payouts.length } };
}

// ---- categorising ------------------------------------------------------------

const FEE_CATS = /^(fee|stripe_fee|stripe_fx_fee|network_cost|tax|stripe_tax|billing|radar|climate|connect|issuing|terminal|treasury|payment_network|.*_fee|.*_fees|.*_cost)$/;
export function categoryOf(row) {
  const c = String(row.cat || "").toLowerCase().replace(/-/g, "_");
  if (c === "charge" || c === "payment" || c === "payment_intent" || c === "capture") return "sales";
  if (c === "refund" || c === "payment_refund" || c === "refund_failure") return "refunds";
  if (c === "dispute" || c === "dispute_reversal" || c === "chargeback" || c === "payment_failure_refund") return "disputes";
  if (FEE_CATS.test(c)) return "fees";
  if (c === "adjustment" || c === "transfer" || c === "payout_reversal" || c === "advance" || c === "advance_funding" || c === "other_adjustment" || c === "reserve_hold" || c === "reserve_release") return "other";
  return "uncategorised";
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.id === UNPAID) findings.push({ severity: "warning", title: `${s.rows.length} row${s.rows.length === 1 ? "" : "s"} have no payout ID`, detail: "They are not yet paid out (or the report omits the payout column). They are journalled to Stripe clearing as a separate group and will not match a bank deposit yet.", line: 0 });
    else if (s.stated === null) findings.push({ severity: "warning", title: `Payout ${s.id} has no payout row and no expected deposit`, detail: `The rows add up to ${money(sum, cur)}. Enter the deposit from your bank or Stripe in the box above to check it.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Payout ${s.id}: rows add up to ${money(sum, cur)} but the payout is ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped. Do not post this journal until the figures agree.`, line: 0 });
    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      add(categoryOf(r), r.gross);
      add("fees", -r.fee);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} in payout ${s.id} had no created date`, detail: "They were placed in the payout's final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `Payout ${s.id} spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to Stripe clearing, so every month's revenue and fees land in the month they happened. The bank deposit of ${s.stated === null ? "the full amount" : money(s.stated, cur)} then clears both.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Payout ${s.id}${keys.length > 1 ? ` (${ym})` : ""}` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Stripe payout ${s.id}${keys.length > 1 ? ` ${ym}` : ""}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => categoryOf(r) === "uncategorised");
    if (unknown.length) findings.push({ severity: "warning", title: `Payout ${s.id} has ${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.cat || r.desc))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => categoryOf(r) === "uncategorised").map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.id === UNPAID ? null : s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.id === UNPAID || s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["automatic_payout_id", "automatic_payout_effective_at", "balance_transaction_id", "created", "available_on", "currency", "gross", "fee", "net", "reporting_category", "source_id", "description"];

// items: [created, category, gross, fee, description]. A payout row is added when `withPayoutRow`.
export function buildReport({ id = "po_1TESTPAYOUT01", effective = "2026-10-08 00:00:00", currency = "usd", items, withPayoutRow = true, totalOverride }) {
  let n = 0;
  const row = (o) => HEAD.map((h) => o[h] ?? "").join(",").replace(/\n/g, " ");
  const csv = (v) => (/[",]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);
  const out = [HEAD.join(",")];
  let net = 0;
  for (const [created, cat, gross, fee, desc] of items) {
    n++;
    const g = typeof gross === "string" ? gross : gross.toFixed(2), f = typeof fee === "string" ? fee : fee.toFixed(2);
    const nn = typeof gross === "string" ? NaN : gross - fee;
    if (!Number.isNaN(nn)) net += Math.round(nn * 100);
    out.push(row({ automatic_payout_id: id, automatic_payout_effective_at: effective, balance_transaction_id: `txn_1T${String(n).padStart(6, "0")}`, created: `${created} 12:00:00`, available_on: `${effective}`, currency, gross: g, fee: f, net: Number.isNaN(nn) ? g : nn.toFixed(2), reporting_category: cat, source_id: `${cat === "charge" ? "ch" : "src"}_3T${String(n).padStart(6, "0")}`, description: csv(desc || "") }));
  }
  if (withPayoutRow) {
    const total = totalOverride ?? net / 100;
    out.push(row({ automatic_payout_id: id, automatic_payout_effective_at: effective, balance_transaction_id: "txn_1TPAYOUT", created: `${effective}`, available_on: `${effective}`, currency, gross: (-total).toFixed(2), fee: "0.00", net: (-total).toFixed(2), reporting_category: "payout", source_id: id, description: "STRIPE PAYOUT" }));
  }
  return out.join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-28", "charge", 129.99, 3.97, "Pro plan, annual"],
  ["2026-09-29", "charge", 49.00, 1.72, "Starter plan"],
  ["2026-09-30", "charge", 19.00, 0.85, "Add-on"],
  ["2026-10-01", "charge", 449.99, 13.35, "Team plan"],
  ["2026-10-02", "charge", 19.00, 0.85, "Add-on"],
  ["2026-10-03", "refund", -49.00, 0.00, "Refund: Starter plan"],
  ["2026-10-04", "dispute", -19.00, 15.00, "Dispute: Add-on"],
  ["2026-10-05", "stripe_fee", -4.50, 0.00, "Billing usage fee"],
  ["2026-10-06", "network_cost", -1.20, 0.00, "Card network assessment"],
  ["2026-10-07", "adjustment", 2.00, 0.00, "Courtesy credit"],
];

export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS });
// The same report after a hand edit: a row dropped from the paste so the payout no longer
// agrees, one category no rule recognises and one amount that is not a number.
export function sampleBrokenReport() {
  const total = SAMPLE_ITEMS.reduce((a, r) => a + Math.round((r[2] - r[3]) * 100), 0) / 100;
  const items = SAMPLE_ITEMS.filter((r) => r[1] !== "network_cost");
  items.push(["2026-10-06", "mystery_item", 1.23, 0, "Unknown"], ["2026-10-06", "charge", "12..5", 0, "Typo"]);
  return buildReport({ items, totalOverride: total });
}

engines/upwork.mjs.text:
// Upwork transaction history -> accounting journal.
//
// Upwork keeps a freelancer's money in an Upwork balance. Client payments (hourly, fixed price milestones,
// bonuses) arrive gross, Upwork's service fee comes off as its own negative row, Connects and Freelancer Plus are
// charged to the same balance, and a withdrawal to a bank or PayPal moves the money out. A bookkeeper therefore
// has to book income gross, the fees as an expense, and clear the Upwork balance against the withdrawals.
// This module reads the Upwork Transaction History CSV (Reports > Transaction history > Download CSV: Date,
// Ref ID, Type, Description, ..., Amount, Currency, Balance), books each row by its Type, proves the file is
// complete by walking the Balance column row to row (a missing or edited row breaks the chain), and writes
// balanced journals for Xero, QuickBooks Online, QuickBooks Desktop (IIF) and a plain CSV, one per month.
//
// The export's column names, its Type labels and each importer's layout are from memory of public Upwork and
// accounting help documents; no real Upwork export and no live Xero or QuickBooks import was available when
// this was written. Columns are matched by several aliases, a row no rule explains is never dropped (it lands in
// an "uncategorised" line and is reported), and the Balance check says whether the rows can be trusted.
//
// Everything is integer cents. Nothing here touches the network or the DOM.

export const CATEGORIES = {
  hourly: { label: "Upwork hourly contract earnings (gross)", account: "Upwork Hourly Income" },
  fixed: { label: "Upwork fixed-price and milestone earnings (gross)", account: "Upwork Fixed Price Income" },
  bonus: { label: "Upwork bonuses and tips (gross)", account: "Upwork Bonus Income" },
  fees: { label: "Upwork service, withdrawal and processing fees", account: "Upwork Fees" },
  connects: { label: "Connects, Freelancer Plus and ads", account: "Upwork Connects and Membership" },
  refunds: { label: "Refunds and reversals to clients", account: "Upwork Refunds" },
  withdrawals: { label: "Withdrawals to your bank or PayPal", account: "Bank (Upwork withdrawals)" },
  uncategorised: { label: "Uncategorised Upwork items", account: "Upwork Uncategorised" },
  clearing: { label: "Upwork balance (clearing)", account: "Upwork Balance" },
};
export const CATEGORY_ORDER = Object.keys(CATEGORIES);

export const defaultMapping = () => Object.fromEntries(CATEGORY_ORDER.map((k) => [k, CATEGORIES[k].account]));

// One "key = Account name" per line; blank lines and # comments are ignored.
export function parseMapping(text) {
  const out = defaultMapping(), errors = [];
  String(text || "").split(/\r?\n/).forEach((raw, i) => {
    const line = raw.trim();
    if (!line || line.startsWith("#")) return;
    const m = line.match(/^([a-z]+)\s*[=:]\s*(.+)$/i);
    if (!m) { errors.push(`Line ${i + 1}: expected "category = account", got "${line}"`); return; }
    const key = m[1].toLowerCase();
    if (!CATEGORIES[key]) { errors.push(`Line ${i + 1}: unknown category "${m[1]}" (use ${CATEGORY_ORDER.join(", ")})`); return; }
    out[key] = m[2].trim();
  });
  return { mapping: out, errors };
}
export const mappingText = (mapping = defaultMapping()) => CATEGORY_ORDER.map((k) => `${k} = ${mapping[k]}`).join("\n");

const dollars = (c) => (c < 0 ? "-" : "") + (Math.abs(c) / 100).toFixed(2);
export const money = (c, cur = "USD") => (c < 0 ? "-" : "") + Math.abs(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " " + cur;

// ---- parsing ----------------------------------------------------------------

function splitLine(line, d) {
  const out = []; let cur = "", q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === d) { out.push(cur); cur = ""; }
    else cur += ch;
  }
  out.push(cur);
  return out;
}

const norm = (h) => h.trim().toLowerCase().replace(/^﻿/, "").replace(/[\s_]+/g, "-").replace(/\(.*\)$/, "").replace(/-+$/, "");

// "$1,234.56", "-$12.00", "(12.00)", "USD 5" and European "1.234,56" all read to cents. Empty is null, junk is NaN.
export function parseAmount(s) {
  let t = String(s ?? "").trim().replace(/\s/g, "");
  if (t === "") return null;
  t = t.replace(/^([-+]?)(?:[A-Za-z]{3})/, "$1").replace(/[$€£]/g, "");
  const paren = t.match(/^\((.*)\)$/);
  if (paren) t = "-" + paren[1];
  let u = t;
  if (/^-?\d{1,3}(\.\d{3})+,\d{1,2}$/.test(t)) u = t.replace(/\./g, "").replace(",", ".");
  else if (/^-?\d+,\d{1,2}$/.test(t)) u = t.replace(",", ".");
  else if (/^-?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) u = t.replace(/,/g, "");
  if (!/^-?\d+(\.\d+)?$/.test(u)) return NaN;
  return Math.round(parseFloat(u) * 100);
}

const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };

// Returns YYYY-MM-DD or null. Accepts ISO (with a time), "Sep 28, 2026", DD.MM.YYYY, and slashed dates read per `order`.
export function parseDate(s, order = "mdy") {
  const t = String(s ?? "").trim();
  if (!t) return null;
  let y, m, d, x;
  if ((x = t.match(/^(\d{4})-(\d{2})-(\d{2})/))) [y, m, d] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})/)) && MONTHS[x[1].toLowerCase()]) [m, d, y] = [MONTHS[x[1].toLowerCase()], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})/)) && MONTHS[x[2].toLowerCase()]) [d, m, y] = [x[1], MONTHS[x[2].toLowerCase()], x[3]];
  else if ((x = t.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/))) [d, m, y] = [x[1], x[2], x[3]];
  else if ((x = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) { if (order === "dmy") [d, m, y] = [x[1], x[2], x[3]]; else [m, d, y] = [x[1], x[2], x[3]]; }
  else return null;
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() !== +y || dt.getUTCMonth() !== +m - 1 || dt.getUTCDate() !== +d) return null;
  return `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

// Upwork Type labels, matched loosely and in this order: a "Withdrawal Fee" is a fee, not a withdrawal.
export function rowCategory(type) {
  const t = String(type || "").toLowerCase().trim();
  if (!t) return "uncategorised";
  if (/withdraw.*fee|fee.*withdraw|service fee|processing fee|transaction fee|marketplace fee|\bfee\b/.test(t)) return "fees";
  if (/withdraw|transfer to|payout|direct to|paypal payment/.test(t)) return "withdrawals";
  if (/connect|membership|freelancer plus|subscription|\bads?\b|advertis|boost|proposal/.test(t)) return "connects";
  if (/refund|chargeback|dispute|reversal|clawback|cancel/.test(t)) return "refunds";
  if (/hourly|timesheet|weekly|time\b/.test(t)) return "hourly";
  if (/fixed|milestone|escrow|contract|project|payment/.test(t)) return "fixed";
  if (/bonus|tip/.test(t)) return "bonus";
  return "uncategorised";
}

const ALL = "Upwork";

// The whole file is one account statement. Rows are walked in time order (Upwork lists newest first; the order is
// detected from the Balance column, or from the dates when there is none) so the running Balance can be proved.
// opts.expected, when given, is the balance Upwork shows after the last row.
export function parsePayouts(text, opts = {}) {
  const findings = [];
  const add = (severity, title, detail, line) => findings.push({ severity, title, detail, line: line || 0 });
  const lines = String(text || "").replace(/^﻿/, "").split(/\r?\n/);
  const first = lines.findIndex((l) => l.trim());
  const none = { payouts: [], findings, summary: { rows: 0, payouts: 0 } };
  if (first < 0) { add("error", "The file is empty", "Paste or choose an Upwork transaction history CSV."); return none; }
  const d = (lines[first].match(/\t/g) || []).length > (lines[first].match(/,/g) || []).length ? "\t" : ",";
  const head = splitLine(lines[first], d).map(norm);
  const col = (...names) => { for (const n of names) { const i = head.indexOf(n); if (i >= 0) return i; } return -1; };
  const I = {
    date: col("date", "transaction-date", "date-created", "datetime", "date-time"),
    id: col("ref-id", "reference-id", "reference", "transaction-id", "id", "ref"),
    type: col("type", "transaction-type"),
    desc: col("description", "memo", "details", "contract", "job"),
    amount: col("amount", "amount-in-usd", "usd-amount", "total"),
    currency: col("currency"),
    balance: col("balance", "balance-in-usd", "running-balance"),
  };
  const missing = [];
  if (I.date < 0) missing.push("date");
  if (I.type < 0) missing.push("type");
  if (I.amount < 0) missing.push("amount");
  if (missing.length) {
    add("error", "This does not look like an Upwork transaction history", `Missing column${missing.length > 1 ? "s" : ""}: ${missing.join(", ")}. In Upwork open Reports > Transaction history, choose the date range and Download CSV, then paste the whole file here.`, first + 1);
    return none;
  }
  const get = (cells, k) => (I[k] >= 0 ? (cells[I[k]] ?? "").trim() : "");
  const rows = [];
  let currency = "";
  for (let i = first + 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cells = splitLine(lines[i], d);
    const rid = get(cells, "id") || `line ${i + 1}`;
    const amount = parseAmount(get(cells, "amount")), bal = I.balance >= 0 ? parseAmount(get(cells, "balance")) : null;
    if (amount === null) { add("warning", "Row has no amount", `${rid} was skipped.`, i + 1); continue; }
    if (Number.isNaN(amount) || Number.isNaN(bal)) { add("error", `An amount on ${rid} is not a number`, "The row is left out, so the balance will not add up.", i + 1); continue; }
    const cur = get(cells, "currency").toUpperCase();
    if (cur && currency && cur !== currency) add("warning", "Mixed currencies in the export", `${cur} row among ${currency} rows. Journals assume one currency; Upwork's own Amount column is in your account currency.`, i + 1);
    if (cur && !currency) currency = cur;
    const type = get(cells, "type");
    const key = rowCategory(type);
    const created = parseDate(get(cells, "date"), opts.dateOrder);
    if (!created) add("warning", `Row ${rid} has no readable date`, `"${get(cells, "date")}" was not understood; the row is placed in the final month.`, i + 1);
    rows.push({ line: i + 1, id: rid, item: get(cells, "desc") || type, type, gross: key === "hourly" || key === "fixed" || key === "bonus" ? amount : 0, fee: key === "fees" ? -amount : 0, net: amount, bal, refunded: key === "refunds", parts: [{ k: key, amt: amount }], created });
  }
  if (!rows.length) { add("error", "No transaction rows found", "The header was read but there were no data rows."); return none; }

  // Put the rows in time order. With balances, the order that makes the running balance hold wins.
  const chain = (rs) => rs.reduce((n, r, j) => n + (j > 0 && r.bal !== null && rs[j - 1].bal !== null && rs[j - 1].bal + r.net === r.bal ? 1 : 0), 0);
  const fwd = rows, rev = [...rows].reverse();
  let ordered = fwd;
  const cf = chain(fwd), cr = chain(rev);
  if (cf !== cr) ordered = cr > cf ? rev : fwd;
  else { const a = fwd[0].created, z = fwd[fwd.length - 1].created; if (a && z && a > z) ordered = rev; }

  const haveBal = ordered.every((r) => r.bal !== null);
  let stated = null, opening = null;
  if (haveBal) {
    opening = ordered[0].bal - ordered[0].net;
    stated = ordered[ordered.length - 1].bal - opening;
    for (let j = 1; j < ordered.length; j++) {
      const p = ordered[j - 1], r = ordered[j], off = r.bal - p.bal - r.net;
      if (off !== 0) add("error", `Balance does not follow between ${p.id} and ${r.id}`, `The balance moved by ${money(r.bal - p.bal, currency || "USD")} but ${r.id} is ${money(r.net, currency || "USD")}: ${money(off, currency || "USD")} is missing or was edited (line ${p.line} to ${r.line}). A row may have been dropped from the paste or its amount changed.`, r.line);
    }
    if (opts.expected != null && Number.isFinite(opts.expected) && opts.expected !== ordered[ordered.length - 1].bal) add("warning", "The last balance in the file is not the balance you entered", `The file ends at ${money(ordered[ordered.length - 1].bal, currency || "USD")} but you entered ${money(opts.expected, currency || "USD")}. The export may stop before today, or newer rows are missing.`, 0);
  } else add("warning", "No Balance column, so completeness cannot be proved", "Without the running balance the page cannot tell if a row is missing. Download the full Transaction history (it includes Balance) and paste that.", 0);
  const effective = ordered.map((r) => r.created).filter(Boolean).sort().pop() || null;
  const group = { id: ALL, effective, stated, opening, currency, rows: ordered };
  return { payouts: [group], findings, summary: { rows: ordered.length, payouts: 1 } };
}

// What Upwork cost, against what was billed: the number a freelancer actually wants from the file.
export function feeSummary(payouts) {
  let gross = 0, fees = 0, connects = 0, refunds = 0, withdrawn = 0;
  for (const s of payouts) for (const r of s.rows) for (const p of r.parts) {
    if (p.k === "hourly" || p.k === "fixed" || p.k === "bonus") gross += p.amt;
    else if (p.k === "fees") fees -= p.amt;
    else if (p.k === "connects") connects -= p.amt;
    else if (p.k === "refunds") refunds -= p.amt;
    else if (p.k === "withdrawals") withdrawn -= p.amt;
  }
  return { gross, fees, connects, refunds, withdrawn, feeRate: gross > 0 ? fees / gross : null, allInRate: gross > 0 ? (fees + connects) / gross : null };
}

// ---- journals ----------------------------------------------------------------

const lastDay = (ym) => { const [y, m] = ym.split("-").map(Number); return `${ym}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, "0")}`; };

// split: "month" (default) writes one journal per calendar month a payout touches.
export function buildJournals(payouts, opts = {}) {
  const mapping = opts.mapping || defaultMapping();
  const split = opts.split || "month";
  const findings = [];
  const journals = [];
  for (const s of payouts) {
    const sum = s.rows.reduce((a, r) => a + r.net, 0);
    const cur = s.currency || "USD";
    const endDate = s.effective || [...s.rows].map((r) => r.created).filter(Boolean).sort().pop() || null;
    if (s.stated === null) findings.push({ severity: "warning", title: "The Upwork balance could not be checked", detail: `The rows add up to ${money(sum, cur)}. Without a Balance column the page cannot prove nothing is missing.`, line: 0 });
    else if (s.stated !== sum) findings.push({ severity: "error", title: `Rows add up to ${money(sum, cur)} but the Upwork balance moved by ${money(s.stated, cur)}`, detail: `Off by ${money(s.stated - sum, cur)}. Rows are missing from the paste, or an amount was skipped or edited. Do not post these journals until the figures agree.`, line: 0 });

    const periods = new Map();
    let undated = 0;
    for (const r of s.rows) {
      let ym = r.created ? r.created.slice(0, 7) : (endDate || "").slice(0, 7);
      if (!r.created) undated++;
      if (split === "none") ym = (endDate || ym || "").slice(0, 7);
      if (!ym) ym = "undated";
      if (!periods.has(ym)) periods.set(ym, new Map());
      const m = periods.get(ym);
      const add = (k, amt) => { if (!amt) return; const e = m.get(k) || { net: 0, count: 0 }; e.net += amt; e.count++; m.set(k, e); };
      for (const p of r.parts) add(p.k, p.amt);
    }
    if (undated) findings.push({ severity: "warning", title: `${undated} row${undated === 1 ? "" : "s"} had no readable date`, detail: "They were placed in the final month.", line: 0 });
    const keys = [...periods.keys()].sort();
    if (keys.length > 1) findings.push({ severity: "info", title: `The export spans ${keys.length} months`, detail: `Written as ${keys.length} journals (${keys.join(", ")}), each balanced to the Upwork balance account, so every month's revenue and fees land in the month they happened.`, line: 0 });
    keys.forEach((ym, idx) => {
      const m = periods.get(ym), last = idx === keys.length - 1;
      const date = ym === "undated" ? (endDate || "") : last && endDate && endDate.slice(0, 7) === ym ? endDate : lastDay(ym);
      const lines = [];
      for (const k of CATEGORY_ORDER) {
        if (k === "clearing" || !m.has(k)) continue;
        const { net, count } = m.get(k);
        if (net === 0) continue;
        lines.push({ category: k, account: mapping[k], debit: net < 0 ? -net : 0, credit: net > 0 ? net : 0, memo: `${CATEGORIES[k].label} (${count} row${count === 1 ? "" : "s"})` });
      }
      const net = lines.reduce((a, l) => a + l.credit - l.debit, 0);
      if (net !== 0 || !lines.length) lines.push({ category: "clearing", account: mapping.clearing, debit: net > 0 ? net : 0, credit: net < 0 ? -net : 0, memo: `Change in Upwork balance (${ym})` });
      journals.push({ payoutId: s.id, period: ym, date, deposit: s.effective, currency: cur, narration: `Upwork transactions ${ym}`, lines, clearing: net });
    });
    const unknown = s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised"));
    if (unknown.length) findings.push({ severity: "warning", title: `${unknown.length} item${unknown.length === 1 ? "" : "s"} no rule recognised`, detail: `${[...new Set(unknown.map((r) => r.item || r.id))].slice(0, 5).join(", ")}. They are journalled to "${mapping.uncategorised}" so the journal still equals the net. Review them and reclassify by hand if needed.`, line: unknown[0].line });
  }
  return { journals, findings };
}

export function uncategorisedRows(payouts) {
  return payouts.flatMap((s) => s.rows.filter((r) => r.parts.some((p) => p.k === "uncategorised")).map((r) => ({ payout: s.id, ...r })));
}

export function reconciliation(payouts, journals) {
  return payouts.map((s) => {
    const js = journals.filter((j) => j.payoutId === s.id);
    const sum = js.reduce((a, j) => a + j.clearing, 0);
    return { id: s.id, deposit: s.effective, currency: s.currency || "USD", stated: s.stated, journalled: sum, periods: js.map((j) => ({ period: j.period, date: j.date, clearing: j.clearing })), agrees: s.stated === null ? null : s.stated === sum };
  });
}

export function validate(text, opts = {}) {
  const p = parsePayouts(text, opts);
  const b = buildJournals(p.payouts, opts);
  const findings = [...p.findings, ...b.findings];
  const order = { error: 0, warning: 1, info: 2 };
  findings.sort((a, b2) => order[a.severity] - order[b2.severity]);
  return { payouts: p.payouts, journals: b.journals, findings, reconciliation: reconciliation(p.payouts, b.journals), fees: feeSummary(p.payouts), summary: { ...p.summary, journals: b.journals.length } };
}

// ---- exports -----------------------------------------------------------------

const csvCell = (v) => { const s = String(v ?? ""); return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; };
const csvRow = (a) => a.map(csvCell).join(",");
const fmtDate = (iso, order) => { if (!iso) return ""; const [y, m, d] = iso.split("-"); return order === "dmy" ? `${d}/${m}/${y}` : order === "mdy" ? `${m}/${d}/${y}` : iso; };
const journalsOf = (journals, id) => journals.filter((j) => j.payoutId === id).length;
const docNo = (journals, j) => `${j.payoutId}${j.period && j.period !== "undated" && journalsOf(journals, j.payoutId) > 1 ? "-" + j.period : ""}`;

// Xero manual journal import: debits positive, credits negative.
export function toXeroJournalCsv(journals, o = {}) {
  const tax = o.taxRate || "Tax Exempt";
  const rows = [csvRow(["*Narration", "*Date", "Description", "*AccountCode", "*TaxRate", "*Amount"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.narration, fmtDate(j.date, o.dateOrder || "dmy"), l.memo, l.account, tax, dollars(l.debit - l.credit)]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Online journal entry import.
export function toQboJournalCsv(journals, o = {}) {
  const rows = [csvRow(["*JournalNo", "*JournalDate", "*AccountName", "Debits", "Credits", "Description", "Name", "Currency"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([docNo(journals, j), fmtDate(j.date, o.dateOrder || "mdy"), l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo, "", j.currency]));
  return rows.join("\r\n") + "\r\n";
}

// QuickBooks Desktop IIF general journal: positive = debit, a transaction's lines sum to zero.
export function toIif(journals) {
  const t = (s) => String(s ?? "").replace(/[\t\r\n]+/g, " ");
  const out = ["!TRNS\tTRNSID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!SPL\tSPLID\tTRNSTYPE\tDATE\tACCNT\tAMOUNT\tDOCNUM\tMEMO", "!ENDTRNS"];
  for (const j of journals) {
    const date = fmtDate(j.date, "mdy"), doc = t(docNo(journals, j));
    j.lines.forEach((l, i) => out.push(`${i === 0 ? "TRNS" : "SPL"}\t\tGENERAL JOURNAL\t${date}\t${t(l.account)}\t${((l.debit - l.credit) / 100).toFixed(2)}\t${doc}\t${t(l.memo)}`));
    out.push("ENDTRNS");
  }
  return out.join("\r\n") + "\r\n";
}

export function journalsCsv(journals) {
  const rows = [csvRow(["payout", "period", "date", "category", "account", "debit", "credit", "memo"])];
  for (const j of journals) for (const l of j.lines) rows.push(csvRow([j.payoutId, j.period, j.date, l.category, l.account, l.debit ? dollars(l.debit) : "", l.credit ? dollars(l.credit) : "", l.memo]));
  return rows.join("\r\n") + "\r\n";
}

export function findingsCsv(result) {
  return [csvRow(["severity", "line", "title", "detail"]), ...result.findings.map((f) => csvRow([f.severity, f.line || "", f.title, f.detail]))].join("\r\n") + "\r\n";
}

export function decodeBuffer(buf) {
  const u = new Uint8Array(buf);
  if (u[0] === 0xff && u[1] === 0xfe) return new TextDecoder("utf-16le").decode(u);
  if (u[0] === 0xfe && u[1] === 0xff) return new TextDecoder("utf-16be").decode(u);
  return new TextDecoder("utf-8").decode(u);
}

// ---- samples -----------------------------------------------------------------

const HEAD = ["Date", "Ref ID", "Type", "Description", "Agency", "Freelancer", "Team", "Account Name", "PO", "Amount", "Amount in local currency", "Currency", "Balance", "Balance in local currency"];

// items: [date, type, description, amount] in time order. Upwork lists the newest row first, with the balance
// after each row. `skip` drops rows from the output but keeps the balances, as a hand-edited paste would.
export function buildReport({ currency = "USD", opening = 250, items, skip = [], mangle = {} }) {
  const csv = (v) => (/[",]/.test(String(v)) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
  let bal = Math.round(opening * 100);
  const rows = items.map(([date, type, desc, amt], n) => {
    const cents = Math.round(amt * 100);
    bal += cents;
    const amtText = mangle[n] ?? (cents < 0 ? "-" : "") + (Math.abs(cents) / 100).toFixed(2);
    return [date, `${1000000 + n}`, type, desc, "", "Sam Freelancer", "Sam Freelancer", "", "", amtText, amtText, currency, (bal / 100).toFixed(2), (bal / 100).toFixed(2)].map(csv).join(",");
  });
  const kept = rows.filter((_, n) => !skip.includes(n));
  return [HEAD.join(","), ...kept.reverse()].join("\n") + "\n";
}

const SAMPLE_ITEMS = [
  ["2026-09-18", "Hourly", "Website QA - week 37", 800.00],
  ["2026-09-18", "Service Fee", "Service Fee - Website QA", -80.00],
  ["2026-09-25", "Fixed Price", "Milestone 2 - Dashboard build", 1500.00],
  ["2026-09-25", "Service Fee", "Service Fee - Dashboard build", -150.00],
  ["2026-09-29", "Withdrawal", "Withdrawal to bank", -1800.00],
  ["2026-09-29", "Withdrawal Fee", "Wire fee", -2.00],
  ["2026-09-30", "Connects", "Connects purchase (80)", -12.00],
  ["2026-10-02", "Bonus", "Bonus - Dashboard build", 100.00],
  ["2026-10-02", "Service Fee", "Service Fee - Bonus", -10.00],
  ["2026-10-04", "Hourly", "Website QA - week 39", 640.00],
  ["2026-10-04", "Service Fee", "Service Fee - Website QA", -64.00],
  ["2026-10-05", "Refund", "Refund - Milestone 1", -200.00],
];

export const sampleReport = () => buildReport({ items: SAMPLE_ITEMS });
// The same history after a hand edit: the bonus row dropped from the paste (the balance no longer follows),
// one amount that is not a number, and a type no rule knows.
export function sampleBrokenReport() {
  const items = [...SAMPLE_ITEMS, ["2026-10-06", "Gift Card", "Promotional credit", 5.00], ["2026-10-06", "Hourly", "Website QA - week 40", 0]];
  return buildReport({ items, skip: [7], mangle: { 13: "6..4" } });
}

